#!/bin/sh
# Shrinks the systemd journal to a size and optionally an age limit.
# Variables: MAX_SIZE_MB (default 500), MAX_AGE_DAYS (optional, unset = no age limit).
# Exit codes: 0 done, 1 vacuum failed, 3 bad input or no systemd journal.
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
export PATH
set -u

size=${MAX_SIZE_MB:-500}
age=${MAX_AGE_DAYS:-}
case $size in '' | *[!0-9]*) echo "MAX_SIZE_MB must be a whole number"; exit 3 ;; esac
[ ${#size} -le 6 ] && [ "$size" -ge 1 ] && [ "$size" -le 100000 ] || { echo "MAX_SIZE_MB must be 1-100000"; exit 3; }
if [ -n "$age" ]; then
  case $age in *[!0-9]*) echo "MAX_AGE_DAYS must be a whole number"; exit 3 ;; esac
  [ ${#age} -le 5 ] && [ "$age" -ge 1 ] && [ "$age" -le 36500 ] || { echo "MAX_AGE_DAYS must be 1-36500"; exit 3; }
fi
command -v journalctl >/dev/null 2>&1 || { echo "journalctl not found: this system has no systemd journal"; exit 3; }
[ -d /run/systemd/system ] || [ -d /var/log/journal ] || { echo "No systemd journal on this system"; exit 3; }

before=$(journalctl --disk-usage 2>&1)
journalctl --rotate >/dev/null 2>&1
journalctl --vacuum-size="${size}M" >/dev/null 2>&1 || { echo "Vacuum by size failed"; exit 1; }
if [ -n "$age" ]; then
  journalctl --vacuum-time="${age}d" >/dev/null 2>&1 || { echo "Vacuum by age failed"; exit 1; }
fi
after=$(journalctl --disk-usage 2>&1)
echo "Journal vacuumed to ${size} MB${age:+ and ${age} days}"
echo "Before: $before"
echo "After:  $after"
exit 0

#!/bin/sh
# Shows, starts, stops, restarts, enables or disables one service (systemd or OpenRC); agent and network services are guarded.
# Variables: SERVICE (required, unit or init script name), ACTION (status, start, stop, restart, enable, disable; default status).
# Exit codes: 0 ok (status: running), 1 failed or not running, 3 bad input or no service manager.
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
export PATH
set -u

command -v awk >/dev/null 2>&1 || { echo "awk not found: install gawk"; exit 3; }

svc=${SERVICE:-}
act=${ACTION:-status}
[ -n "$svc" ] || { echo "SERVICE is required"; exit 3; }
case $svc in
-* | *[!A-Za-z0-9_.@:-]*) echo "SERVICE has characters that are not allowed"; exit 3 ;;
esac
[ ${#svc} -le 100 ] || { echo "SERVICE is too long"; exit 3; }
case $act in status | start | stop | restart | enable | disable) ;; *) echo "ACTION must be status, start, stop, restart, enable or disable"; exit 3 ;; esac
case $svc in
ulrmm-agent* | ulrmm-mesh* | meshagent* | 'Mesh Agent')
  case $act in stop | restart | disable)
    echo "Refusing to $act $svc: it would cut the management connection"
    exit 3
    ;;
  esac
  ;;
NetworkManager | NetworkManager.service | systemd-networkd | systemd-networkd.service | networking | networking.service | network | network.service | wicked | wicked.service)
  case $act in stop | disable)
    echo "Refusing to $act $svc: the machine would lose its network and the management connection (use restart)"
    exit 3
    ;;
  esac
  ;;
esac

if [ -d /run/systemd/system ] && command -v systemctl >/dev/null 2>&1; then
  systemctl cat "$svc" >/dev/null 2>&1 || { echo "Service $svc not found"; exit 1; }
  case $act in
  status) ;;
  start | stop | restart) systemctl "$act" "$svc" >/dev/null 2>&1 || { echo "systemctl $act $svc failed"; exit 1; } ;;
  enable | disable)
    systemctl "$act" "$svc" >/dev/null 2>&1 || { echo "systemctl $act $svc failed"; exit 1; }
    ;;
  esac
  active=$(systemctl is-active "$svc" 2>&1)
  enabled=$(systemctl is-enabled "$svc" 2>&1 | head -1)
  echo "$svc: $active, $enabled"
  case $act in
  status | restart | start) [ "$active" = active ] || exit 1 ;;
  stop) [ "$active" != active ] || exit 1 ;;
  enable) case $enabled in enabled | static | alias | indirect) ;; *) exit 1 ;; esac ;;
  disable) [ "$enabled" != enabled ] || exit 1 ;;
  esac
  exit 0
elif command -v rc-service >/dev/null 2>&1; then
  [ -f "/etc/init.d/$svc" ] || { echo "Service $svc not found"; exit 1; }
  case $act in
  status) ;;
  start | restart) rc-service "$svc" "$act" >/dev/null 2>&1 || { echo "rc-service $svc $act failed"; exit 1; } ;;
  stop) rc-service "$svc" stop >/dev/null 2>&1 ;;
  enable) rc-update add "$svc" default >/dev/null 2>&1 || { echo "rc-update add failed"; exit 1; } ;;
  disable) rc-update del "$svc" default >/dev/null 2>&1 || true ;;
  esac
  state=$(rc-service "$svc" status 2>&1 | head -1 | sed 's/^[ *]*status: *//')
  if rc-update show default 2>/dev/null | awk '{print $1}' | grep -qx "$svc"; then en=enabled; else en=disabled; fi
  echo "$svc: $state, $en"
  case $act in
  status | start | restart) rc-service "$svc" status >/dev/null 2>&1 || exit 1 ;;
  stop) rc-service "$svc" status >/dev/null 2>&1 && exit 1 ;;
  enable) [ "$en" = enabled ] || exit 1 ;;
  disable) [ "$en" = disabled ] || exit 1 ;;
  esac
  exit 0
fi
echo "Neither systemd nor OpenRC found"
exit 3

#!/bin/sh
# Checks when the TLS certificates of files (PEM) or host:port endpoints expire.
# Variables: TARGETS (one per line: /path/cert.pem or host:port, required), WARN_DAYS (30), ERROR_DAYS (7)
# Exit: 0 all fine, 1 expired, unreachable or inside ERROR_DAYS, 2 inside WARN_DAYS, 3 bad input or openssl missing
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
export PATH LC_ALL=C
set -u

int() {
  case $2 in '' | *[!0-9]*) echo "$1 must be a whole number"; exit 3 ;; esac
  { [ "${#2}" -le 4 ] && [ "$2" -ge 1 ] && [ "$2" -le 3650 ]; } || { echo "$1 must be between 1 and 3650"; exit 3; }
}
WD=${WARN_DAYS:-30}
ED=${ERROR_DAYS:-7}
int WARN_DAYS "$WD"
int ERROR_DAYS "$ED"
[ "$ED" -lt "$WD" ] || { echo "ERROR_DAYS must be lower than WARN_DAYS"; exit 3; }
LIST=$(printf '%s\n' "${TARGETS:-}" | tr -d '\r' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//;/^$/d')
[ -n "$LIST" ] || { echo "TARGETS is required"; exit 3; }
command -v openssl >/dev/null 2>&1 || { echo "openssl is not installed (install the openssl package)"; exit 3; }

# validate everything before touching anything
printf '%s\n' "$LIST" | while IFS= read -r t; do
  case $t in
  /*) case $t in *[!A-Za-z0-9/._+@-]*) echo "Bad file path: $t"; exit 1 ;; esac ;;
  *:*)
    h=${t%:*} p=${t##*:}
    case $h in '' | -* | *[!A-Za-z0-9.-]*) echo "Bad host: $t"; exit 1 ;; esac
    case $p in '' | *[!0-9]*) echo "Bad port: $t"; exit 1 ;; esac
    [ "${#p}" -le 5 ] && [ "$p" -ge 1 ] && [ "$p" -le 65535 ] || { echo "Bad port: $t"; exit 1; } ;;
  *) echo "Target must be an absolute file path or host:port: $t"; exit 1 ;;
  esac
done || exit 3
tmo=''
command -v timeout >/dev/null 2>&1 && tmo='timeout 20'

nl='
'
rc=0 detail='' n=0
for t in $LIST; do
  n=$((n + 1))
  case $t in
  /*)
    [ -r "$t" ] || { detail="${detail}ERROR $t: not readable$nl"; rc=1; continue; }
    cert=$(openssl x509 -in "$t" 2>/dev/null) ;;
  *)
    h=${t%:*}
    cert=$($tmo openssl s_client -connect "$t" -servername "$h" </dev/null 2>/dev/null | openssl x509 2>/dev/null) ;;
  esac
  [ -n "$cert" ] || { detail="${detail}ERROR $t: no certificate (unreachable, no TLS or not PEM)$nl"; rc=1; continue; }
  end=$(printf '%s\n' "$cert" | openssl x509 -noout -enddate | sed 's/^notAfter=//')
  if ! printf '%s\n' "$cert" | openssl x509 -noout -checkend 0 >/dev/null; then
    detail="${detail}ERROR $t: expired on $end$nl"; rc=1
  elif ! printf '%s\n' "$cert" | openssl x509 -noout -checkend $((ED * 86400)) >/dev/null; then
    detail="${detail}ERROR $t: expires $end (within $ED days)$nl"; rc=1
  elif ! printf '%s\n' "$cert" | openssl x509 -noout -checkend $((WD * 86400)) >/dev/null; then
    detail="${detail}WARN  $t: expires $end (within $WD days)$nl"; [ $rc -eq 0 ] && rc=2
  else
    detail="${detail}ok    $t: expires $end$nl"
  fi
done
case $rc in
0) echo "OK: $n certificates valid for more than $WD days" ;;
1) echo "ERROR: certificate problem, see below" ;;
2) echo "WARNING: a certificate expires within $WD days" ;;
esac
printf '%s' "$detail"
exit $rc

#!/bin/sh
# Checks the 5-minute load average per CPU core against thresholds.
# Variables: WARN_PER_CORE (1.5), ERROR_PER_CORE (3)
# Exit: 0 ok, 1 error threshold reached, 2 warning threshold reached, 3 bad input or unsupported system
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
export PATH
set -u

dec() {
  case $2 in '' | *[!0-9.]* | *.*.* | . | .* | *.) echo "$1 must be a positive number like 1.5"; exit 3 ;; esac
  [ "${#2}" -le 7 ] || { echo "$1 is too long"; exit 3; }
}
# decimal text to hundredths
cent() {
  i=${1%%.*}
  i=$(printf '%s' "$i" | sed 's/^0*//')
  case $1 in *.*) f=${1#*.} ;; *) f= ;; esac
  f=$(printf '%s00' "$f" | cut -c1-2)
  echo $((${i:-0} * 100 + 1$f - 100))
}
WARN=${WARN_PER_CORE:-1.5}
ERR=${ERROR_PER_CORE:-3}
dec WARN_PER_CORE "$WARN"
dec ERROR_PER_CORE "$ERR"
wc100=$(cent "$WARN")
ec100=$(cent "$ERR")
[ "$wc100" -lt "$ec100" ] || { echo "WARN_PER_CORE must be lower than ERROR_PER_CORE"; exit 3; }

[ -r /proc/loadavg ] || { echo "Unsupported: /proc/loadavg not readable"; exit 3; }
cores=$(grep -c '^processor' /proc/cpuinfo 2>/dev/null)
case $cores in '' | 0 | *[!0-9]*) cores=$(nproc 2>/dev/null || echo 1) ;; esac
read -r l1 l5 l15 _ </proc/loadavg
l100=$(cent "$l5")
per=$((l100 / cores))
per=$(printf '%d.%02d' $((per / 100)) $((per % 100)))
msg="load $l1 $l5 $l15 on $cores cores, 5 min per core $per"
if [ "$l100" -ge $((ec100 * cores)) ]; then echo "ERROR: $msg (limit $ERR)"; exit 1; fi
if [ "$l100" -ge $((wc100 * cores)) ]; then echo "WARNING: $msg (limit $WARN)"; exit 2; fi
echo "OK: $msg"

#!/bin/sh
# Tests connectivity: ping for a host, TCP connect for host:port, and an optional DNS lookup.
# Variables: TARGETS (host or host:port, one per line, required), DNS_NAME (name to resolve, optional)
# Exit: 0 everything reachable, 1 at least one test failed, 3 bad input or required tool missing
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
export PATH LC_ALL=C
set -u
command -v awk >/dev/null 2>&1 || { echo "awk is not installed (install gawk or mawk)"; exit 3; }

have() { command -v "$1" >/dev/null 2>&1; }
LIST=$(printf '%s\n' "${TARGETS:-}" | tr ',' '\n' | tr -d '\r' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//;/^$/d')
[ -n "$LIST" ] || { echo "TARGETS is required"; exit 3; }
hostok() { case $1 in '' | -* | *[!A-Za-z0-9.-]*) return 1 ;; esac; }
needping=0 needtcp=0
for t in $LIST; do
  case $t in
  *:*)
    h=${t%:*} p=${t##*:}
    hostok "$h" || { echo "Bad host in target: $t (IPv6 literals are not supported)"; exit 3; }
    case $p in '' | *[!0-9]*) echo "Bad port in target: $t"; exit 3 ;; esac
    { [ "${#p}" -le 5 ] && [ "$p" -ge 1 ] && [ "$p" -le 65535 ]; } || { echo "Port out of range: $t"; exit 3; }
    needtcp=1 ;;
  *) hostok "$t" || { echo "Bad host in target: $t"; exit 3; }; needping=1 ;;
  esac
done
D=${DNS_NAME:-}
[ -z "$D" ] || hostok "$D" || { echo "Bad DNS_NAME: only letters, digits, dots and dashes"; exit 3; }
[ $needping -eq 0 ] || have ping || { echo "Unsupported: ping is not installed (iputils-ping, iputils or inetutils)"; exit 3; }
tcp=''
if [ $needtcp -eq 1 ]; then
  if have nc; then tcp=nc
  elif have curl; then tcp=curl
  else echo "Unsupported: no nc or curl for TCP tests (install netcat-openbsd or curl)"; exit 3; fi
fi

nl='
'
bad='' ok='' n=0
for t in $LIST; do
  n=$((n + 1))
  case $t in
  *:*)
    h=${t%:*} p=${t##*:}
    if [ $tcp = nc ]; then nc -z -w 5 "$h" "$p" >/dev/null 2>&1; else curl -sS -m 5 "telnet://$h:$p" </dev/null >/dev/null 2>&1; fi
    r=$? ;;
  *) ping -c 2 -W 3 "$t" >/dev/null 2>&1 || ping -c 2 -w 6 "$t" >/dev/null 2>&1; r=$? ;;
  esac
  if [ $r -eq 0 ]; then ok="$ok$t "; else bad="$bad$t: unreachable$nl"; fi
done
if [ -n "$D" ]; then
  n=$((n + 1))
  a=''
  if have getent; then a=$(getent ahosts "$D" 2>/dev/null | awk '{print $1}' | sort -u | tr '\n' ' ')
  elif have nslookup; then a=$(nslookup "$D" 2>/dev/null | awk '/^Address/ && !/#/ {print $NF}' | tr '\n' ' ')
  elif have host; then a=$(host "$D" 2>/dev/null | awk '/has address/ {print $NF}' | tr '\n' ' ')
  else echo "Unsupported: no getent, nslookup or host for the DNS test"; exit 3; fi
  if [ -n "$a" ]; then ok="$ok$D=$a"; else bad="$bad$D: DNS lookup failed$nl"; fi
fi
if [ -z "$bad" ]; then
  echo "OK: $n tests passed ($ok)"
  exit 0
fi
echo "ERROR: $(printf '%s' "$bad" | wc -l) of $n tests failed"
printf '%s' "$bad"
exit 1

#!/bin/sh
# Checks data and metadata usage of LVM thin pools.
# Variables: WARN_PERCENT (80), ERROR_PERCENT (90)
# Exit: 0 ok, 1 error threshold reached, 2 warning threshold reached, 3 bad input, no LVM or no thin pools
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
export PATH LC_ALL=C
set -u
command -v awk >/dev/null 2>&1 || { echo "awk is not installed (install gawk or mawk)"; exit 3; }

int() {
  case $2 in '' | *[!0-9]*) echo "$1 must be a whole number"; exit 3 ;; esac
  { [ "${#2}" -le 3 ] && [ "$2" -ge 1 ] && [ "$2" -le 100 ]; } || { echo "$1 must be between 1 and 100"; exit 3; }
}
WARN=${WARN_PERCENT:-80}
ERR=${ERROR_PERCENT:-90}
int WARN_PERCENT "$WARN"
int ERROR_PERCENT "$ERR"
[ "$WARN" -lt "$ERR" ] || { echo "WARN_PERCENT must be lower than ERROR_PERCENT"; exit 3; }
command -v lvs >/dev/null 2>&1 || { echo "Unsupported: LVM tools not installed (lvm2)"; exit 3; }
out=$(lvs --noheadings --separator '|' -o vg_name,lv_name,lv_attr,data_percent,metadata_percent 2>&1) || { echo "Cannot query LVM: $(printf '%s' "$out" | head -n 1)"; exit 3; }
pools=$(printf '%s\n' "$out" | awk -F'|' '{gsub(/^ +/, "", $1); if ($3 ~ /^ *t/) print $1 "/" $2 "|" $4 "|" $5}')
[ -n "$pools" ] || { echo "No LVM thin pools on this system"; exit 3; }
res=$(printf '%s\n' "$pools" | awk -F'|' -v w="$WARN" -v e="$ERR" '{
  d = $2 + 0; m = $3 + 0; s = "ok"
  if (d >= e || m >= e) s = "ERROR"; else if (d >= w || m >= w) s = "WARN"
  printf "%s %s data %.1f%% metadata %.1f%%\n", s, $1, d, m }')
if printf '%s\n' "$res" | grep -q '^ERROR'; then echo "ERROR: thin pool at or above $ERR%"; rc=1
elif printf '%s\n' "$res" | grep -q '^WARN'; then echo "WARNING: thin pool at or above $WARN%"; rc=2
else echo "OK: $(printf '%s\n' "$res" | wc -l) thin pools below $WARN%"; rc=0; fi
printf '%s\n' "$res"
exit $rc

#!/bin/sh
# Adds or removes a managed entry in /etc/hosts (marked with # ulrmm, other lines are never touched).
# Variables: ACTION (add, remove; default add), IP (required for add), ENTRY_HOSTNAME (required).
# Exit codes: 0 done, 1 failed, 3 bad input or the name is already mapped by an unmanaged line.
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
export PATH
set -u

command -v awk >/dev/null 2>&1 || { echo "awk not found: install gawk"; exit 3; }

act=${ACTION:-add}
ip=${IP:-}
hn=${ENTRY_HOSTNAME:-}
case $act in add | remove) ;; *) echo "ACTION must be add or remove"; exit 3 ;; esac
[ -n "$hn" ] || { echo "ENTRY_HOSTNAME is required"; exit 3; }
case $hn in -* | .* | *. | *..* | *[!A-Za-z0-9.-]*) echo "ENTRY_HOSTNAME has characters that are not allowed"; exit 3 ;; esac
[ ${#hn} -le 253 ] || { echo "ENTRY_HOSTNAME is too long"; exit 3; }
[ "$hn" != localhost ] || { echo "Refusing to touch localhost"; exit 3; }
if [ "$act" = add ]; then
  [ -n "$ip" ] || { echo "IP is required"; exit 3; }
  case $ip in *[!0-9A-Fa-f.:]* | '') echo "IP is not an IPv4 or IPv6 address"; exit 3 ;; esac
  case $ip in
  *:*) case $ip in *:::*) echo "IP is not valid"; exit 3 ;; esac ;;
  *)
    printf '%s' "$ip" | grep -Eq '^([0-9]{1,3}\.){3}[0-9]{1,3}$' || { echo "IP is not a valid IPv4 address"; exit 3; }
    if printf '%s' "$ip" | tr '.' '\n' | awk '$1>255 {f=1} END {exit !f}'; then echo "IP is not a valid IPv4 address"; exit 3; fi
    ;;
  esac
fi
[ -f /etc/hosts ] || { echo "/etc/hosts not found"; exit 3; }
tmp=$(mktemp) || exit 1
trap 'rm -f "$tmp"' EXIT
managed=$(awk -v h="$hn" '/# ulrmm$/ && $0 !~ /^#/ {for (i=2;i<=NF;i++) if (tolower($i)==tolower(h)) {print $1; exit}}' /etc/hosts)
other=$(awk -v h="$hn" '$0 !~ /^[ \t]*#/ && $0 !~ /# ulrmm$/ {for (i=2;i<=NF;i++) if (tolower($i)==tolower(h)) {print $1; exit}}' /etc/hosts)
if [ "$act" = add ]; then
  if [ -n "$other" ]; then
    [ "$other" = "$ip" ] && { echo "$hn already maps to $ip"; exit 0; }
    echo "$hn is already mapped to $other by an unmanaged line, remove that line by hand first"
    exit 3
  fi
  [ "$managed" = "$ip" ] && { echo "$hn already maps to $ip"; exit 0; }
  awk -v h="$hn" '/# ulrmm$/ {ok=0; for (i=2;i<=NF;i++) if (tolower($i)==tolower(h)) ok=1; if (ok) next} {print}' /etc/hosts >"$tmp"
  printf '%s\t%s\t# ulrmm\n' "$ip" "$hn" >>"$tmp"
  cat "$tmp" >/etc/hosts || { echo "Writing /etc/hosts failed"; exit 1; }
  grep -q "^$ip	$hn	# ulrmm\$" /etc/hosts || { echo "Entry missing after write"; exit 1; }
  echo "Added $hn -> $ip${managed:+ (replaced $managed)}"
  if grep -Eqs '^[[:space:]]*manage_etc_hosts:[[:space:]]*(true|template|True)' /etc/cloud/cloud.cfg /etc/cloud/cloud.cfg.d/*.cfg; then
    echo "Note: cloud-init rewrites /etc/hosts at every boot (manage_etc_hosts); change /etc/cloud/templates/hosts.*.tmpl as well"
  fi
  exit 0
fi
if [ -z "$managed" ]; then
  [ -n "$other" ] && { echo "$hn is mapped by an unmanaged line, not removing it"; exit 3; }
  echo "$hn has no managed entry, nothing to do"
  exit 0
fi
awk -v h="$hn" '/# ulrmm$/ {ok=0; for (i=2;i<=NF;i++) if (tolower($i)==tolower(h)) ok=1; if (ok) next} {print}' /etc/hosts >"$tmp"
cat "$tmp" >/etc/hosts || { echo "Writing /etc/hosts failed"; exit 1; }
echo "Removed $hn ($managed)"
exit 0

#!/bin/sh
# Adds an SSH public key to a user's authorized_keys (format checked, no duplicates, written as that user).
# Variables: TARGET_USER (required), PUBLIC_KEY (required, one key line without options).
# Exit codes: 0 key in place, 1 failed, 3 bad input or unknown user.
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
export PATH
set -u

command -v awk >/dev/null 2>&1 || { echo "awk not found: install gawk"; exit 3; }

u=${TARGET_USER:-}
key=${PUBLIC_KEY:-}
[ -n "$u" ] || { echo "TARGET_USER is required"; exit 3; }
case $u in [!a-z_]* | *[!a-z0-9_-]*) echo "TARGET_USER has characters that are not allowed"; exit 3 ;; esac
[ -n "$key" ] || { echo "PUBLIC_KEY is required"; exit 3; }
lines=$(printf '%s\n' "$key" | tr -d '\r' | sed '/^[[:space:]]*$/d' | wc -l)
[ "$lines" -eq 1 ] || { echo "PUBLIC_KEY must be exactly one line"; exit 3; }
key=$(printf '%s\n' "$key" | tr -d '\r' | sed '/^[[:space:]]*$/d')
printf '%s\n' "$key" | grep -Eq '^(ssh-ed25519|ssh-rsa|ecdsa-sha2-nistp(256|384|521)|sk-ssh-ed25519@openssh\.com|sk-ecdsa-sha2-nistp256@openssh\.com) [A-Za-z0-9+/]{40,}=*( [[:print:]]*)?$' ||
  { echo "PUBLIC_KEY is not a plain public key line (options such as command= are refused)"; exit 3; }
tmp=$(mktemp) || exit 1
trap 'rm -f "$tmp"' EXIT
printf '%s\n' "$key" >"$tmp"
if command -v ssh-keygen >/dev/null 2>&1; then
  fp=$(ssh-keygen -l -f "$tmp" 2>/dev/null) || { echo "ssh-keygen rejects this key"; exit 3; }
else
  fp="(not verified with ssh-keygen, it is not installed)"
fi
ent=$(getent passwd "$u") || { echo "User $u does not exist"; exit 3; }
home=$(echo "$ent" | cut -d: -f6)
[ -d "$home" ] && [ ! -L "$home" ] && [ "$home" != / ] || { echo "Home directory $home is not usable"; exit 1; }
# Written as the user, so a symlink or hard link the user planted cannot redirect a root write.
# shellcheck disable=SC2016
KEYLINE=$key KEYHOME=$home su -s /bin/sh "$u" -c '
umask 077
cd "$KEYHOME" || exit 4
f=.ssh/authorized_keys
if [ -L .ssh ] || [ -L "$f" ] || { [ -e "$f" ] && [ ! -f "$f" ]; }; then exit 5; fi
mkdir -p .ssh && chmod 700 .ssh || exit 6
b=$(printf "%s\n" "$KEYLINE" | awk "{print \$2}")
if [ -f "$f" ] && awk -v b="$b" "\$2==b || \$3==b {f=1} END {exit !f}" "$f"; then chmod 600 "$f"; exit 10; fi
if [ -s "$f" ] && [ -n "$(tail -c1 "$f")" ]; then printf "\n" >>"$f" || exit 6; fi
printf "%s\n" "$KEYLINE" >>"$f" && chmod 600 "$f" || exit 6
' </dev/null >/dev/null 2>&1
rc=$?
case $rc in
0) new=1 ;;
10) new=0 ;;
4) echo "Home directory $home is not usable"; exit 1 ;;
5) echo "$home/.ssh or its authorized_keys is a symlink or not a regular file, refusing"; exit 1 ;;
*) echo "Writing $home/.ssh/authorized_keys as $u failed (exit $rc): check ownership, or the account is expired"; exit 1 ;;
esac
if [ "$new" = 1 ]; then echo "Key added for $u: $fp"; else echo "Key already present for $u: $fp"; fi
exit 0

#!/bin/sh
# Sets the password of a local user (read from the environment, passed to chpasswd on stdin).
# Variables: TARGET_USER (required), PASSWORD (required, 8-128 characters).
# Exit codes: 0 password set, 1 failed, 3 bad input, unknown user or system account.
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
export PATH
set -u

command -v awk >/dev/null 2>&1 || { echo "awk not found: install gawk"; exit 3; }

u=${TARGET_USER:-}
pw=${PASSWORD:-}
[ -n "$u" ] || { echo "TARGET_USER is required"; exit 3; }
case $u in [!a-z_]* | *[!a-z0-9_-]*) echo "TARGET_USER has characters that are not allowed"; exit 3 ;; esac
[ ${#pw} -ge 8 ] && [ ${#pw} -le 128 ] || { echo "PASSWORD must be 8-128 characters"; exit 3; }
case $pw in *"
"*) echo "PASSWORD must not contain a line break"; exit 3 ;; esac
ent=$(getent passwd "$u") || { echo "User $u does not exist"; exit 3; }
uid=$(echo "$ent" | cut -d: -f3)
umin=$(awk '$1=="UID_MIN" {print $2}' /etc/login.defs 2>/dev/null)
case $umin in '' | *[!0-9]*) umin=1000 ;; esac
if [ "$uid" -ne 0 ] && { [ "$uid" -lt "$umin" ] || [ "$uid" -ge 65534 ]; }; then
  echo "Refusing to set a password for $u: uid $uid is a system account"
  exit 3
fi
command -v chpasswd >/dev/null 2>&1 || { echo "chpasswd not found"; exit 3; }
before=$(awk -F: -v u="$u" '$1==u {print $2}' /etc/shadow)
printf '%s:%s\n' "$u" "$pw" | chpasswd >/dev/null 2>&1 || { echo "chpasswd failed"; exit 1; }
after=$(awk -F: -v u="$u" '$1==u {print $2}' /etc/shadow)
case $after in '' | '!'* | '*'*) echo "Password for $u is still not usable after the change"; exit 1 ;; esac
[ "$after" != "$before" ] || { echo "Password hash unchanged"; exit 1; }
echo "Password for $u set"
exit 0

# Checks whether the Active Directory Recycle Bin is enabled in the forest.
# Variables: none
# Exit: 0 enabled, 1 not enabled, 3 not a domain controller or ActiveDirectory module missing
$ErrorActionPreference = 'Stop'
$cs = Get-CimInstance -ClassName Win32_ComputerSystem
if ($cs.DomainRole -lt 4) {
    Write-Output 'This computer is not a domain controller'
    exit 3
}
if (-not (Get-Module -ListAvailable -Name ActiveDirectory)) {
    Write-Output 'The ActiveDirectory PowerShell module is not installed'
    exit 3
}
try {
    Import-Module ActiveDirectory
    $f = Get-ADOptionalFeature -Filter "Name -eq 'Recycle Bin Feature'"
} catch {
    Write-Output ('Cannot query the forest: ' + $_.Exception.Message)
    exit 3
}
if ($f -and @($f.EnabledScopes).Count -gt 0) {
    Write-Output 'OK: AD Recycle Bin is enabled'
    exit 0
}
Write-Output 'FAIL: AD Recycle Bin is not enabled (enabling is irreversible, do it deliberately)'
exit 1

# Checks Active Directory replication of this domain controller with its partners.
# Variables: none
# Exit: 0 all partners replicate, 1 a replication failure exists, 3 not a domain controller or no AD tooling
$ErrorActionPreference = 'Stop'
$cs = Get-CimInstance -ClassName Win32_ComputerSystem
if ($cs.DomainRole -lt 4) {
    Write-Output 'This computer is not a domain controller'
    exit 3
}
$failures = @()
$lines = @()
if (Get-Module -ListAvailable -Name ActiveDirectory) {
    try {
        Import-Module ActiveDirectory
        $meta = @(Get-ADReplicationPartnerMetadata -Target $env:COMPUTERNAME -Scope Server -Partition *)
    } catch {
        Write-Output ('Cannot read replication metadata: ' + $_.Exception.Message)
        exit 3
    }
    foreach ($m in $meta) {
        $partner = ([string]$m.Partner -split ',')[1] -replace '^CN=', ''
        $lines += ('{0} / {1}: last success {2:yyyy-MM-dd HH:mm}, result {3}, failures {4}' -f $partner, $m.Partition, $m.LastReplicationSuccess, $m.LastReplicationResult, $m.ConsecutiveReplicationFailures)
        if ($m.LastReplicationResult -ne 0 -or $m.ConsecutiveReplicationFailures -gt 0) {
            $failures += ($partner + ' / ' + $m.Partition)
        }
    }
    $count = $meta.Count
} else {
    $exe = Join-Path $env:SystemRoot 'System32\repadmin.exe'
    if (-not (Test-Path $exe)) {
        Write-Output 'Neither the ActiveDirectory module nor repadmin.exe is available'
        exit 3
    }
    $ErrorActionPreference = 'Continue'
    $csv = & $exe /showrepl $env:COMPUTERNAME /csv 2>&1
    $rc = $LASTEXITCODE
    $ErrorActionPreference = 'Stop'
    if ($rc -ne 0) {
        Write-Output ('repadmin failed with exit code ' + $rc)
        exit 3
    }
    $rows = @($csv | ForEach-Object { [string]$_ } | Where-Object { $_ -like 'showrepl_*' } | ConvertFrom-Csv | Where-Object { $_.'Source DSA' })
    foreach ($r in $rows) {
        $n = 0
        [void][int]::TryParse([string]$r.'Number of Failures', [ref]$n)
        $lines += ('{0} / {1}: last success {2}, failures {3}' -f $r.'Source DSA', $r.'Naming Context', $r.'Last Success Time', $n)
        if ($n -gt 0) { $failures += ([string]$r.'Source DSA' + ' / ' + $r.'Naming Context') }
    }
    $count = $rows.Count
}
if ($count -eq 0) {
    Write-Output 'OK: no replication partners (single domain controller)'
    exit 0
}
if ($failures.Count -gt 0) {
    Write-Output ('FAIL: ' + $failures.Count + ' replication failure(s) of ' + $count + ' link(s)')
} else {
    Write-Output ('OK: ' + $count + ' replication link(s) healthy')
}
$lines | ForEach-Object { Write-Output ('  ' + $_) }
if ($failures.Count -gt 0) { exit 1 }
exit 0

# Reports the Entra ID (Azure AD), hybrid and on-premises domain join state from dsregcmd /status.
# Variables: none
# Exit: 0 reported, 3 dsregcmd.exe not available
$ErrorActionPreference = 'Stop'
$exe = Join-Path $env:SystemRoot 'System32\dsregcmd.exe'
if (-not (Test-Path $exe)) {
    Write-Output 'dsregcmd.exe is not available on this system'
    exit 3
}
$ErrorActionPreference = 'Continue'
$out = & $exe /status 2>&1
$rc = $LASTEXITCODE
$ErrorActionPreference = 'Stop'
if ($rc -ne 0) {
    Write-Output ('dsregcmd failed with exit code ' + $rc)
    exit 3
}
$v = @{}
foreach ($line in $out) {
    if (([string]$line) -match '^\s*([A-Za-z]+)\s*:\s*(.*?)\s*$') {
        if (-not $v.ContainsKey($Matches[1])) { $v[$Matches[1]] = $Matches[2] }
    }
}
$aad = $v['AzureAdJoined'] -eq 'YES'
$dom = $v['DomainJoined'] -eq 'YES'
$ws = $v['WorkplaceJoined'] -eq 'YES'
if ($aad -and $dom) { $type = 'hybrid joined (Entra ID and on-premises domain)' }
elseif ($aad) { $type = 'Entra ID joined' }
elseif ($dom) { $type = 'on-premises domain joined only' }
elseif ($ws) { $type = 'Entra ID registered (workplace)' }
else { $type = 'not joined' }
Write-Output ('Join state: ' + $type)
foreach ($k in 'AzureAdJoined', 'DomainJoined', 'WorkplaceJoined', 'EnterpriseJoined', 'TenantName', 'TenantId', 'DeviceId', 'DomainName', 'MdmUrl', 'AzureAdPrt') {
    if ($v.ContainsKey($k) -and $v[$k]) { Write-Output ('{0}: {1}' -f $k, $v[$k]) }
}
exit 0

# Joins this computer to an Active Directory domain. The password is never printed.
# Variables: DOMAIN, DOMAIN_USER (account with join rights), PASSWORD, OU (optional distinguished name), RESTART (checkbox, default false)
# Exit: 0 joined or already a member, 1 join failed, 3 bad input or unsupported system
$ErrorActionPreference = 'Stop'
$domain = ([string]$env:DOMAIN).Trim()
$user = ([string]$env:DOMAIN_USER).Trim()
$password = [string]$env:PASSWORD
$ou = ([string]$env:OU).Trim()
$restart = ([string]$env:RESTART).Trim().ToLower() -eq 'true'
if ($domain -notmatch '^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$') {
    Write-Output 'Bad or missing DOMAIN'
    exit 3
}
if (-not $user -or $user -match '\$$') {
    Write-Output 'Bad or missing DOMAIN_USER'
    exit 3
}
if (-not $password) {
    Write-Output 'PASSWORD is required'
    exit 3
}
if ($ou -and $ou -notmatch '^(OU|CN)=.+') {
    Write-Output 'Bad OU: expected a distinguished name such as OU=Servers,DC=corp,DC=example,DC=com'
    exit 3
}
$cs = Get-CimInstance -ClassName Win32_ComputerSystem
if ($cs.DomainRole -ge 4) {
    Write-Output 'This computer is a domain controller, not joining'
    exit 3
}
if ($cs.PartOfDomain) {
    if ($cs.Domain -ieq $domain -or $cs.Domain.Split('.')[0] -ieq $domain.Split('.')[0]) {
        Write-Output ('Already a member of ' + $cs.Domain + ', nothing changed')
        exit 0
    }
    Write-Output ('Already a member of a different domain: ' + $cs.Domain)
    exit 3
}
try {
    $secure = ConvertTo-SecureString -String $password -AsPlainText -Force
    $cred = New-Object System.Management.Automation.PSCredential($user, $secure)
    $params = @{ DomainName = $domain; Credential = $cred; Force = $true }
    if ($ou) { $params['OUPath'] = $ou }
    Add-Computer @params
} catch {
    Write-Output ('FAIL: ' + $_.Exception.Message)
    exit 1
}
if ($restart) {
    Write-Output ('Joined ' + $domain + ', restarting in 30 seconds')
    & shutdown.exe /r /t 30 /c 'Domain join completed'
} else {
    Write-Output ('Joined ' + $domain + ', a restart is required to finish')
}
exit 0

# Tests the secure channel between this computer and its domain and optionally repairs it. The password is never printed.
# Variables: REPAIR (checkbox, default false), DOMAIN_USER and PASSWORD (domain account allowed to reset the computer account, needed for REPAIR)
# Exit: 0 channel healthy or repaired, 1 channel broken, 3 bad input or not domain joined
$ErrorActionPreference = 'Stop'
$repair = ([string]$env:REPAIR).Trim().ToLower() -eq 'true'
$cs = Get-CimInstance -ClassName Win32_ComputerSystem
if (-not $cs.PartOfDomain) {
    Write-Output 'This computer is not joined to a domain'
    exit 3
}
$cred = $null
if ($repair) {
    $user = ([string]$env:DOMAIN_USER).Trim()
    $password = [string]$env:PASSWORD
    if (-not $user -or $user -match '\$$' -or -not $password) {
        Write-Output 'REPAIR needs DOMAIN_USER and PASSWORD of a domain account'
        exit 3
    }
    $cred = New-Object System.Management.Automation.PSCredential($user, (ConvertTo-SecureString -String $password -AsPlainText -Force))
}
try {
    $ok = Test-ComputerSecureChannel
} catch {
    Write-Output ('FAIL: secure channel test failed: ' + $_.Exception.Message)
    $ok = $false
}
if ($ok) {
    Write-Output ('OK: secure channel to ' + $cs.Domain + ' is healthy')
    exit 0
}
if (-not $repair) {
    Write-Output ('FAIL: secure channel to ' + $cs.Domain + ' is broken')
    exit 1
}
try {
    $fixed = Test-ComputerSecureChannel -Repair -Credential $cred
} catch {
    Write-Output ('FAIL: repair failed: ' + $_.Exception.Message)
    exit 1
}
if ($fixed) {
    Write-Output ('Secure channel to ' + $cs.Domain + ' was repaired')
    exit 0
}
Write-Output 'FAIL: repair did not restore the secure channel'
exit 1

# Prints the last lines of the agent log found in the agent install directory.
# Variables: LINES (optional, default 100, 1-2000)
# Exit: 0 printed, 1 no log file found, 3 bad input or agent not installed
$ErrorActionPreference = 'Stop'
$raw = ([string]$env:LINES).Trim()
$lines = 100
if ($raw) {
    if (-not [int]::TryParse($raw, [ref]$lines) -or $lines -lt 1 -or $lines -gt 2000) {
        Write-Output ('Bad LINES value: ' + $raw + ' (allowed 1-2000)')
        exit 3
    }
}
$dir = Join-Path $env:ProgramFiles 'ULRMM Agent'
if (-not (Test-Path -LiteralPath $dir)) {
    Write-Output ('Agent install directory not found: ' + $dir)
    exit 3
}
$log = Join-Path $dir 'agent.log'
if (-not (Test-Path -LiteralPath $log)) {
    $found = Get-ChildItem -LiteralPath $dir -Filter '*.log' -Recurse -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
    if (-not $found) {
        Write-Output ('No log file found under ' + $dir)
        exit 1
    }
    $log = $found.FullName
}
$info = Get-Item -LiteralPath $log
Write-Output ('{0} ({1:N0} KB, modified {2:yyyy-MM-dd HH:mm})' -f $log, ($info.Length / 1KB), $info.LastWriteTime)
try {
    $tail = @(Get-Content -LiteralPath $log -Tail $lines -Encoding UTF8)
} catch {
    Write-Output ('Cannot read the log: ' + $_.Exception.Message)
    exit 1
}
foreach ($l in $tail) {
    if ($l.Length -gt 1500) { $l = $l.Substring(0, 1500) + ' ...' }
    Write-Output $l
}
exit 0

# Adds Microsoft Defender exclusions for the agent: install directories, working directory and agent processes.
# Variables: none
# Exit: 0 exclusions in place, 1 Defender refused the change (for example another antivirus is active), 3 Defender cmdlets unavailable
$ErrorActionPreference = 'Stop'
if (-not (Get-Command Add-MpPreference -ErrorAction SilentlyContinue)) {
    Write-Output 'Microsoft Defender cmdlets are not available on this system'
    exit 3
}
$paths = @(
    (Join-Path $env:ProgramFiles 'ULRMM Agent'),
    (Join-Path $env:ProgramFiles 'Mesh Agent'),
    (Join-Path $env:ProgramData 'UniversalLocalRMM')
)
$procs = @('ulrmm-agent.exe', 'MeshAgent.exe')
try {
    $pref = Get-MpPreference
    $havePaths = @($pref.ExclusionPath)
    $haveProcs = @($pref.ExclusionProcess)
    foreach ($p in $paths) {
        if ($havePaths -contains $p) {
            Write-Output ('Path already excluded: ' + $p)
        } else {
            Add-MpPreference -ExclusionPath $p
            Write-Output ('Path excluded: ' + $p)
        }
    }
    foreach ($p in $procs) {
        if ($haveProcs -contains $p) {
            Write-Output ('Process already excluded: ' + $p)
        } else {
            Add-MpPreference -ExclusionProcess $p
            Write-Output ('Process excluded: ' + $p)
        }
    }
    $pref = Get-MpPreference
} catch {
    Write-Output ('FAIL: ' + $_.Exception.Message)
    exit 1
}
$missing = @($paths | Where-Object { @($pref.ExclusionPath) -notcontains $_ }) + @($procs | Where-Object { @($pref.ExclusionProcess) -notcontains $_ })
if ($missing.Count -gt 0) {
    Write-Output ('FAIL: not visible after the change: ' + ($missing -join ', '))
    exit 1
}
Write-Output 'OK: all agent exclusions are in place'
exit 0

# Reports the state of the MeshCentral agent service and optionally restarts it.
# Variables: RESTART (checkbox, default false)
# Exit: 0 service running, 1 service not running, 3 bad input or Mesh Agent not installed
$ErrorActionPreference = 'Stop'
$restartRaw = ([string]$env:RESTART).Trim().ToLower()
if ($restartRaw -and $restartRaw -notin 'true', 'false') {
    Write-Output ('Bad RESTART value: ' + $restartRaw)
    exit 3
}
$svc = Get-Service -Name 'Mesh Agent' -ErrorAction SilentlyContinue
if (-not $svc) {
    Write-Output 'Service "Mesh Agent" is not installed'
    exit 3
}
if ($restartRaw -eq 'true') {
    try {
        Restart-Service -Name 'Mesh Agent' -Force
        Write-Output 'Mesh Agent restarted'
    } catch {
        Write-Output ('FAIL: restart failed: ' + $_.Exception.Message)
    }
    $svc = Get-Service -Name 'Mesh Agent'
}
$wmi = Get-CimInstance -ClassName Win32_Service -Filter "Name='Mesh Agent'" -ErrorAction SilentlyContinue
$proc = @(Get-Process -Name 'MeshAgent' -ErrorAction SilentlyContinue)
if ($svc.Status -eq 'Running') {
    Write-Output 'OK: Mesh Agent is running'
} else {
    Write-Output ('FAIL: Mesh Agent is ' + $svc.Status)
}
Write-Output ('Start type: ' + $svc.StartType)
if ($wmi) {
    Write-Output ('Path: ' + $wmi.PathName)
    $exe = ([string]$wmi.PathName).Trim().Trim('"')
    if ($exe -match '^"?([^"]+?\.exe)') { $exe = $Matches[1] }
    if (Test-Path -LiteralPath $exe) {
        Write-Output ('File version: ' + (Get-Item -LiteralPath $exe).VersionInfo.FileVersion)
    }
}
if ($proc.Count -gt 0) {
    Write-Output ('Process started: {0:yyyy-MM-dd HH:mm}' -f $proc[0].StartTime)
}
if ($svc.Status -ne 'Running') { exit 1 }
exit 0

# Reports the antivirus products registered in Security Center with their state; on server editions it falls back
#   to Microsoft Defender status and the uninstall keys.
# Variables: none.
# Exit: 0 an antivirus is active and current, 1 no active antivirus, 2 outdated signatures or several active products.

$rows = @()
$scError = $null
try {
    $products = @(Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntiVirusProduct -ErrorAction Stop)
} catch {
    $scError = $_.Exception.Message
}

if (-not $scError) {
    # productState is undocumented; byte 2 0x10/0x11 means on, byte 3 0x10 means signatures out of date.
    foreach ($a in $products) {
        $state = [uint32]$a.productState
        $rows += [pscustomobject]@{
            Name    = $a.displayName
            On      = (($state -shr 8) -band 0xF0) -eq 0x10
            Current = ($state -band 0xF0) -eq 0
            Detail  = ('state 0x{0:X6}, {1}' -f $state, $a.pathToSignedReportingExe)
        }
    }
} else {
    $mp = $null
    try { $mp = Get-MpComputerStatus -ErrorAction Stop } catch { $mp = $null }
    if ($mp) {
        $rows += [pscustomobject]@{
            Name    = 'Microsoft Defender Antivirus'
            On      = [bool]($mp.AntivirusEnabled -and $mp.RealTimeProtectionEnabled)
            Current = $mp.AntivirusSignatureAge -le 7
            Detail  = "signatures $($mp.AntivirusSignatureAge) day(s) old, real-time $($mp.RealTimeProtectionEnabled)"
        }
    }
    $vendors = '^(ESET|Bitdefender|Kaspersky|Avast|AVG (AntiVirus|Internet)|Avira|Malwarebytes|Sophos|Norton|McAfee|F-Secure|WithSecure|Trend Micro|G DATA|Symantec|Webroot|Panda)'
    $keys = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
    'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    Get-ItemProperty -Path $keys -ErrorAction SilentlyContinue |
        Where-Object { $_.DisplayName -match $vendors -and $_.DisplayName -notmatch 'Management Agent|Remover|Uninstall' } |
        Sort-Object DisplayName -Unique | ForEach-Object {
            $rows += [pscustomobject]@{ Name = $_.DisplayName; On = $true; Current = $true
                Detail = "version $($_.DisplayVersion), installed (state only visible in the vendor console)" }
        }
}

$active = @($rows | Where-Object { $_.On })
if ($active.Count -eq 0) {
    Write-Output 'FAIL: no active antivirus'
    $rc = 1
} elseif (@($active | Where-Object { -not $_.Current }).Count -gt 0) {
    Write-Output "WARNING: signatures out of date: $((@($active | Where-Object { -not $_.Current }) | ForEach-Object { $_.Name }) -join ', ')"
    $rc = 2
} elseif ($active.Count -gt 1 -and -not $scError) {
    Write-Output "WARNING: several active products: $(($active | ForEach-Object { $_.Name }) -join ', ')"
    $rc = 2
} else {
    Write-Output "OK: $(($active | ForEach-Object { $_.Name }) -join ', ')"
    $rc = 0
}
if ($scError) { Write-Output 'Source: Defender status and uninstall keys (no Security Center on this edition)' }
foreach ($r in $rows) {
    $on = if ($r.On) { 'on' } else { 'off' }
    Write-Output "$($r.Name): $on, $($r.Detail)"
}
exit $rc

# Installs a third-party antivirus product unattended, or starts its installer for the signed-in user, after checking
#   the installer's Authenticode publisher.
# Variables: PRODUCT (required) eset-home, eset-endpoint-antivirus, eset-endpoint-security, bitdefender-gravityzone,
#   bitdefender-total-security, kaspersky-endpoint, kaspersky-home, avast-free, avg-free, malwarebytes; MODE (silent;
#   attended starts the vendor wizard in the session of the signed-in user, needs run as user); LICENSE_KEY ("",
#   silent only); INSTALLER_URL ("" = vendor default, https); GZ_PACKAGE_ID ("" GravityZone package id); BIRTH_DATE
#   ("" YYYY-MM-DD, kaspersky-home); ALLOW_EXISTING (false); TIMEOUT_MINUTES (40, silent only).
