# Updates the Microsoft Defender signatures now.
# Variables: none.
# Exit: 0 updated or already current, 1 update failed, 3 Defender not available.

try {
    $before = (Get-MpComputerStatus -ErrorAction Stop).AntivirusSignatureVersion
} catch {
    Write-Output "Microsoft Defender is not available: $($_.Exception.Message)"
    exit 3
}

$ok = $true
try {
    Update-MpSignature -ErrorAction Stop
} catch {
    Write-Output "Update-MpSignature failed: $($_.Exception.Message); trying MpCmdRun"
    $mpcmd = Join-Path $env:ProgramFiles 'Windows Defender\MpCmdRun.exe'
    $out = & cmd.exe /c "`"$mpcmd`" -SignatureUpdate 2>&1"
    $ok = $LASTEXITCODE -eq 0
    $out | Select-Object -Last 3 | ForEach-Object { Write-Output $_ }
}

$s = Get-MpComputerStatus
if (-not $ok) {
    Write-Output "Signature update failed, still at $($s.AntivirusSignatureVersion)"
    exit 1
}
if ($s.AntivirusSignatureVersion -ne $before) {
    Write-Output "Signatures updated: $before -> $($s.AntivirusSignatureVersion)"
} else {
    Write-Output "Signatures already current: $before"
}
Write-Output "Last updated $($s.AntivirusSignatureLastUpdated), engine $($s.AMEngineVersion)"
exit 0

# Checks Microsoft Defender Antivirus: engine running, real-time protection and signature age.
# Variables: WARN_DAYS (2), FAIL_DAYS (7) signature age thresholds in days.
# Exit: 0 ok or another antivirus is active, 1 failing, 2 warning, 3 bad input or Defender not available.

$warnText = "$env:WARN_DAYS".Trim()
$failText = "$env:FAIL_DAYS".Trim()
if (-not $warnText) { $warnText = '2' }
if (-not $failText) { $failText = '7' }
if ($warnText -notmatch '^\d{1,3}$' -or $failText -notmatch '^\d{1,3}$' -or [int]$warnText -gt [int]$failText) {
    Write-Output 'WARN_DAYS and FAIL_DAYS must be whole numbers with WARN_DAYS <= FAIL_DAYS'
    exit 3
}

try {
    $s = Get-MpComputerStatus -ErrorAction Stop
} catch {
    Write-Output "Microsoft Defender is not available: $($_.Exception.Message)"
    exit 3
}

$mode = "$($s.AMRunningMode)"
$age = [int64]$s.AntivirusSignatureAge
$detail = "mode '$mode', real-time $($s.RealTimeProtectionEnabled), signatures $age day(s) old ($($s.AntivirusSignatureVersion)), tamper protection $($s.IsTamperProtected)"

if (-not $s.AntivirusEnabled -or $mode -match 'Passive|Not running') {
    $other = @()
    try {
        $other = @(Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntiVirusProduct -ErrorAction Stop |
                Where-Object { $_.displayName -notmatch '^(Windows|Microsoft) Defender' -and ($_.productState -band 0x1000) } |
                ForEach-Object { $_.displayName })
    } catch {
        $other = @()
    }
    if ($other.Count -gt 0) {
        Write-Output "OK: Defender is not the active antivirus, $($other -join ', ') is"
        Write-Output $detail
        exit 0
    }
    Write-Output 'FAIL: Defender antivirus is off and no other antivirus is active'
    $rc = 1
} elseif (-not $s.RealTimeProtectionEnabled) {
    Write-Output 'FAIL: real-time protection is off'
    $rc = 1
} elseif ($age -ge [int]$failText) {
    Write-Output "FAIL: signatures are $age day(s) old"
    $rc = 1
} elseif ($age -ge [int]$warnText) {
    Write-Output "WARNING: signatures are $age day(s) old"
    $rc = 2
} else {
    Write-Output 'OK: Defender antivirus active and current'
    $rc = 0
}
Write-Output $detail
Write-Output "Engine $($s.AMEngineVersion), platform $($s.AMProductVersion), last quick scan $($s.QuickScanAge) day(s) ago"
exit $rc

# Scans with the ESET command-line scanner (ecls.exe) of an installed ESET product and lists the detections.
# Variables: SCAN_PATH ("" = all local drives) folder or file to scan.
# Exit: 0 clean, 1 threat found or scanner error, 2 some files could not be scanned, 3 bad input or ESET not installed.

$path = "$env:SCAN_PATH".Trim()
if ($path -and ($path -notmatch '^[A-Za-z]:\\' -or $path -match '["*?<>|]')) { Write-Output 'SCAN_PATH must be an absolute local path'; exit 3 }
if ($path -and -not (Test-Path -LiteralPath $path)) { Write-Output "SCAN_PATH does not exist: $path"; exit 3 }

$dir = Join-Path $env:ProgramFiles 'ESET\ESET Security'
$ecls = Join-Path $dir 'ecls.exe'
if (-not (Test-Path -LiteralPath $ecls)) { Write-Output "ESET command-line scanner not found at $ecls"; exit 3 }

$log = Join-Path $env:SystemRoot ('Temp\ecls-' + [Guid]::NewGuid().ToString('N') + '.log')
# Double a trailing backslash, otherwise it escapes the closing quote.
$target = if ($path) { "`"$($path -replace '\\$', '\\')`"" } else { '/auto' }
$argText = "/base-dir=`"$dir\Modules`" /log-file=`"$log`" $target"
$start = Get-Date
$proc = Start-Process -FilePath $ecls -ArgumentList $argText -WindowStyle Hidden -Wait -PassThru
$code = $proc.ExitCode
$minutes = [math]::Round(((Get-Date) - $start).TotalMinutes, 1)

$lines = @()
if (Test-Path -LiteralPath $log) {
    $lines = @(Get-Content -LiteralPath $log -ErrorAction SilentlyContinue)
    Remove-Item -LiteralPath $log -Force -ErrorAction SilentlyContinue
}
switch ($code) {
    0 { Write-Output "CLEAN: no threat found ($minutes min)"; $rc = 0 }
    1 { Write-Output "THREATS: found and cleaned ($minutes min)"; $rc = 1 }
    10 { Write-Output "WARNING: some files could not be scanned ($minutes min)"; $rc = 2 }
    50 { Write-Output "THREATS: found ($minutes min)"; $rc = 1 }
    default { Write-Output "FAIL: ecls.exe exit code $code"; $rc = 1 }
}
$lines | Where-Object { $_ -match 'threat=|result=' -and $_ -notmatch 'threat="(is OK)?"' } | Select-Object -First 30 |
    ForEach-Object { Write-Output $_.Substring(0, [math]::Min(200, $_.Length)) }
$lines | Where-Object { $_ -match '^(Scanned|Infected|Cleaned|Total)' } | ForEach-Object { Write-Output $_ }
exit $rc

