# Prints the hardware serial number alone on the last line, for storing in an RMM custom field.
# Variables: none
# Exit: 0 serial found, 1 the firmware has no usable serial, 3 CIM data unavailable
$ErrorActionPreference = 'Stop'
$junk = '^(0+|none|n/a|default string|system serial number|to be filled by o\.e\.m\.|not specified|not applicable|chassis serial number|base board serial number|123456789.*)$'
try {
    $candidates = @(
        (Get-CimInstance -ClassName Win32_BIOS).SerialNumber,
        (Get-CimInstance -ClassName Win32_BaseBoard).SerialNumber,
        (Get-CimInstance -ClassName Win32_SystemEnclosure).SerialNumber
    )
} catch {
    Write-Output ('Cannot read the serial number: ' + $_.Exception.Message)
    exit 3
}
foreach ($c in $candidates) {
    $s = ([string]$c).Trim()
    if ($s -and $s -notmatch $junk) {
        Write-Output 'Serial number:'
        Write-Output $s
        exit 0
    }
}
Write-Output 'The firmware reports no usable serial number (virtual machine or unbranded board)'
exit 1

# Clears the cache folders of Chrome, Edge and Firefox for every user profile; a running browser is skipped unless FORCE.
# Variables: BROWSER (all) all, chrome, edge or firefox; FORCE (false) close the running browser first.
# Exit: 0 done, 1 a folder could not be cleared, 3 bad input.
$browser = 'all'
if ($env:BROWSER) { $browser = $env:BROWSER.Trim().ToLower() }
if ('all', 'chrome', 'edge', 'firefox' -notcontains $browser) { Write-Output 'BROWSER must be all, chrome, edge or firefox'; exit 3 }
$force = $env:FORCE -eq 'true'

$defs = @(
    @{ Key = 'chrome'; Proc = 'chrome'; Root = 'AppData\Local\Google\Chrome\User Data'; Chromium = $true }
    @{ Key = 'edge'; Proc = 'msedge'; Root = 'AppData\Local\Microsoft\Edge\User Data'; Chromium = $true }
    @{ Key = 'firefox'; Proc = 'firefox'; Root = 'AppData\Local\Mozilla\Firefox\Profiles'; Chromium = $false }
)

function Get-TreeFile([string]$Path) {
    foreach ($i in @(Get-ChildItem -LiteralPath $Path -Force -ErrorAction SilentlyContinue)) {
        if ($i.PSIsContainer) {
            if (-not ($i.Attributes -band [IO.FileAttributes]::ReparsePoint)) { Get-TreeFile $i.FullName }
        } else { $i }
    }
}

$total = [int64]0
$bad = 0
$profiles = @(Get-CimInstance Win32_UserProfile | Where-Object { -not $_.Special -and $_.LocalPath })
foreach ($d in $defs) {
    if ($browser -ne 'all' -and $browser -ne $d.Key) { continue }
    $running = @(Get-Process -Name $d.Proc -ErrorAction SilentlyContinue)
    if ($running.Count -gt 0) {
        if (-not $force) { Write-Output "$($d.Key): running, skipped (set FORCE to close it)"; continue }
        $running | Stop-Process -Force -ErrorAction SilentlyContinue
        Start-Sleep -Seconds 2
    }
    $bytes = [int64]0
    foreach ($p in $profiles) {
        $root = Join-Path $p.LocalPath $d.Root
        if (-not (Test-Path -LiteralPath $root)) { continue }
        $targets = @()
        if ($d.Chromium) {
            foreach ($pd in Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -eq 'Default' -or $_.Name -like 'Profile *' -or $_.Name -eq 'Guest Profile' }) {
                foreach ($c in 'Cache', 'Code Cache', 'GPUCache', 'Service Worker\CacheStorage') { $targets += Join-Path $pd.FullName $c }
            }
        } else {
            foreach ($pd in Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue) {
                foreach ($c in 'cache2', 'startupCache') { $targets += Join-Path $pd.FullName $c }
            }
        }
        foreach ($t in $targets) {
            if (-not (Test-Path -LiteralPath $t)) { continue }
            foreach ($f in @(Get-TreeFile $t)) {
                Remove-Item -LiteralPath $f.FullName -Force -ErrorAction SilentlyContinue
                if (Test-Path -LiteralPath $f.FullName) { $bad++ } else { $bytes += $f.Length }
            }
        }
    }
    Write-Output ("{0}: freed {1:N1} MB" -f $d.Key, ($bytes / 1MB))
    $total += $bytes
}
Write-Output ("Total freed: {0:N1} MB" -f ($total / 1MB))
if ($bad -gt 0) { Write-Output "$bad files could not be removed"; exit 1 }
exit 0

# Frees disk space: Windows temp, user temp folders (files older than a day), update download cache, optional recycle bin and component store cleanup.
# Variables: DRY_RUN (false) only report what would be removed, RECYCLE_BIN (false) empty the recycle bins, COMPONENT_CLEANUP (false) run DISM StartComponentCleanup.
# Exit: 0 done, 1 a step failed.
$ErrorActionPreference = 'Stop'
$dry = $env:DRY_RUN -eq 'true'
$recycle = $env:RECYCLE_BIN -eq 'true'
$component = $env:COMPONENT_CLEANUP -eq 'true'
$failed = $false

function Get-TreeFile([string]$Path) {
    $items = Get-ChildItem -LiteralPath $Path -Force -ErrorAction SilentlyContinue
    foreach ($i in $items) {
        if ($i.PSIsContainer) {
            if (-not ($i.Attributes -band [IO.FileAttributes]::ReparsePoint)) { Get-TreeFile $i.FullName }
        } else { $i }
    }
}

function Remove-EmptyDir([string]$Path) {
    foreach ($d in @(Get-ChildItem -LiteralPath $Path -Directory -Force -ErrorAction SilentlyContinue)) {
        if ($d.Attributes -band [IO.FileAttributes]::ReparsePoint) { continue }
        Remove-EmptyDir $d.FullName
        try { [IO.Directory]::Delete($d.FullName) } catch { $null = $_ }
    }
}

function Clear-Tree([string]$Path, [int]$MinAgeDays) {
    if (-not (Test-Path -LiteralPath $Path)) { return 0 }
    $cut = (Get-Date).AddDays(-$MinAgeDays)
    $bytes = [int64]0
    foreach ($f in @(Get-TreeFile $Path)) {
        if ($f.LastWriteTime -ge $cut) { continue }
        if ($dry) { $bytes += $f.Length; continue }
        Remove-Item -LiteralPath $f.FullName -Force -ErrorAction SilentlyContinue
        if (-not (Test-Path -LiteralPath $f.FullName)) { $bytes += $f.Length }
    }
    if (-not $dry) { Remove-EmptyDir $Path }
    return $bytes
}

function Format-Size([int64]$Bytes) { '{0:N1} MB' -f ($Bytes / 1MB) }

try {
    $sys = $env:SystemDrive
    $freeBefore = (Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='$sys'").FreeSpace
    $total = [int64]0
    $verb = 'Freed'
    if ($dry) { $verb = 'Would free' }

    $b = Clear-Tree (Join-Path $env:windir 'Temp') 1
    Write-Output ("Windows temp: {0} {1}" -f $verb.ToLower(), (Format-Size $b)); $total += $b

    $profiles = Get-CimInstance Win32_UserProfile | Where-Object { -not $_.Special -and $_.LocalPath }
    foreach ($p in $profiles) {
        $t = Join-Path $p.LocalPath 'AppData\Local\Temp'
        $b = Clear-Tree $t 1
        if ($b -gt 0) { Write-Output ("User temp {0}: {1}" -f (Split-Path -Leaf $p.LocalPath), (Format-Size $b)) }
        $total += $b
    }

    $wu = Join-Path $env:windir 'SoftwareDistribution\Download'
    if (Test-Path -LiteralPath $wu) {
        $stopped = @()
        if (-not $dry) {
            foreach ($n in 'wuauserv', 'bits') {
                $s = Get-Service -Name $n -ErrorAction SilentlyContinue
                if ($s -and $s.Status -eq 'Running') {
                    Stop-Service -Name $n -Force -ErrorAction SilentlyContinue
                    $stopped += $n
                    try { $s.WaitForStatus('Stopped', [TimeSpan]::FromSeconds(60)) }
                    catch { Write-Output "$n did not stop in time, its files may stay" }
                }
            }
        }
        try { $b = Clear-Tree $wu 0 }
        finally {
            foreach ($n in $stopped) { Start-Service -Name $n -ErrorAction SilentlyContinue }
        }
        Write-Output ("Update download cache: {0}" -f (Format-Size $b)); $total += $b
    }

    if ($recycle) {
        $rb = [int64]0
        foreach ($d in Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3') {
            $bin = Join-Path ($d.DeviceID + '\') '$Recycle.Bin'
            if (-not (Test-Path -LiteralPath $bin)) { continue }
            foreach ($f in @(Get-TreeFile $bin)) {
                if ($dry) { $rb += $f.Length; continue }
                Remove-Item -LiteralPath $f.FullName -Force -ErrorAction SilentlyContinue
                if (-not (Test-Path -LiteralPath $f.FullName)) { $rb += $f.Length }
            }
        }
        Write-Output ("Recycle bins: {0}" -f (Format-Size $rb)); $total += $rb
    }

    if ($component) {
        if ($dry) {
            Write-Output 'Component cleanup: skipped (dry run)'
        } else {
            $ErrorActionPreference = 'Continue'
            $null = & dism.exe /Online /Cleanup-Image /StartComponentCleanup 2>&1
            $rc = $LASTEXITCODE
            $ErrorActionPreference = 'Stop'
            if ($rc -eq 0) { Write-Output 'Component cleanup: done' }
            else { Write-Output "Component cleanup: DISM exit code $rc"; $failed = $true }
        }
    }

    $freeAfter = (Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='$sys'").FreeSpace
    Write-Output ("{0} in total: {1}; free on {2} {3} -> {4}" -f $verb, (Format-Size $total), $sys, (Format-Size $freeBefore), (Format-Size $freeAfter))
} catch {
    Write-Output "Cleanup failed: $($_.Exception.Message)"
    exit 1
}
if ($failed) { exit 1 }
exit 0

# Stops the print spooler, deletes the queued print jobs and starts the spooler again.
# Variables: none.
# Exit: 0 done, 1 failed, 3 no print spooler on this system.
$svc = Get-Service -Name Spooler -ErrorAction SilentlyContinue
if (-not $svc) { Write-Output 'The Print Spooler service does not exist on this system'; exit 3 }
$deps = @($svc.DependentServices | Where-Object { $_.Status -eq 'Running' } | ForEach-Object { $_.Name })
try {
    if ($svc.Status -ne 'Stopped') {
        Stop-Service -Name Spooler -Force -ErrorAction Stop
        try { $svc.WaitForStatus('Stopped', [TimeSpan]::FromSeconds(30)) }
        catch {
            Get-Process -Name spoolsv -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
            Start-Sleep -Seconds 2
        }
    }
    $dir = Join-Path $env:windir 'System32\spool\PRINTERS'
    $jobs = @(Get-ChildItem -LiteralPath $dir -File -Force -ErrorAction SilentlyContinue)
    $removed = 0
    foreach ($j in $jobs) {
        Remove-Item -LiteralPath $j.FullName -Force -ErrorAction SilentlyContinue
        if (-not (Test-Path -LiteralPath $j.FullName)) { $removed++ }
    }
    Start-Service -Name Spooler -ErrorAction Stop
    foreach ($d in $deps) { Start-Service -Name $d -ErrorAction SilentlyContinue }
    $svc.Refresh()
    Write-Output "Spooler restarted, $removed of $($jobs.Count) queue files removed, service is $($svc.Status)"
    if ($removed -lt $jobs.Count) { exit 1 }
    exit 0
} catch {
    Write-Output "Spooler reset failed: $($_.Exception.Message)"
    Start-Service -Name Spooler -ErrorAction SilentlyContinue
    foreach ($d in $deps) { Start-Service -Name $d -ErrorAction SilentlyContinue }
    exit 1
}

# Restarts or shuts down the computer after an optional delay, or cancels a pending shutdown.
# Variables: MODE (restart) restart, shutdown or cancel; DELAY_MINUTES (0) wait time, 0 to 1440; MESSAGE message shown to users; FORCE (false) close applications without asking (Windows always does so with a delay above 0).
# Exit: 0 done, 1 shutdown.exe failed, 3 bad input.
$mode = 'restart'
if ($env:MODE) { $mode = $env:MODE.Trim().ToLower() }
if ('restart', 'shutdown', 'cancel' -notcontains $mode) { Write-Output 'MODE must be restart, shutdown or cancel'; exit 3 }
$delay = 0
if ($env:DELAY_MINUTES) {
    if (-not [int]::TryParse($env:DELAY_MINUTES.Trim(), [ref]$delay) -or $delay -lt 0 -or $delay -gt 1440) { Write-Output 'DELAY_MINUTES must be a number from 0 to 1440'; exit 3 }
}
$msg = ''
if ($env:MESSAGE) { $msg = $env:MESSAGE.Trim() -replace '["\r\n]', ' ' }
if ($msg.Length -gt 400) { Write-Output 'MESSAGE is longer than 400 characters'; exit 3 }
if ($msg -match '^[/-]') { Write-Output 'MESSAGE must not start with / or -'; exit 3 }

$sd = Join-Path $env:windir 'System32\shutdown.exe'
$arguments = @()
switch ($mode) {
    'cancel' { $arguments = @('/a') }
    'restart' { $arguments = @('/r', '/t', [string]($delay * 60)) }
    'shutdown' { $arguments = @('/s', '/t', [string]($delay * 60)) }
}
if ($mode -ne 'cancel') {
    if ($env:FORCE -eq 'true') { $arguments += '/f' }
    if ($msg) { $arguments += '/c'; $arguments += $msg }
}
$out = & $sd @arguments 2>&1
$rc = $LASTEXITCODE
if ($mode -eq 'cancel') {
    if ($rc -eq 0) { Write-Output 'Pending shutdown cancelled'; exit 0 }
    if ($rc -eq 1116) { Write-Output 'No shutdown was pending'; exit 0 }
} elseif ($rc -eq 0) {
    Write-Output "$mode scheduled in $delay minute(s)"
    exit 0
}
Write-Output "shutdown.exe exit code ${rc}: $($out -join ' ')"
exit 1

# Shows the state of a service or starts, stops or restarts it.
# Variables: SERVICE service name or display name; ACTION (status) status, start, stop or restart.
# Exit: 0 done, 1 the service is not in the wanted state, 3 bad input or unknown service.
$name = ''
if ($env:SERVICE) { $name = $env:SERVICE.Trim() }
if (-not $name -or $name -match '[\*\?\[\]]') { Write-Output 'SERVICE is required and must not contain wildcards'; exit 3 }
$action = 'status'
if ($env:ACTION) { $action = $env:ACTION.Trim().ToLower() }
if ('status', 'start', 'stop', 'restart' -notcontains $action) { Write-Output 'ACTION must be status, start, stop or restart'; exit 3 }

$svc = Get-Service -Name $name -ErrorAction SilentlyContinue
if (-not $svc) { $svc = Get-Service -DisplayName $name -ErrorAction SilentlyContinue | Select-Object -First 1 }
if (-not $svc) { Write-Output "Service '$name' not found"; exit 3 }

function Write-State {
    $svc.Refresh()
    $cim = Get-CimInstance Win32_Service -Filter ("Name='{0}'" -f $svc.Name.Replace("'", "''"))
    Write-Output ("{0} ({1}): {2}, start type {3}" -f $svc.Name, $svc.DisplayName, $svc.Status, $cim.StartMode)
}

try {
    $want = $null
    switch ($action) {
        'start' { if ($svc.Status -ne 'Running') { Start-Service -InputObject $svc -ErrorAction Stop }; $want = 'Running' }
        'stop' { if ($svc.Status -ne 'Stopped') { Stop-Service -InputObject $svc -Force -ErrorAction Stop }; $want = 'Stopped' }
        'restart' { Restart-Service -InputObject $svc -Force -ErrorAction Stop; $want = 'Running' }
    }
    if ($want) { $svc.WaitForStatus($want, [TimeSpan]::FromSeconds(60)) }
    Write-State
    if ($want -and $svc.Status.ToString() -ne $want) { exit 1 }
    exit 0
} catch {
    Write-Output "$action failed: $($_.Exception.Message)"
    Write-State
    exit 1
}

# Checks the component store with DISM and the system files with sfc; in repair mode restores both. Results come from exit codes and DISM health states, not from text.
# Variables: MODE (scan) scan or repair.
# Exit: 0 healthy or repaired, 1 corruption remains or a step failed, 3 bad input.
$mode = 'scan'
if ($env:MODE) { $mode = $env:MODE.Trim().ToLower() }
if ($mode -ne 'scan' -and $mode -ne 'repair') { Write-Output 'MODE must be scan or repair'; exit 3 }
if (-not (Get-Command Repair-WindowsImage -ErrorAction SilentlyContinue)) { Write-Output 'The DISM PowerShell module is not available'; exit 3 }

function Test-SystemFile {
    $tmp = Join-Path $env:windir 'Temp\sfc-verify.txt'
    $p = Start-Process -FilePath (Join-Path $env:windir 'System32\sfc.exe') -ArgumentList '/verifyonly' -Wait -PassThru -NoNewWindow -RedirectStandardOutput $tmp
    Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
    return $p.ExitCode
}

try {
    $restart = $false
    $lines = @()
    $scan = Repair-WindowsImage -Online -ScanHealth -ErrorAction Stop
    $state = $scan.ImageHealthState.ToString()
    $lines += "Component store: $state"
    if ($mode -eq 'repair' -and $state -ne 'Healthy') {
        $fix = Repair-WindowsImage -Online -RestoreHealth -ErrorAction Stop
        if ($fix.RestartNeeded) { $restart = $true }
        $state = (Repair-WindowsImage -Online -ScanHealth -ErrorAction Stop).ImageHealthState.ToString()
        $lines += "Component store after repair: $state"
    }
    if ($mode -eq 'repair') {
        $tmp = Join-Path $env:windir 'Temp\sfc-scan.txt'
        $p = Start-Process -FilePath (Join-Path $env:windir 'System32\sfc.exe') -ArgumentList '/scannow' -Wait -PassThru -NoNewWindow -RedirectStandardOutput $tmp
        Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
        $lines += "sfc /scannow finished, exit code $($p.ExitCode)"
    }
    $rc = Test-SystemFile
    if ($rc -eq 0) { $lines += 'System files: no integrity violations' }
    else { $lines += "System files: sfc /verifyonly exit code $rc (not 0, violations remain or sfc could not finish)" }
    if ($restart) { $lines += 'A restart is needed to finish the repair' }
    if ($state -eq 'Healthy' -and $rc -eq 0) { Write-Output 'RESULT: healthy'; Write-Output $lines; exit 0 }
    Write-Output 'RESULT: corruption found'
    Write-Output $lines
    exit 1
} catch {
    Write-Output "Check failed: $($_.Exception.Message)"
    Write-Output $lines
    exit 1
}

# Looks for bluescreens (bugchecks) in the last days: event 1001 of the system error reporting provider and new dump files.
# Variables: DAYS (7) look back in days.
# Exit: 0 none found, 1 a bluescreen was recorded, 3 bad input.
$days = 7
if ($env:DAYS) { if (-not [int]::TryParse($env:DAYS.Trim(), [ref]$days) -or $days -lt 1 -or $days -gt 365) { Write-Output 'DAYS must be a number from 1 to 365'; exit 3 } }
$since = (Get-Date).AddDays(-$days)
$events = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-WER-SystemErrorReporting'; Id = 1001; StartTime = $since } -ErrorAction SilentlyContinue)
$dumps = @()
$mini = Join-Path $env:windir 'Minidump'
if (Test-Path -LiteralPath $mini) { $dumps += @(Get-ChildItem -LiteralPath $mini -Filter '*.dmp' -File -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -ge $since }) }
$full = Join-Path $env:windir 'MEMORY.DMP'
if (Test-Path -LiteralPath $full) { $dumps += @(Get-Item -LiteralPath $full | Where-Object { $_.LastWriteTime -ge $since }) }
if ($events.Count -eq 0 -and $dumps.Count -eq 0) { Write-Output "OK: no bluescreen in the last $days days"; exit 0 }
Write-Output "CRITICAL: $($events.Count) bugcheck event(s) and $($dumps.Count) dump file(s) in the last $days days"
foreach ($e in $events) {
    $code = ''
    if ($e.Properties.Count -gt 0) { $code = [string]$e.Properties[0].Value }
    Write-Output ("{0:yyyy-MM-dd HH:mm} bugcheck {1}" -f $e.TimeCreated, $code)
}
foreach ($d in $dumps) { Write-Output ("Dump {0}, {1:yyyy-MM-dd HH:mm}, {2:N1} MB" -f $d.FullName, $d.LastWriteTime, ($d.Length / 1MB)) }
exit 1

# Checks that the working set of all instances of a process stays below a limit.
# Variables: PROCESS process name, with or without .exe; MAX_MB memory limit in MB.
# Exit: 0 below the limit or not running, 1 above the limit, 3 bad input.
$name = ''
if ($env:PROCESS) { $name = $env:PROCESS.Trim() -replace '\.exe$', '' }
if ($name -notmatch '^[A-Za-z0-9_. -]{1,64}$') { Write-Output 'PROCESS is required: letters, digits, space, dot, dash and underscore only'; exit 3 }
$max = 0
if (-not $env:MAX_MB -or -not [int]::TryParse($env:MAX_MB.Trim(), [ref]$max) -or $max -lt 1) { Write-Output 'MAX_MB is required and must be a positive number'; exit 3 }
$procs = @(Get-Process -Name $name -ErrorAction SilentlyContinue)
if ($procs.Count -eq 0) { Write-Output "OK: $name is not running"; exit 0 }
$total = ($procs | Measure-Object -Property WorkingSet64 -Sum).Sum / 1MB
$biggest = ($procs | Sort-Object -Property WorkingSet64 -Descending | Select-Object -First 1)
$line = '{0}: {1} instance(s) use {2:N0} MB in total, largest pid {3} with {4:N0} MB, limit {5} MB' -f $name, $procs.Count, $total, $biggest.Id, ($biggest.WorkingSet64 / 1MB), $max
if ($total -gt $max) { Write-Output "CRITICAL: $line"; exit 1 }
Write-Output "OK: $line"
exit 0

# Lists Windows Installer (MSI) installs, removals and reconfigurations of the last hours from the Application log; programs with their own installer are not recorded there.
# Variables: HOURS (24) look back in hours.
# Exit: 0 report printed, 3 bad input.
$hours = 24
if ($env:HOURS) { if (-not [int]::TryParse($env:HOURS.Trim(), [ref]$hours) -or $hours -lt 1 -or $hours -gt 8760) { Write-Output 'HOURS must be a number from 1 to 8760'; exit 3 } }
$kinds = @{ 1033 = 'installed'; 1034 = 'removed'; 1035 = 'reconfigured' }
$events = @(Get-WinEvent -FilterHashtable @{ LogName = 'Application'; ProviderName = 'MsiInstaller'; Id = 1033, 1034, 1035; StartTime = (Get-Date).AddHours(-$hours) } -ErrorAction SilentlyContinue)
if ($events.Count -eq 0) { Write-Output "No MSI install, removal or change in the last $hours hours"; exit 0 }
Write-Output "$($events.Count) MSI change(s) in the last $hours hours"
foreach ($e in ($events | Sort-Object -Property TimeCreated)) {
    $p = $e.Properties
    $product = ''
    $version = ''
    $status = ''
    if ($p.Count -ge 4) { $product = [string]$p[0].Value; $version = [string]$p[1].Value; $status = [string]$p[3].Value }
    Write-Output ("{0:yyyy-MM-dd HH:mm} {1}: {2} {3} (status {4})" -f $e.TimeCreated, $kinds[[int]$e.Id], $product, $version, $status)
}
exit 0

# Checks for users that are logged on with a temporary profile and for broken profile registrations (ProfileList keys ending in .bak).
# Variables: none.
# Exit: 0 healthy, 1 temporary or broken profile found.
$problems = @()
foreach ($p in @(Get-CimInstance Win32_UserProfile | Where-Object { -not $_.Special -and $_.LocalPath })) {
    if ($p.LocalPath -match '\\TEMP(\.[^\\]*)?$') { $problems += "Temporary profile folder $($p.LocalPath), SID $($p.SID), loaded: $($p.Loaded)" }
}
$list = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList'
foreach ($k in @(Get-ChildItem -LiteralPath $list -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -like '*.bak' })) {
    $path = (Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue).ProfileImagePath
    $problems += "ProfileList key $($k.PSChildName) ends in .bak (profile $path is registered twice)"
}
$ev = @(Get-WinEvent -FilterHashtable @{ LogName = 'Application'; ProviderName = 'Microsoft-Windows-User Profiles Service'; Id = 1511; StartTime = (Get-Date).AddDays(-7) } -ErrorAction SilentlyContinue)
if ($problems.Count -eq 0) {
    Write-Output "OK: no temporary profile; $($ev.Count) temporary-profile logon event(s) in the last 7 days"
    exit 0
}
Write-Output "CRITICAL: $($problems.Count) profile problem(s); $($ev.Count) temporary-profile logon event(s) in the last 7 days"
$problems | ForEach-Object { Write-Output $_ }
exit 1

# Lists the top processes by CPU use (measured over 3 seconds) or by memory (working set).
# Variables: TOP (10) number of processes; SORT (cpu) cpu or memory.
# Exit: 0 report printed, 3 bad input.
$top = 10
if ($env:TOP) { if (-not [int]::TryParse($env:TOP.Trim(), [ref]$top) -or $top -lt 1 -or $top -gt 100) { Write-Output 'TOP must be a number from 1 to 100'; exit 3 } }
$sort = 'cpu'
if ($env:SORT) { $sort = $env:SORT.Trim().ToLower() }
if ('cpu', 'memory' -notcontains $sort) { Write-Output 'SORT must be cpu or memory'; exit 3 }
$cores = [int](Get-CimInstance Win32_ComputerSystem).NumberOfLogicalProcessors
$first = @{}
foreach ($p in Get-Process) { if ($null -ne $p.CPU) { $first[$p.Id] = $p.CPU } }
$sec = 3
Start-Sleep -Seconds $sec
$rows = foreach ($p in Get-Process) {
    $pct = 0.0
    if ($first.ContainsKey($p.Id) -and $null -ne $p.CPU) { $pct = [math]::Round(($p.CPU - $first[$p.Id]) / $sec / $cores * 100, 1) }
    [pscustomobject]@{ Name = $p.ProcessName; Id = $p.Id; Cpu = $pct; MemMB = [math]::Round($p.WorkingSet64 / 1MB, 0) }
}
if ($sort -eq 'cpu') { $rows = $rows | Sort-Object -Property Cpu, MemMB -Descending } else { $rows = $rows | Sort-Object -Property MemMB -Descending }
Write-Output "Top $top processes by $sort ($cores logical CPUs, CPU is share of the whole machine)"
foreach ($r in ($rows | Select-Object -First $top)) {
    Write-Output ('{0,-30} pid {1,6}  cpu {2,5}%  mem {3,6} MB' -f $r.Name, $r.Id, $r.Cpu, $r.MemMB)
}
exit 0

# Looks for unexpected shutdowns and restarts in the last days: Kernel-Power event 41 and EventLog event 6008.
# Variables: DAYS (7) look back in days.
# Exit: 0 none found, 1 an unexpected shutdown was recorded, 3 bad input.
$days = 7
if ($env:DAYS) { if (-not [int]::TryParse($env:DAYS.Trim(), [ref]$days) -or $days -lt 1 -or $days -gt 365) { Write-Output 'DAYS must be a number from 1 to 365'; exit 3 } }
$since = (Get-Date).AddDays(-$days)
$kp = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-Kernel-Power'; Id = 41; StartTime = $since } -ErrorAction SilentlyContinue)
$el = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'EventLog'; Id = 6008; StartTime = $since } -ErrorAction SilentlyContinue)
if ($kp.Count -eq 0 -and $el.Count -eq 0) { Write-Output "OK: no unexpected shutdown in the last $days days"; exit 0 }
Write-Output "CRITICAL: $($kp.Count) Kernel-Power 41 and $($el.Count) EventLog 6008 event(s) in the last $days days"
foreach ($e in ($kp + $el | Sort-Object -Property TimeCreated)) {
    $extra = ''
    if ($e.Id -eq 41 -and $e.Properties.Count -gt 0 -and [int64]$e.Properties[0].Value -ne 0) { $extra = ' bugcheck 0x{0:X}' -f [int64]$e.Properties[0].Value }
    Write-Output ("{0:yyyy-MM-dd HH:mm:ss} {1} event {2}{3}" -f $e.TimeCreated, $e.ProviderName, $e.Id, $extra)
}
exit 1

# Tests ping (host) or a TCP connection (host:port) for every target and optionally a DNS lookup.
# Variables: TARGETS one host or host:port per line (comma also works); DNS_NAME name that has to resolve.
# Exit: 0 everything works, 1 at least one test failed, 3 bad input.
$targets = @()
if ($env:TARGETS) { $targets = @($env:TARGETS -split '[,\r\n]+' | ForEach-Object { $_.Trim() } | Where-Object { $_ }) }
$dns = ''
if ($env:DNS_NAME) { $dns = $env:DNS_NAME.Trim() }
if ($targets.Count -eq 0 -and -not $dns) { Write-Output 'Give TARGETS or DNS_NAME'; exit 3 }
if ($dns -and $dns -notmatch '^[A-Za-z0-9._-]{1,253}$') { Write-Output 'DNS_NAME is not a valid host name'; exit 3 }
$failed = 0

function Test-TcpPort([string]$HostName, [int]$Port) {
    $family = [System.Net.Sockets.AddressFamily]::InterNetwork
    if ($HostName.Contains(':')) { $family = [System.Net.Sockets.AddressFamily]::InterNetworkV6 }
    $c = New-Object System.Net.Sockets.TcpClient($family)
    try {
        $iar = $c.BeginConnect($HostName, $Port, $null, $null)
        if (-not $iar.AsyncWaitHandle.WaitOne(5000)) { return 'timeout' }
        $c.EndConnect($iar)
        return 'ok'
    } catch { return 'refused or unreachable' }
    finally { $c.Close() }
}

if ($dns) {
    try {
        $r = @(Resolve-DnsName -Name $dns -DnsOnly -ErrorAction Stop | Where-Object { $_.IPAddress } | ForEach-Object { $_.IPAddress })
        if ($r.Count -eq 0) { throw 'no address records' }
        Write-Output "ok   DNS $dns -> $($r -join ', ')"
    } catch { Write-Output "FAIL DNS ${dns}: $($_.Exception.Message)"; $failed++ }
}
foreach ($t in $targets) {
    $h = $t
    $port = 0
    if ($t -match '^\[([0-9a-fA-F:.]+)\]:([0-9]{1,5})$' -or $t -match '^([A-Za-z0-9._-]+):([0-9]{1,5})$') { $h = $Matches[1]; $port = [int]$Matches[2] }
    if ($h -notmatch '^[A-Za-z0-9._:-]{1,253}$' -or $port -lt 0 -or $port -gt 65535) { Write-Output "FAIL ${t}: not a valid target"; $failed++; continue }
    if ($port -gt 0) {
        $res = Test-TcpPort $h $port
        if ($res -eq 'ok') { Write-Output "ok   TCP ${h}:$port" } else { Write-Output "FAIL TCP ${h}:$port $res"; $failed++ }
    } else {
        $ok = Test-Connection -ComputerName $h -Count 2 -Quiet -ErrorAction SilentlyContinue
        if ($ok) { Write-Output "ok   ping $h" } else { Write-Output "FAIL ping $h"; $failed++ }
    }
}
if ($failed -gt 0) { Write-Output "$failed test(s) failed"; exit 1 }
Write-Output 'All tests passed'
exit 0

# Sets the DNS servers of an adapter (default: the adapters with a default gateway) or returns them to DHCP. Without SERVERS and RESET_TO_DHCP it only reports.
# Variables: SERVERS IP addresses separated by comma, space or line; INTERFACE adapter name; RESET_TO_DHCP (false) use the DHCP-provided servers.
# Exit: 0 done, 1 failed, 3 bad input or no matching adapter.
if ($env:RESET_TO_DHCP -and 'true', 'false' -notcontains $env:RESET_TO_DHCP.Trim()) { Write-Output 'RESET_TO_DHCP must be true or false'; exit 3 }
$reset = $env:RESET_TO_DHCP -and $env:RESET_TO_DHCP.Trim() -eq 'true'
$servers = @()
if ($env:SERVERS -and -not $reset) {
    foreach ($s in ($env:SERVERS -split '[,\s;]+' | Where-Object { $_ })) {
        $ip = $null
        if ($s -notmatch '^(\d{1,3}\.){3}\d{1,3}$|:' -or -not [System.Net.IPAddress]::TryParse($s, [ref]$ip)) { Write-Output "'$s' is not an IP address"; exit 3 }
        $servers += $ip.ToString()
    }
}
$if = ''
if ($env:INTERFACE) { $if = $env:INTERFACE.Trim() }
if ($if -match '[\*\?\[\]]') { Write-Output 'INTERFACE must not contain wildcards'; exit 3 }
try {
    if ($if) {
        $adapters = @(Get-NetAdapter -Name $if -ErrorAction SilentlyContinue)
    } else {
        $adapters = @(Get-NetIPConfiguration | Where-Object { $_.IPv4DefaultGateway -and $_.NetAdapter.Status -eq 'Up' } | ForEach-Object { $_.NetAdapter })
    }
    if ($adapters.Count -eq 0) { Write-Output 'No matching network adapter found'; exit 3 }
    foreach ($a in $adapters) {
        if ($reset) { Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ResetServerAddresses -ErrorAction Stop }
        elseif ($servers.Count -gt 0) { Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ServerAddresses $servers -ErrorAction Stop }
        $now = @(Get-DnsClientServerAddress -InterfaceIndex $a.ifIndex -AddressFamily IPv4 | ForEach-Object { $_.ServerAddresses })
        Write-Output "$($a.Name): $($now -join ', ')"
    }
    if ($reset -or $servers.Count -gt 0) { Clear-DnsClientCache; Write-Output 'DNS cache flushed' }
    exit 0
} catch {
    Write-Output "Failed: $($_.Exception.Message)"
    exit 1
}

# Adds or removes a Windows Firewall port rule. An existing rule with the same name and the same settings counts as done; built-in rule groups are never removed.
# Variables: ACTION (add) add or remove; NAME rule name; PORT number, range (8000-8010) or comma list; PROTOCOL (TCP) TCP or UDP; DIRECTION (inbound) inbound or outbound; RULE_ACTION (allow) allow or block.
# Exit: 0 done or already in place, 1 failed, 3 bad input.
$action = 'add'
if ($env:ACTION) { $action = $env:ACTION.Trim().ToLower() }
if ('add', 'remove' -notcontains $action) { Write-Output 'ACTION must be add or remove'; exit 3 }
$name = ''
if ($env:NAME) { $name = $env:NAME.Trim() }
if ($name -notmatch '^[A-Za-z0-9 ._()-]{1,100}$') { Write-Output 'NAME is required: letters, digits, space and . _ ( ) - only'; exit 3 }
$port = ''
$proto = 'TCP'
$dir = 'inbound'
$verdict = 'allow'
if ($action -eq 'add') {
    if ($env:PORT) { $port = ($env:PORT -replace '\s', '') }
    if ($port -notmatch '^[0-9]{1,5}(-[0-9]{1,5})?(,[0-9]{1,5}(-[0-9]{1,5})?)*$') { Write-Output 'PORT must be a number, a range like 8000-8010 or a comma list'; exit 3 }
    foreach ($n in ($port -split '[,-]')) { if ([int]$n -lt 1 -or [int]$n -gt 65535) { Write-Output 'PORT values must be 1 to 65535'; exit 3 } }
    if ($env:PROTOCOL) { $proto = $env:PROTOCOL.Trim().ToUpper() }
    if ('TCP', 'UDP' -notcontains $proto) { Write-Output 'PROTOCOL must be TCP or UDP'; exit 3 }
    if ($env:DIRECTION) { $dir = $env:DIRECTION.Trim().ToLower() }
    if ('inbound', 'outbound' -notcontains $dir) { Write-Output 'DIRECTION must be inbound or outbound'; exit 3 }
    if ($env:RULE_ACTION) { $verdict = $env:RULE_ACTION.Trim().ToLower() }
    if ('allow', 'block' -notcontains $verdict) { Write-Output 'RULE_ACTION must be allow or block'; exit 3 }
}
try {
    $existing = @(Get-NetFirewallRule -DisplayName $name -ErrorAction SilentlyContinue)
    if ($action -eq 'remove') {
        if ($existing.Count -eq 0) { Write-Output "No rule named '$name', nothing to remove"; exit 0 }
        if (@($existing | Where-Object { $_.Group }).Count -gt 0) { Write-Output "'$name' belongs to a built-in rule group, not removed"; exit 1 }
        $existing | Remove-NetFirewallRule -ErrorAction Stop
        Write-Output "Removed $($existing.Count) rule(s) named '$name'"
        exit 0
    }
    $want = @{ inbound = 'Inbound'; outbound = 'Outbound'; allow = 'Allow'; block = 'Block' }
    if ($existing.Count -gt 0) {
        $r = $existing[0]
        $f = $r | Get-NetFirewallPortFilter
        $have = if ($dir -eq 'inbound') { @($f.LocalPort) -join ',' } else { @($f.RemotePort) -join ',' }
        if ($existing.Count -eq 1 -and $r.Enabled -eq 'True' -and $r.Direction -eq $want[$dir] -and $r.Action -eq $want[$verdict] -and $f.Protocol -eq $proto -and $have -eq $port) {
            Write-Output "Rule '$name' already exists with these settings"
            exit 0
        }
        Write-Output "A rule named '$name' exists with different settings; remove it first"
        exit 1
    }
    $params = @{ DisplayName = $name; Direction = $want[$dir]; Action = $want[$verdict]; Protocol = $proto; Profile = 'Any'; Enabled = 'True' }
    if ($dir -eq 'inbound') { $params.LocalPort = $port -split ',' } else { $params.RemotePort = $port -split ',' }
    New-NetFirewallRule @params -ErrorAction Stop | Out-Null
    Write-Output "Added rule '$name': $verdict $dir $proto $port"
    exit 0
} catch {
    Write-Output "Failed: $($_.Exception.Message)"
    exit 1
}

# Adds or removes a host name in the hosts file. Add makes the name point to the given IP and drops the name from other lines.
# Variables: ACTION (add) add or remove; IP address for add; ENTRY_HOSTNAME host name.
# Exit: 0 done or already in place, 1 failed, 3 bad input.
$action = 'add'
if ($env:ACTION) { $action = $env:ACTION.Trim().ToLower() }
if ('add', 'remove' -notcontains $action) { Write-Output 'ACTION must be add or remove'; exit 3 }
$name = ''
if ($env:ENTRY_HOSTNAME) { $name = $env:ENTRY_HOSTNAME.Trim().ToLower() }
if ($name -notmatch '^[a-z0-9]([a-z0-9._-]{0,251}[a-z0-9])?$') { Write-Output 'ENTRY_HOSTNAME is required and must be a valid host name'; exit 3 }
$ip = ''
if ($action -eq 'add') {
    $parsed = $null
    if (-not $env:IP -or $env:IP.Trim() -notmatch '^(\d{1,3}\.){3}\d{1,3}$|:' -or -not [System.Net.IPAddress]::TryParse($env:IP.Trim(), [ref]$parsed)) { Write-Output 'IP must be a valid IP address'; exit 3 }
    $ip = $parsed.ToString()
}
$path = Join-Path $env:windir 'System32\drivers\etc\hosts'
try {
    $lines = @()
    if (Test-Path -LiteralPath $path) { $lines = @([System.IO.File]::ReadAllLines($path)) }
    $out = New-Object System.Collections.Generic.List[string]
    $changed = $false
    $already = $false
    foreach ($l in $lines) {
        if ($l.IndexOf($name, [StringComparison]::OrdinalIgnoreCase) -lt 0) { $out.Add($l); continue }
        $body = $l
        $comment = ''
        $h = $l.IndexOf('#')
        if ($h -ge 0) { $body = $l.Substring(0, $h); $comment = $l.Substring($h) }
        $tok = @($body -split '\s+' | Where-Object { $_ })
        if ($tok.Count -lt 2 -or ($tok[1..($tok.Count - 1)] | ForEach-Object { $_.ToLower() }) -notcontains $name) { $out.Add($l); continue }
        if ($action -eq 'add' -and $tok[0] -eq $ip -and $tok.Count -eq 2 -and -not $already) { $already = $true; $out.Add($l); continue }
        $rest = @($tok[1..($tok.Count - 1)] | Where-Object { $_.ToLower() -ne $name })
        $changed = $true
        if ($rest.Count -gt 0) {
            $new = $tok[0] + ' ' + ($rest -join ' ')
            if ($comment) { $new += ' ' + $comment }
            $out.Add($new)
        } elseif ($comment) { $out.Add($comment) }
    }
    if ($action -eq 'add' -and -not $already) { $out.Add("$ip`t$name"); $changed = $true }
    if (-not $changed) {
        if ($action -eq 'add') { Write-Output "Already in place: $ip $name" } else { Write-Output "$name is not in the hosts file" }
        exit 0
    }
    [System.IO.File]::WriteAllLines($path, [string[]]$out, (New-Object System.Text.UTF8Encoding $false))
    if ($action -eq 'add') { Write-Output "Hosts entry set: $ip $name" } else { Write-Output "Removed $name from the hosts file" }
    exit 0
} catch {
    Write-Output "Failed: $($_.Exception.Message)"
    exit 1
}

# Reports the IP configuration of every adapter that has an address: status, MAC, addresses, gateway, DNS servers and DHCP.
# Variables: none.
# Exit: 0 report printed, 1 failed.
try {
    $configs = @(Get-NetIPConfiguration -ErrorAction Stop | Where-Object { $_.IPv4Address -or $_.IPv6Address })
    if ($configs.Count -eq 0) { Write-Output 'No adapter with an IP address'; exit 0 }
    Write-Output "$($configs.Count) adapter(s) with an address, host $($env:COMPUTERNAME)"
    foreach ($c in $configs) {
        $a = $c.NetAdapter
        $dhcp = (Get-NetIPInterface -InterfaceIndex $c.InterfaceIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue).Dhcp
        Write-Output "[$($c.InterfaceAlias)] $($a.InterfaceDescription), $($a.Status), $($a.LinkSpeed), MAC $($a.MacAddress)"
        Write-Output ("  IPv4: {0}" -f ((@($c.IPv4Address) | Where-Object { $_ } | ForEach-Object { '{0}/{1}' -f $_.IPAddress, $_.PrefixLength }) -join ', '))
        $v6 = @($c.IPv6Address | Where-Object { $_ } | ForEach-Object { $_.IPAddress })
        if ($v6.Count -gt 0) { Write-Output "  IPv6: $($v6 -join ', ')" }
        Write-Output ("  Gateway: {0}" -f ((@($c.IPv4DefaultGateway) | ForEach-Object { $_.NextHop }) -join ', '))
        Write-Output ("  DNS: {0}; DHCP: {1}" -f (@($c.DNSServer | ForEach-Object { $_.ServerAddresses }) -join ', '), $dhcp)
    }
    exit 0
} catch {
    Write-Output "Failed: $($_.Exception.Message)"
    exit 1
}

# Sets connected networks of category Public to Private; domain networks are left alone.
# Variables: INTERFACE adapter name, empty = every connection.
# Exit: 0 done, 1 failed, 3 bad input or no matching connection.
$if = ''
if ($env:INTERFACE) { $if = $env:INTERFACE.Trim() }
if ($if -match '[\*\?\[\]]') { Write-Output 'INTERFACE must not contain wildcards'; exit 3 }
try {
    $profiles = @(Get-NetConnectionProfile -ErrorAction Stop)
    if ($if) { $profiles = @($profiles | Where-Object { $_.InterfaceAlias -ieq $if }) }
    if ($profiles.Count -eq 0) { Write-Output 'No matching network connection found'; exit 3 }
    foreach ($p in $profiles) {
        if ($p.NetworkCategory -eq 'Public') {
            Set-NetConnectionProfile -InterfaceIndex $p.InterfaceIndex -NetworkCategory Private -ErrorAction Stop
            Write-Output "$($p.InterfaceAlias) ($($p.Name)): Public -> Private"
        } else {
            Write-Output "$($p.InterfaceAlias) ($($p.Name)): already $($p.NetworkCategory)"
        }
    }
    exit 0
} catch {
    Write-Output "Failed: $($_.Exception.Message)"
    exit 1
}

# Network repair step: flush the DNS cache, renew DHCP leases, reset Winsock or reset the TCP/IP stack (the two resets need a restart).
# Variables: ACTION (flush dns) flush dns, renew dhcp, reset winsock or reset tcpip.
# Exit: 0 done, 1 the command failed, 3 bad input.
$action = 'flush dns'
if ($env:ACTION) { $action = $env:ACTION.Trim().ToLower() }
$sys = Join-Path $env:windir 'System32'
switch ($action) {
    'flush dns' { $exe = 'ipconfig.exe'; $arguments = @('/flushdns') }
    'renew dhcp' { $exe = 'ipconfig.exe'; $arguments = @('/renew') }
    'reset winsock' { $exe = 'netsh.exe'; $arguments = @('winsock', 'reset') }
    'reset tcpip' { $exe = 'netsh.exe'; $arguments = @('int', 'ip', 'reset') }
    default { Write-Output 'ACTION must be flush dns, renew dhcp, reset winsock or reset tcpip'; exit 3 }
}
$out = (& (Join-Path $sys $exe) @arguments 2>&1 | Out-String).Trim()
$rc = $LASTEXITCODE
if ($rc -ne 0) { Write-Output "$action failed (exit $rc): $out"; exit 1 }
Write-Output "$action done"
if ($action -like 'reset*') { Write-Output 'Restart the computer to finish the reset' }
exit 0

# Lists the saved Wi-Fi profiles with name, authentication, encryption and connection mode. Keys are never read or printed.
# Variables: none.
# Exit: 0 report printed, 1 a profile could not be read.
$root = Join-Path $env:ProgramData 'Microsoft\Wlansvc\Profiles\Interfaces'
if (-not (Test-Path -LiteralPath $root)) { Write-Output 'No Wi-Fi profiles (no wireless adapter was ever configured)'; exit 0 }
$files = @(Get-ChildItem -LiteralPath $root -Filter '*.xml' -Recurse -File -ErrorAction SilentlyContinue)
if ($files.Count -eq 0) { Write-Output 'No saved Wi-Fi profiles'; exit 0 }
$bad = 0
Write-Output "$($files.Count) saved Wi-Fi profile(s)"
foreach ($f in $files) {
    try {
        $x = [xml](Get-Content -LiteralPath $f.FullName -Raw -Encoding UTF8 -ErrorAction Stop)
        $p = $x.WLANProfile
        $sec = $p.MSM.security
        Write-Output ("{0}: auth {1}, encryption {2}, mode {3}" -f $p.name, $sec.authEncryption.authentication, $sec.authEncryption.encryption, $p.connectionMode)
    } catch {
        Write-Output "Could not read $($f.Name)"
        $bad++
    }
}
if ($bad -gt 0) { exit 1 }
exit 0

# Shows, enables or disables fast startup (hybrid boot). It only has an effect while hibernation is enabled.
# Variables: STATE (status) status, on or off.
# Exit: 0 done, 1 failed, 3 bad input.
$state = 'status'
if ($env:STATE) { $state = $env:STATE.Trim().ToLower() }
if ('status', 'on', 'off' -notcontains $state) { Write-Output 'STATE must be status, on or off'; exit 3 }
$key = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power'
$policy = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\System'
try {
    $cur = (Get-ItemProperty -LiteralPath $key -Name HiberbootEnabled -ErrorAction SilentlyContinue).HiberbootEnabled
    if ($state -ne 'status') {
        $val = 0
        if ($state -eq 'on') { $val = 1 }
        if ($cur -eq $val) { Write-Output "Fast startup is already $state" }
        else {
            New-ItemProperty -LiteralPath $key -Name HiberbootEnabled -Value $val -PropertyType DWord -Force -ErrorAction Stop | Out-Null
            Write-Output "Fast startup turned $state"
        }
        $cur = $val
    }
    $text = 'off'
    if ($cur -eq 1) { $text = 'on' }
    Write-Output "Fast startup: $text"
    $pw = Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\Power' -ErrorAction SilentlyContinue
    $hib = $pw.HibernateEnabled
    if ($null -eq $hib) { $hib = $pw.HibernateEnabledDefault }
    if ($cur -eq 1 -and $hib -ne 1) { Write-Output 'Note: hibernation is disabled, fast startup has no effect until it is enabled' }
    $pol = (Get-ItemProperty -LiteralPath $policy -Name HiberbootEnabled -ErrorAction SilentlyContinue).HiberbootEnabled
    if ($null -ne $pol) { Write-Output "Note: a policy sets HiberbootEnabled to $pol and overrides this value" }
    exit 0
} catch {
    Write-Output "Failed: $($_.Exception.Message)"
    exit 1
}

# Shows, enables or disables hibernation (hiberfil.sys). Disabling it also turns off fast startup.
# Variables: STATE (status) status, on or off.
# Exit: 0 done, 1 powercfg failed, 3 bad input.
$state = 'status'
if ($env:STATE) { $state = $env:STATE.Trim().ToLower() }
if ('status', 'on', 'off' -notcontains $state) { Write-Output 'STATE must be status, on or off'; exit 3 }
$key = 'HKLM:\SYSTEM\CurrentControlSet\Control\Power'

function Get-Hibernate {
    $p = Get-ItemProperty -LiteralPath $key -ErrorAction SilentlyContinue
    if ($null -ne $p.HibernateEnabled) { return [bool]$p.HibernateEnabled }
    [bool]$p.HibernateEnabledDefault
}

$cur = Get-Hibernate
if ($state -eq 'status') {
    Write-Output "Hibernation enabled: $cur"
    exit 0
}
if (($state -eq 'on') -eq $cur) { Write-Output "Hibernation is already $state"; exit 0 }
$out = (& (Join-Path $env:windir 'System32\powercfg.exe') /hibernate $state 2>&1 | Out-String).Trim()
if ($LASTEXITCODE -ne 0) { Write-Output "powercfg failed (exit $LASTEXITCODE): $out"; exit 1 }
$now = Get-Hibernate
Write-Output "Hibernation turned $state, now enabled: $now"
if ($now -ne ($state -eq 'on')) { exit 1 }
exit 0

# Shows the active power plan or activates one; a missing built-in plan is recreated from its template.
# Variables: PLAN (status) status, balanced, high performance, power saver or ultimate.
# Exit: 0 done, 1 failed, 3 bad input.
$plan = 'status'
if ($env:PLAN) { $plan = $env:PLAN.Trim().ToLower() }
$guids = @{
    'balanced'         = '381b4222-f694-41f0-9685-ff5bb260df2e'
    'high performance' = '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c'
    'power saver'      = 'a1841308-3541-4fab-bc81-f71556f20b4a'
    'ultimate'         = 'e9a42b02-d5df-448d-aa00-03f14749eb61'
}
if ($plan -ne 'status' -and -not $guids.ContainsKey($plan)) { Write-Output 'PLAN must be status, balanced, high performance, power saver or ultimate'; exit 3 }
$pc = Join-Path $env:windir 'System32\powercfg.exe'
$guidRe = '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}'

function Get-Active {
    $line = (& $pc /getactivescheme 2>&1 | Out-String).Trim()
    $m = [regex]::Match($line, $guidRe)
    return @{ Guid = $m.Value.ToLower(); Text = $line }
}

$active = Get-Active
if ($plan -eq 'status') { Write-Output $active.Text; exit 0 }
$want = $guids[$plan]
if ($active.Guid -eq $want) { Write-Output "Already active: $($active.Text)"; exit 0 }

$list = (& $pc /list 2>&1 | Out-String).ToLower()
$target = $want
if ($list -notmatch [regex]::Escape($want)) {
    $dup = (& $pc /duplicatescheme $want $want 2>&1 | Out-String)
    if ($LASTEXITCODE -ne 0) { $dup = (& $pc /duplicatescheme $want 2>&1 | Out-String) }
    $m = [regex]::Match($dup, $guidRe)
    if ($LASTEXITCODE -ne 0 -or -not $m.Success) { Write-Output "The plan '$plan' does not exist and could not be created: $($dup.Trim())"; exit 1 }
    $target = $m.Value
    Write-Output "Created the '$plan' plan"
}
$out = (& $pc /setactive $target 2>&1 | Out-String).Trim()
if ($LASTEXITCODE -ne 0) { Write-Output "Could not activate the plan: $out"; exit 1 }
Write-Output "Activated: $((Get-Active).Text)"
exit 0

# Sets the sleep and display timeouts of the active power plan; empty values stay unchanged, 0 means never.
# Variables: AC_SLEEP_MINUTES, DC_SLEEP_MINUTES, AC_DISPLAY_MINUTES, DC_DISPLAY_MINUTES (all empty), 0 to 1440.
# Exit: 0 done, 1 powercfg failed, 3 bad input or nothing to change.
$pc = Join-Path $env:windir 'System32\powercfg.exe'
$items = @(
    @{ Var = 'AC_SLEEP_MINUTES'; Value = $env:AC_SLEEP_MINUTES; Setting = 'standby-timeout-ac' }
    @{ Var = 'DC_SLEEP_MINUTES'; Value = $env:DC_SLEEP_MINUTES; Setting = 'standby-timeout-dc' }
    @{ Var = 'AC_DISPLAY_MINUTES'; Value = $env:AC_DISPLAY_MINUTES; Setting = 'monitor-timeout-ac' }
    @{ Var = 'DC_DISPLAY_MINUTES'; Value = $env:DC_DISPLAY_MINUTES; Setting = 'monitor-timeout-dc' }
)
$todo = @()
foreach ($i in $items) {
    $raw = $i.Value
    if (-not $raw -or -not $raw.Trim()) { continue }
    $n = 0
    if (-not [int]::TryParse($raw.Trim(), [ref]$n) -or $n -lt 0 -or $n -gt 1440) { Write-Output "$($i.Var) must be a number from 0 to 1440"; exit 3 }
    $todo += @{ Setting = $i.Setting; Value = $n; Var = $i.Var }
}
if ($todo.Count -eq 0) { Write-Output 'No timeout given, nothing to change'; exit 3 }
$rc = 0
foreach ($t in $todo) {
    $out = (& $pc /change $t.Setting ([string]$t.Value) 2>&1 | Out-String).Trim()
    if ($LASTEXITCODE -eq 0) { Write-Output "$($t.Var) set to $($t.Value)" }
    else { Write-Output "$($t.Var) failed: $out"; $rc = 1 }
}
Write-Output (& $pc /getactivescheme 2>&1 | Out-String).Trim()
exit $rc

# Installs the OpenSSH server Windows capability, sets the sshd service to automatic and ensures the firewall rule for port 22.
# Variables: none
# Exit: 0 sshd installed and running, 1 install or start failed, 3 Windows version without the capability
$ErrorActionPreference = 'Stop'
if ([Environment]::OSVersion.Version.Build -lt 17763) {
    Write-Output 'OpenSSH server as a Windows capability needs Windows 10 1809 or Server 2019 or newer'
    exit 3
}
try {
    if (-not (Get-Service -Name sshd -ErrorAction SilentlyContinue)) {
        $cap = Get-WindowsCapability -Online | Where-Object { $_.Name -like 'OpenSSH.Server*' } | Select-Object -First 1
        if (-not $cap) {
            Write-Output 'The OpenSSH.Server capability is not offered on this system'
            exit 3
        }
        if ([string]$cap.State -ne 'Installed') {
            Write-Output ('Installing ' + $cap.Name + ' (needs Windows Update or a reachable feature source)')
            [void](Add-WindowsCapability -Online -Name $cap.Name)
        }
    } else {
        Write-Output 'sshd service already present'
    }
    Set-Service -Name sshd -StartupType Automatic
    if ((Get-Service -Name sshd).Status -ne 'Running') {
        Start-Service -Name sshd
        Write-Output 'sshd started'
    }
    $rule = Get-NetFirewallRule -Name 'OpenSSH-Server-In-TCP' -ErrorAction SilentlyContinue
    if (-not $rule) {
        [void](New-NetFirewallRule -Name 'OpenSSH-Server-In-TCP' -DisplayName 'OpenSSH Server (sshd)' -Enabled True -Direction Inbound -Protocol TCP -Action Allow -LocalPort 22)
        Write-Output 'Firewall rule created for TCP 22'
    } elseif ([string]$rule.Enabled -ne 'True') {
        Enable-NetFirewallRule -Name 'OpenSSH-Server-In-TCP'
        Write-Output 'Firewall rule enabled'
    }
} catch {
    Write-Output ('FAIL: ' + $_.Exception.Message)
    exit 1
}
$svc = Get-Service -Name sshd
Write-Output ('OK: sshd is ' + $svc.Status + ', start type ' + $svc.StartType + ', firewall rule in place')
exit 0

# Shows, enables or disables Remote Desktop, including Network Level Authentication and the firewall rule group.
# Variables: STATE (status, enable or disable; default status), NLA (checkbox, default true, applied when enabling)
# Exit: 0 done or reported, 1 change failed, 3 bad input or Remote Desktop not available (Home edition)
$ErrorActionPreference = 'Stop'
$state = ([string]$env:STATE).Trim().ToLower()
if (-not $state) { $state = 'status' }
if ($state -notin 'status', 'enable', 'disable') {
    Write-Output ('Bad STATE value: ' + $state)
    exit 3
}
$nlaRaw = ([string]$env:NLA).Trim().ToLower()
if ($nlaRaw -and $nlaRaw -notin 'true', 'false') {
    Write-Output ('Bad NLA value: ' + $nlaRaw)
    exit 3
}
$nla = $nlaRaw -ne 'false'
$ts = 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server'
$rdp = $ts + '\WinStations\RDP-Tcp'
$sku = [int](Get-CimInstance -ClassName Win32_OperatingSystem).OperatingSystemSKU
if (($sku -in 98, 99, 100, 101) -or -not (Test-Path $rdp)) {
    Write-Output 'Remote Desktop hosting is not available on this edition (Windows Home)'
    exit 3
}
# language-neutral identifier of the "Remote Desktop" firewall group
$group = '@FirewallAPI.dll,-28752'
try {
    if ($state -eq 'enable') {
        [void](New-ItemProperty -Path $ts -Name fDenyTSConnections -Value 0 -PropertyType DWord -Force)
        [void](New-ItemProperty -Path $rdp -Name UserAuthentication -Value ([int]$nla) -PropertyType DWord -Force)
        Enable-NetFirewallRule -Group $group
        Write-Output ('Remote Desktop enabled, NLA=' + $nla + ', firewall group enabled')
    } elseif ($state -eq 'disable') {
        [void](New-ItemProperty -Path $ts -Name fDenyTSConnections -Value 1 -PropertyType DWord -Force)
        Disable-NetFirewallRule -Group $group
        Write-Output 'Remote Desktop disabled, firewall group disabled'
    }
    $deny = (Get-ItemProperty -Path $ts -Name fDenyTSConnections).fDenyTSConnections
    $auth = (Get-ItemProperty -Path $rdp -Name UserAuthentication).UserAuthentication
    $rules = @(Get-NetFirewallRule -Group $group -ErrorAction SilentlyContinue)
    $on = @($rules | Where-Object { [string]$_.Enabled -eq 'True' }).Count
} catch {
    Write-Output ('FAIL: ' + $_.Exception.Message)
    exit 1
}
$policy = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\Terminal Services' -ErrorAction SilentlyContinue
if ($policy -and $null -ne $policy.fDenyTSConnections) {
    $deny = $policy.fDenyTSConnections
    Write-Output 'Remote Desktop is set by group policy, the policy value applies'
}
$enabled = $deny -eq 0
Write-Output ('Remote Desktop: ' + $(if ($enabled) { 'enabled' } else { 'disabled' }))
Write-Output ('Network Level Authentication: ' + $(if ($auth -eq 1) { 'required' } else { 'not required' }))
Write-Output ('Firewall rules enabled in the group: ' + $on + ' of ' + $rules.Count)
if (($state -eq 'enable' -and -not $enabled) -or ($state -eq 'disable' -and $enabled)) { exit 1 }
exit 0

# Prints the BitLocker numerical recovery password of a drive on the last line, to store it in an RMM custom field.
# Variables: DRIVE (optional, default the system drive, e.g. C:)
# Exit: 0 key printed, 1 volume has no recovery password, 3 bad input or BitLocker unavailable
$ErrorActionPreference = 'Stop'
$drive = ([string]$env:DRIVE).Trim()
