if ($drive -notmatch '^[A-Za-z]:?\\?$') {
    Write-Output ('Bad DRIVE value: ' + $drive)
    exit 3
}
$drive = $drive.Substring(0, 1).ToUpper() + ':'
if (-not (Get-Command Get-BitLockerVolume -ErrorAction SilentlyContinue)) {
