}
exit 2

# Checks whether a restart is pending (servicing stack, Windows Update, file renames, computer rename).
# Variables: none
# Exit: 0 no restart pending, 2 restart pending
$ErrorActionPreference = 'Stop'
$reasons = @()
if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') {
    $reasons += 'component servicing'
}
if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') {
    $reasons += 'Windows Update'
}
$sm = Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -ErrorAction SilentlyContinue
if ($sm -and $sm.PendingFileRenameOperations) {
    $reasons += 'pending file rename operations'
}
$names = 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName'
$active = (Get-ItemProperty -Path ($names + '\ActiveComputerName') -ErrorAction SilentlyContinue).ComputerName
$new = (Get-ItemProperty -Path ($names + '\ComputerName') -ErrorAction SilentlyContinue).ComputerName
if ($active -and $new -and $active -ne $new) {
    $reasons += 'computer rename'
}
if ($reasons.Count -gt 0) {
    Write-Output ('WARNING: restart pending: ' + ($reasons -join ', '))
    exit 2
}
Write-Output 'OK: no restart pending'
exit 0

# Reports Secure Boot state, firmware type and TPM presence and readiness.
# Variables: none
# Exit: 0 Secure Boot on and TPM ready, 2 Secure Boot off or unsupported or no usable TPM
$ErrorActionPreference = 'Stop'
$problems = @()

$boot = 'unknown'
try {
    if (Confirm-SecureBootUEFI) { $boot = 'enabled' } else { $boot = 'disabled' }
} catch {
    $boot = 'not supported (legacy BIOS boot or no UEFI)'
}
if ($boot -ne 'enabled') { $problems += 'Secure Boot ' + $boot }
Write-Output ('Secure Boot: ' + $boot)

$tpmText = 'not present'
$ready = $false
try {
    $t = Get-CimInstance -Namespace 'root\cimv2\Security\MicrosoftTpm' -ClassName Win32_Tpm
    if ($t) {
        $ver = ([string]$t.SpecVersion).Split(',')[0]
        $ready = [bool]$t.IsEnabled_InitialValue -and [bool]$t.IsActivated_InitialValue
        $tpmText = 'spec ' + $ver + ', enabled=' + $t.IsEnabled_InitialValue + ', activated=' + $t.IsActivated_InitialValue + ', manufacturer=' + $t.ManufacturerIdTxt
    }
} catch {
    $tpmText = 'not present or not readable'
}
if (-not $ready) { $problems += 'TPM ' + $tpmText }
Write-Output ('TPM: ' + $tpmText)

if ($problems.Count -gt 0) {
    Write-Output ('WARNING: ' + ($problems -join '; '))
    exit 2
}
Write-Output 'OK: Secure Boot is on and the TPM is ready'
exit 0

# Reports whether the SMBv1 server protocol is enabled and optionally disables it (server protocol and optional feature).
# Variables: DISABLE (checkbox, default false)
# Exit: 0 SMBv1 is off, 1 SMBv1 is on or could not be disabled, 3 bad input or SMB cmdlets unavailable
$ErrorActionPreference = 'Stop'
$disable = ([string]$env:DISABLE).Trim().ToLower()
if ($disable -and $disable -notin 'true', 'false') {
    Write-Output ('Bad DISABLE value: ' + $disable)
    exit 3
}
if (-not (Get-Command Get-SmbServerConfiguration -ErrorAction SilentlyContinue)) {
    Write-Output 'SMB cmdlets are not available on this system'
    exit 3
}

function Get-FeatureState {
    if (-not (Get-Command Get-WindowsOptionalFeature -ErrorAction SilentlyContinue)) { return 'unknown' }
    try {
        $f = Get-WindowsOptionalFeature -Online -FeatureName SMB1Protocol -ErrorAction Stop
        return [string]$f.State
    } catch {
        return 'unknown'
    }
}

try {
    $before = [bool](Get-SmbServerConfiguration).EnableSMB1Protocol
    $featureBefore = Get-FeatureState
    if ($disable -eq 'true') {
        if ($before) {
            Set-SmbServerConfiguration -EnableSMB1Protocol $false -Force
            Write-Output 'SMBv1 server protocol disabled'
        }
        if ($featureBefore -eq 'Enabled') {
            [void](Disable-WindowsOptionalFeature -Online -FeatureName SMB1Protocol -NoRestart)
            Write-Output 'SMB1Protocol feature removed, takes full effect after a restart'
        }
    }
    $after = [bool](Get-SmbServerConfiguration).EnableSMB1Protocol
} catch {
    Write-Output ('FAIL: ' + $_.Exception.Message)
    exit 1
}
if ($after) {
    Write-Output 'FAIL: SMBv1 server protocol is enabled'
    exit 1
}
Write-Output 'OK: SMBv1 server protocol is disabled'
Write-Output ('Optional feature SMB1Protocol: ' + (Get-FeatureState))
exit 0

# Checks that User Account Control is enabled and reports its policy settings.
# Variables: none
# Exit: 0 UAC enabled, 1 UAC disabled, 3 policy key unreadable
$ErrorActionPreference = 'Stop'
$key = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System'
try {
    $p = Get-ItemProperty -Path $key
} catch {
    Write-Output ('Cannot read ' + $key)
    exit 3
}
$lua = $p.EnableLUA
$prompt = $p.ConsentPromptBehaviorAdmin
$names = @{
    0 = 'elevate without prompting'
    1 = 'prompt for credentials on the secure desktop'
    2 = 'prompt for consent on the secure desktop'
    3 = 'prompt for credentials'
    4 = 'prompt for consent'
    5 = 'prompt for consent for non-Windows binaries'
}
if ($lua -eq 1) {
    Write-Output 'OK: UAC is enabled'
