# Shows, enables or disables USB mass storage through the USBSTOR driver start value.
# Variables: STATE (status, enable or disable; default status)
# Exit: 0 ok, 1 change failed, 3 bad input
# Devices that are already plugged in keep working until they are removed or the machine restarts.
$ErrorActionPreference = 'Stop'
$state = ([string]$env:STATE).Trim().ToLower()
if (-not $state) { $state = 'status' }
if ($state -notin 'status', 'enable', 'disable') {
    Write-Output ('Bad STATE value: ' + $state)
    exit 3
}
$key = 'HKLM:\SYSTEM\CurrentControlSet\Services\USBSTOR'
if (-not (Test-Path $key)) {
    Write-Output 'USBSTOR driver key not found'
    exit 3
}
try {
    $current = [int](Get-ItemProperty -Path $key -Name Start).Start
    if ($state -eq 'enable' -or $state -eq 'disable') {
        $want = if ($state -eq 'enable') { 3 } else { 4 }
        if ($current -eq $want) {
            Write-Output ('USB storage already ' + $state + 'd, nothing changed')
        } else {
            [void](New-ItemProperty -Path $key -Name Start -Value $want -PropertyType DWord -Force)
            Write-Output ('USB storage ' + $state + 'd')
        }
        $current = [int](Get-ItemProperty -Path $key -Name Start).Start
    }
} catch {
    Write-Output ('FAIL: ' + $_.Exception.Message)
    exit 1
}
$label = if ($current -eq 4) { 'disabled' } elseif ($current -eq 3) { 'enabled' } else { 'start value ' + $current }
Write-Output ('USB storage is ' + $label)
exit 0

# Checks that Windows is activated and reports the license channel and remaining grace period.
# Variables: none
# Exit: 0 licensed, 1 not licensed, 3 licensing information unavailable
$ErrorActionPreference = 'Stop'
$windowsAppId = '55c92734-d682-4d71-983e-d6ec3f16059f'
try {
    $p = @(Get-CimInstance -ClassName SoftwareLicensingProduct -Filter "ApplicationId='$windowsAppId' AND PartialProductKey IS NOT NULL" | Where-Object { -not $_.LicenseIsAddon })
} catch {
    Write-Output ('Cannot read the licensing status: ' + $_.Exception.Message)
    exit 3
}
if ($p.Count -eq 0) {
    Write-Output 'FAIL: no installed product key found'
    exit 1
}
$states = @{
    0 = 'Unlicensed'; 1 = 'Licensed'; 2 = 'Initial grace period'; 3 = 'Additional grace period'
    4 = 'Non-genuine grace period'; 5 = 'Notification'; 6 = 'Extended grace period'
}
$licensed = @($p | Where-Object { $_.LicenseStatus -eq 1 })
$main = if ($licensed.Count -gt 0) { $licensed[0] } else { $p[0] }
$text = $states[[int]$main.LicenseStatus]
if ($licensed.Count -gt 0) {
    Write-Output 'OK: Windows is activated'
    $rc = 0
} else {
    Write-Output ('FAIL: Windows is not activated (' + $text + ')')
    $rc = 1
}
Write-Output ('Product: ' + $main.Name)
Write-Output ('Channel: ' + $main.ProductKeyChannel + ', partial key ' + $main.PartialProductKey)
if ($main.GracePeriodRemaining -gt 0) {
    Write-Output ('Grace period remaining: ' + [math]::Round($main.GracePeriodRemaining / 1440, 1) + ' days')
}
exit $rc

# Checks the certificates of a store for expiry and shows which IIS HTTPS bindings use a certificate when the IIS module exists.
# Variables: WARN_DAYS (30) days before expiry that count as a warning; STORE (LocalMachine\My) certificate store, for example LocalMachine\My or LocalMachine\WebHosting.
# Exit: 0 all valid, 1 a certificate is expired, 2 a certificate expires soon, 3 bad input.
$warn = 30
if ($env:WARN_DAYS) { if (-not [int]::TryParse($env:WARN_DAYS.Trim(), [ref]$warn) -or $warn -lt 1 -or $warn -gt 3650) { Write-Output 'WARN_DAYS must be a number from 1 to 3650'; exit 3 } }
$store = 'LocalMachine\My'
if ($env:STORE) { $store = $env:STORE.Trim() }
if ($store -notmatch '^(LocalMachine|CurrentUser)\\[A-Za-z0-9 _-]{1,60}$') { Write-Output 'STORE must look like LocalMachine\My'; exit 3 }
$path = 'Cert:\' + $store
if (-not (Test-Path -LiteralPath $path)) { Write-Output "Certificate store $store does not exist"; exit 3 }

$bindings = @{}
$iisNote = ''
if (Get-Module -ListAvailable -Name WebAdministration) {
    try {
        Import-Module WebAdministration -ErrorAction Stop
        foreach ($b in @(Get-WebBinding -Protocol https -ErrorAction Stop)) {
            $hash = [string]$b.certificateHash
            if (-not $hash) { continue }
            $site = ''
            if ($b.ItemXPath -match "@name='([^']+)'") { $site = $Matches[1] }
            $label = "$site $($b.bindingInformation)".Trim()
            if ($bindings.ContainsKey($hash)) { $bindings[$hash] += "; $label" } else { $bindings[$hash] = $label }
        }
    } catch { $iisNote = "IIS bindings could not be read: $($_.Exception.Message)" }
}

$now = Get-Date
$certs = @(Get-ChildItem -LiteralPath $path -ErrorAction Stop | Where-Object { $_.NotAfter })
$expired = 0
$soon = 0
$lines = @()
foreach ($c in ($certs | Sort-Object -Property NotAfter)) {
    $days = [int][math]::Floor(($c.NotAfter - $now).TotalDays)
    $tag = 'ok'
    if ($days -lt 0) { $tag = 'EXPIRED'; $expired++ } elseif ($days -le $warn) { $tag = 'EXPIRES SOON'; $soon++ }
    if ($tag -eq 'ok') { continue }
    $use = ''
    if ($bindings.ContainsKey($c.Thumbprint)) { $use = " used by IIS: $($bindings[$c.Thumbprint])" }
    $lines += ("{0}: {1} thumbprint {2} valid until {3:yyyy-MM-dd} ({4} days){5}" -f $tag, $c.Subject, $c.Thumbprint, $c.NotAfter, $days, $use)
}
if ($expired -gt 0) { Write-Output "CRITICAL: $expired expired, $soon expiring within $warn days in $store ($($certs.Count) certificates)" }
elseif ($soon -gt 0) { Write-Output "WARNING: $soon certificate(s) expire within $warn days in $store ($($certs.Count) certificates)" }
else { Write-Output "OK: $($certs.Count) certificate(s) in $store, none expiring within $warn days" }
$lines | ForEach-Object { Write-Output $_ }
if ($iisNote) { Write-Output $iisNote }
if ($expired + $soon -eq 0) { exit 0 }
if ($expired -gt 0) { exit 1 }
exit 2

# Checks the address usage of every IPv4 DHCP scope on this server.
# Variables: WARN_PERCENT (85) usage that counts as a warning.
# Exit: 0 ok, 1 a scope has no free address left, 2 a scope is above the warning level, 3 bad input or no DHCP server role.
$warn = 85
if ($env:WARN_PERCENT) { if (-not [int]::TryParse($env:WARN_PERCENT.Trim(), [ref]$warn) -or $warn -lt 1 -or $warn -gt 100) { Write-Output 'WARN_PERCENT must be a number from 1 to 100'; exit 3 } }
if (-not (Get-Command Get-DhcpServerv4ScopeStatistics -ErrorAction SilentlyContinue)) { Write-Output 'The DHCP Server role or its PowerShell module is not installed'; exit 3 }
if (-not (Get-Service -Name DHCPServer -ErrorAction SilentlyContinue)) { Write-Output 'The DHCP Server role is not installed on this machine (only the management tools)'; exit 3 }
try {
    $stats = @(Get-DhcpServerv4ScopeStatistics -ErrorAction Stop)
} catch {
    Write-Output "Cannot read the DHCP scopes: $($_.Exception.Message)"
    exit 1
}
if ($stats.Count -eq 0) { Write-Output 'No IPv4 DHCP scopes configured'; exit 0 }
$names = @{}
foreach ($sc in @(Get-DhcpServerv4Scope -ErrorAction SilentlyContinue)) { $names[[string]$sc.ScopeId] = $sc.Name }
$level = 0
$lines = @()
foreach ($s in ($stats | Sort-Object -Property PercentageInUse -Descending)) {
    $pct = [math]::Round([double]$s.PercentageInUse, 1)
    $tag = 'ok'
    if ($s.Free -le 0) { $tag = 'FULL'; $level = 2 } elseif ($pct -ge $warn) { $tag = 'WARN'; if ($level -lt 1) { $level = 1 } }
    $lines += ("{0} {1} ({2}): {3}% in use, {4} in use, {5} free" -f $tag, $s.ScopeId, $names[[string]$s.ScopeId], $pct, $s.InUse, $s.Free)
}
switch ($level) {
    0 { Write-Output "OK: $($stats.Count) scope(s) below $warn% in use"; $rc = 0 }
    1 { Write-Output "WARNING: a scope is above $warn% in use"; $rc = 2 }
    default { Write-Output 'CRITICAL: a scope has no free address'; $rc = 1 }
}
$lines | ForEach-Object { Write-Output $_ }
exit $rc

# Lists Hyper-V checkpoints older than the limit; old checkpoints slow VMs down and fill the disk.
# Variables: MAX_DAYS (7) age limit in days.
# Exit: 0 none too old, 2 old checkpoints found, 3 bad input or Hyper-V not available.
$max = 7
if ($env:MAX_DAYS) { if (-not [int]::TryParse($env:MAX_DAYS.Trim(), [ref]$max) -or $max -lt 1 -or $max -gt 3650) { Write-Output 'MAX_DAYS must be a number from 1 to 3650'; exit 3 } }
if (-not (Get-Command Get-VMSnapshot -ErrorAction SilentlyContinue)) { Write-Output 'The Hyper-V PowerShell module is not available on this system'; exit 3 }
try {
    $snaps = @(Get-VM -ErrorAction Stop | Get-VMSnapshot -ErrorAction Stop)
} catch {
    Write-Output "Cannot read the checkpoints (is this a Hyper-V host?): $($_.Exception.Message)"
    exit 3
}
$cut = (Get-Date).AddDays(-$max)
$old = @($snaps | Where-Object { $_.CreationTime -lt $cut })
if ($old.Count -eq 0) { Write-Output "OK: $($snaps.Count) checkpoint(s), none older than $max days"; exit 0 }
Write-Output "WARNING: $($old.Count) of $($snaps.Count) checkpoint(s) older than $max days"
foreach ($s in ($old | Sort-Object -Property CreationTime)) {
    Write-Output ("{0}: '{1}' created {2:yyyy-MM-dd} ({3} days old)" -f $s.VMName, $s.Name, $s.CreationTime, [int]((Get-Date) - $s.CreationTime).TotalDays)
}
exit 2

# Lists the Hyper-V virtual machines with state and heartbeat and checks that the VMs named in EXPECT_RUNNING are running.
# Variables: EXPECT_RUNNING VM names that must be running, comma or line separated (empty = only report).
# Exit: 0 ok, 1 an expected VM is not running or missing, 2 a VM is in a critical or paused state, 3 Hyper-V is not available.
if (-not (Get-Command Get-VM -ErrorAction SilentlyContinue)) { Write-Output 'The Hyper-V PowerShell module is not available on this system'; exit 3 }
$expect = @()
if ($env:EXPECT_RUNNING) { $expect = @($env:EXPECT_RUNNING -split '[,\r\n]+' | ForEach-Object { $_.Trim() } | Where-Object { $_ }) }
try {
    $vms = @(Get-VM -ErrorAction Stop)
} catch {
    Write-Output "Cannot read the VMs (is this a Hyper-V host?): $($_.Exception.Message)"
    exit 3
}
$bad = 0
$warn = 0
$lines = @()
foreach ($e in $expect) {
    $vm = $vms | Where-Object { $_.Name -ieq $e } | Select-Object -First 1
    if (-not $vm) { $lines += "MISSING expected VM '$e' does not exist on this host"; $bad++ }
    elseif ($vm.State -ne 'Running') { $lines += "DOWN expected VM '$($vm.Name)' is $($vm.State)"; $bad++ }
}
foreach ($vm in $vms) {
    if ($vm.State -like '*Critical*' -or $vm.State -eq 'Paused') { $warn++ }
}
$verdict = 'OK'
if ($bad -gt 0) { $verdict = 'CRITICAL' } elseif ($warn -gt 0) { $verdict = 'WARNING' }
Write-Output ("{0}: {1} VM(s), {2} running; {3} expected VM(s) failing, {4} VM(s) critical or paused" -f $verdict, $vms.Count, @($vms | Where-Object { $_.State -eq 'Running' }).Count, $bad, $warn)
$lines | ForEach-Object { Write-Output $_ }
foreach ($vm in ($vms | Sort-Object -Property Name)) {
    Write-Output ("{0}: {1}, heartbeat {2}, uptime {3}" -f $vm.Name, $vm.State, $vm.Heartbeat, $vm.Uptime.ToString('d\.hh\:mm'))
}
if ($bad -gt 0) { exit 1 }
if ($warn -gt 0) { exit 2 }
exit 0

# Checks the last Windows Server Backup run: result of the last backup and age of the last successful one.
# Variables: MAX_HOURS (26) maximum age of the last successful backup in hours.
# Exit: 0 backup ok, 1 backup too old, never run or last run failed, 3 bad input or Windows Server Backup not installed.
$max = 26
if ($env:MAX_HOURS) { if (-not [int]::TryParse($env:MAX_HOURS.Trim(), [ref]$max) -or $max -lt 1 -or $max -gt 8760) { Write-Output 'MAX_HOURS must be a number from 1 to 8760'; exit 3 } }
if (-not (Get-Command Get-WBSummary -ErrorAction SilentlyContinue)) { Write-Output 'Windows Server Backup is not installed (feature Windows-Server-Backup)'; exit 3 }
try {
    $s = Get-WBSummary -ErrorAction Stop
} catch {
    Write-Output "Cannot read the backup summary: $($_.Exception.Message)"
    exit 1
}
if (-not $s -or -not $s.LastSuccessfulBackupTime -or $s.LastSuccessfulBackupTime.Year -lt 2000) { Write-Output 'CRITICAL: no successful backup found'; exit 1 }
$age = ((Get-Date) - $s.LastSuccessfulBackupTime).TotalHours
$lastHr = [int64]$s.LastBackupResultHR
$problem = $false
if ($lastHr -ne 0) { $problem = $true }
if ($age -gt $max) { $problem = $true }
$verdict = 'OK'
if ($problem) { $verdict = 'CRITICAL' }
Write-Output ("{0}: last success {1:yyyy-MM-dd HH:mm} ({2:N1} h ago, limit {3} h), last run {4:yyyy-MM-dd HH:mm} result 0x{5:X8}" -f $verdict, $s.LastSuccessfulBackupTime, $age, $max, $s.LastBackupTime, ($lastHr -band 0xFFFFFFFFL))
if ($s.NextBackupTime) { Write-Output ("Next backup: {0:yyyy-MM-dd HH:mm}" -f $s.NextBackupTime) }
if ($problem) { exit 1 }
exit 0

# Lists installed programs from the 64-bit and 32-bit uninstall registry views, optionally filtered by name.
# Variables: NAME part of the display name, case-insensitive; empty lists everything.
# Exit: 0 found or listed, 1 nothing matches.
$filter = ''
if ($env:NAME) { $filter = $env:NAME.Trim() }
$roots = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'
$rows = @()
foreach ($r in $roots) {
    foreach ($k in @(Get-ChildItem -LiteralPath $r -ErrorAction SilentlyContinue)) {
        $p = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue
        if (-not $p.DisplayName -or $p.SystemComponent -eq 1 -or $p.ParentKeyName) { continue }
        if ($filter -and $p.DisplayName.IndexOf($filter, [StringComparison]::OrdinalIgnoreCase) -lt 0) { continue }
        $arch = 'x64'
        if ($r -like '*WOW6432Node*') { $arch = 'x86' }
        $rows += [pscustomobject]@{ Name = $p.DisplayName; Version = $p.DisplayVersion; Publisher = $p.Publisher; Date = $p.InstallDate; Arch = $arch }
    }
}
if ($rows.Count -eq 0) { Write-Output "No installed program matches '$filter'"; exit 1 }
Write-Output "$($rows.Count) installed program(s) (machine-wide entries only)"
foreach ($x in ($rows | Sort-Object -Property Name, Arch)) {
    Write-Output ("{0} | {1} | {2} | {3} | {4}" -f $x.Name, $x.Version, $x.Publisher, $x.Date, $x.Arch)
}
exit 0

# Uninstalls one program by its exact display name: MSI packages with msiexec /x /qn, other programs only when they provide a QuietUninstallString. Refuses when several entries match.
# Variables: NAME exact display name (see the find installed software script); DRY_RUN (false) only show what would run.
# Exit: 0 uninstalled or not installed, 1 failed or several matches, 3 bad input or no silent uninstall available.
$name = ''
if ($env:NAME) { $name = $env:NAME.Trim() }
if (-not $name) { Write-Output 'NAME is required'; exit 3 }
$dry = $false
if ($env:DRY_RUN) {
    if ('true', 'false' -notcontains $env:DRY_RUN.Trim()) { Write-Output 'DRY_RUN must be true or false'; exit 3 }
    $dry = $env:DRY_RUN.Trim() -eq 'true'
}
$roots = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'
$hits = @()
foreach ($r in $roots) {
    foreach ($k in @(Get-ChildItem -LiteralPath $r -ErrorAction SilentlyContinue)) {
        $p = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue
        if ($p.DisplayName -and $p.DisplayName -ieq $name) { $hits += [pscustomobject]@{ Key = $k.PSChildName; Path = $k.PSPath; Props = $p } }
    }
}
if ($hits.Count -eq 0) { Write-Output "'$name' is not installed"; exit 0 }
if ($hits.Count -gt 1) {
    Write-Output "$($hits.Count) entries match '$name', refusing to guess:"
    $hits | ForEach-Object { Write-Output ("  {0} {1} ({2})" -f $_.Props.DisplayName, $_.Props.DisplayVersion, $_.Key) }
    exit 1
}
$h = $hits[0]
$cmd = $null
$file = $null
if ($h.Props.WindowsInstaller -eq 1 -and $h.Key -match '^\{[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}\}$') {
    $file = Join-Path $env:windir 'System32\msiexec.exe'
    $cmd = "/x $($h.Key) /qn /norestart"
} elseif ($h.Props.QuietUninstallString) {
    $file = Join-Path $env:windir 'System32\cmd.exe'
    $cmd = '/c "' + $h.Props.QuietUninstallString + '"'
} else {
    Write-Output "'$name' is not an MSI package and has no QuietUninstallString, it cannot be removed silently"
    exit 3
}
Write-Output "Found $($h.Props.DisplayName) $($h.Props.DisplayVersion): $file $cmd"
if ($dry) { Write-Output 'Dry run, nothing removed'; exit 0 }
try {
    $p = Start-Process -FilePath $file -ArgumentList $cmd -Wait -PassThru -WindowStyle Hidden
    $gone = -not (Test-Path -LiteralPath $h.Path)
    Write-Output "Uninstaller exit code $($p.ExitCode), registry entry removed: $gone"
    if ($p.ExitCode -eq 3010) { Write-Output 'A restart is needed to finish'; exit 0 }
    if ($p.ExitCode -eq 0 -or $gone) { exit 0 }
    exit 1
} catch {
    Write-Output "Failed: $($_.Exception.Message)"
    exit 1
}

# Runs winget as SYSTEM: list packages with an update, upgrade all, or install, upgrade or uninstall one package (machine scope, agreements accepted).
# Variables: ACTION (list) list, upgrade all, install, upgrade or uninstall; PACKAGE_ID exact winget id, for example Mozilla.Firefox (not needed for list and upgrade all).
# Exit: 0 done or nothing to do, 1 winget failed, 3 bad input or winget not available.
$action = 'list'
if ($env:ACTION) { $action = $env:ACTION.Trim().ToLower() }
if ('list', 'upgrade all', 'install', 'upgrade', 'uninstall' -notcontains $action) { Write-Output 'ACTION must be list, upgrade all, install, upgrade or uninstall'; exit 3 }
$id = ''
if ($env:PACKAGE_ID) { $id = $env:PACKAGE_ID.Trim() }
if ($action -in 'install', 'upgrade', 'uninstall') {
    if ($id -notmatch '^[A-Za-z0-9][A-Za-z0-9._+-]{1,127}$') { Write-Output 'PACKAGE_ID is required, for example Mozilla.Firefox'; exit 3 }
}

$exe = $null
$apps = Join-Path $env:ProgramFiles 'WindowsApps'
$dirs = @(Get-ChildItem -Path (Join-Path $apps 'Microsoft.DesktopAppInstaller_*__8wekyb3d8bbwe') -Directory -ErrorAction SilentlyContinue)
$best = $null
foreach ($d in $dirs) {
    if ($d.Name -notmatch '_(x64|arm64)__') { continue }
    $ver = $null
    if ($d.Name -match '_([0-9.]+)_') { $ver = [version]$Matches[1] }
    if (-not (Test-Path -LiteralPath (Join-Path $d.FullName 'winget.exe'))) { continue }
    if (-not $best -or $ver -gt $best.Ver) { $best = @{ Ver = $ver; Path = (Join-Path $d.FullName 'winget.exe') } }
}
if ($best) { $exe = $best.Path }
if (-not $exe) { Write-Output 'winget is not available on this system (needs Windows 10 1809+ or 11 with App Installer; not on Server 2016/2019 or LTSC without it)'; exit 3 }

try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch { Write-Verbose 'no console to set the encoding on' }
$common = @('--accept-source-agreements', '--disable-interactivity')
$pkg = @('--id', $id, '--exact', '--silent', '--scope', 'machine', '--accept-package-agreements')
switch ($action) {
    'list' { $arguments = @('upgrade') + $common }
    'upgrade all' { $arguments = @('upgrade', '--all', '--silent', '--scope', 'machine', '--accept-package-agreements') + $common }
    'install' { $arguments = @('install') + $pkg + $common }
    'upgrade' { $arguments = @('upgrade') + $pkg + $common }
    'uninstall' { $arguments = @('uninstall', '--id', $id, '--exact', '--silent', '--scope', 'machine') + $common }
}
$old = $ErrorActionPreference
$ErrorActionPreference = 'Continue'
$out = & $exe @arguments 2>&1 | ForEach-Object { [string]$_ }
$rc = $LASTEXITCODE
$ErrorActionPreference = $old
$blocks = '[' + [char]0x2580 + '-' + [char]0x259F + ']'
foreach ($l in $out) {
    if ($l -match '^\s*[-\\|/]?\s*$' -or $l -match $blocks) { continue }
    Write-Output $l.TrimEnd()
}
if ($rc -eq 0) { Write-Output 'winget finished successfully'; exit 0 }
if ($rc -eq -1978335189) { Write-Output "winget: no applicable update (code $rc)"; exit 0 }
if ($rc -eq -1978335135 -and $action -eq 'install') { Write-Output "$id is already installed"; exit 0 }
if ($rc -eq -1978335212 -and $action -eq 'uninstall') { Write-Output "No installed package $id found in machine scope, nothing to remove"; exit 0 }
if ($rc -eq -1073741515) { Write-Output 'winget could not start as SYSTEM: install the Microsoft Visual C++ 2015-2022 Redistributable'; exit 1 }
Write-Output "winget exit code $rc"
exit 1

# Checks the used space of the fixed drives against a warning and an error threshold.
# Variables: WARN_PERCENT (85) used space for a warning; ERROR_PERCENT (95) used space for an error; DRIVES drive letters like C,D (empty = all fixed drives).
# Exit: 0 ok, 1 a drive is above the error threshold, 2 a drive is above the warning threshold, 3 bad input.
$warn = 85
$err = 95
if ($env:WARN_PERCENT) { if (-not [int]::TryParse($env:WARN_PERCENT.Trim(), [ref]$warn) -or $warn -lt 1 -or $warn -gt 100) { Write-Output 'WARN_PERCENT must be a number from 1 to 100'; exit 3 } }
if ($env:ERROR_PERCENT) { if (-not [int]::TryParse($env:ERROR_PERCENT.Trim(), [ref]$err) -or $err -lt 1 -or $err -gt 100) { Write-Output 'ERROR_PERCENT must be a number from 1 to 100'; exit 3 } }
if ($warn -gt $err) { Write-Output 'WARN_PERCENT must not be above ERROR_PERCENT'; exit 3 }
$only = @()
if ($env:DRIVES) {
    foreach ($d in ($env:DRIVES -split '[,\s;]+' | Where-Object { $_ })) {
        if ($d -notmatch '^[A-Za-z]:?\\?$') { Write-Output "'$d' is not a drive letter"; exit 3 }
        $only += ($d.Substring(0, 1).ToUpper() + ':')
    }
}
$disks = @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' | Where-Object { $_.Size -gt 0 })
if ($only.Count -gt 0) {
    foreach ($o in $only) { if (-not ($disks | Where-Object { $_.DeviceID -eq $o })) { Write-Output "Drive $o not found"; exit 3 } }
    $disks = @($disks | Where-Object { $only -contains $_.DeviceID })
}
$level = 0
$lines = @()
foreach ($d in $disks) {
    $pct = [math]::Round(100 - 100 * $d.FreeSpace / $d.Size, 1)
    $tag = 'ok'
    if ($pct -ge $err) { $tag = 'ERROR'; $level = 2 } elseif ($pct -ge $warn) { $tag = 'WARN'; if ($level -lt 1) { $level = 1 } }
    $lines += ('{0} {1} {2}% used, {3:N1} GB free of {4:N0} GB' -f $tag, $d.DeviceID, $pct, ($d.FreeSpace / 1GB), ($d.Size / 1GB))
}
if ($disks.Count -eq 0) { Write-Output 'No fixed drives found'; exit 0 }
switch ($level) {
    0 { Write-Output "OK: $($disks.Count) drive(s) below $warn% used"; $rc = 0 }
    1 { Write-Output "WARNING: a drive is above $warn% used"; $rc = 2 }
    2 { Write-Output "CRITICAL: a drive is above $err% used"; $rc = 1 }
}
$lines | ForEach-Object { Write-Output $_ }
exit $rc

# Lists the largest files below a folder; reparse points (junctions, links) are not followed.
# Variables: SEARCH_PATH (C:\) folder to scan; TOP (20) number of files; MIN_MB (100) smallest size that is listed.
# Exit: 0 report printed, 3 bad input.
$root = $env:SystemDrive + '\'
if ($env:SEARCH_PATH) { $root = $env:SEARCH_PATH.Trim() }
if ($root -notmatch '^[A-Za-z]:\\' -or -not (Test-Path -LiteralPath $root -PathType Container)) { Write-Output 'SEARCH_PATH must be an existing local folder like C:\'; exit 3 }
$top = 20
if ($env:TOP) { if (-not [int]::TryParse($env:TOP.Trim(), [ref]$top) -or $top -lt 1 -or $top -gt 500) { Write-Output 'TOP must be a number from 1 to 500'; exit 3 } }
$minMb = 100
if ($env:MIN_MB) { if (-not [int]::TryParse($env:MIN_MB.Trim(), [ref]$minMb) -or $minMb -lt 0 -or $minMb -gt 1048576) { Write-Output 'MIN_MB must be a number from 0 to 1048576'; exit 3 } }
$min = [int64]$minMb * 1MB
$found = New-Object System.Collections.Generic.List[object]
$stack = New-Object System.Collections.Generic.Stack[string]
$stack.Push($root)
$skipped = 0
while ($stack.Count -gt 0) {
    $dir = $stack.Pop()
    try {
        $di = New-Object System.IO.DirectoryInfo $dir
        foreach ($f in $di.GetFiles()) { if ($f.Length -ge $min) { $found.Add($f) } }
        foreach ($d in $di.GetDirectories()) {
            if (-not ($d.Attributes -band [System.IO.FileAttributes]::ReparsePoint)) { $stack.Push($d.FullName) }
        }
    } catch { $skipped++ }
}
$list = @($found | Sort-Object -Property Length -Descending | Select-Object -First $top)
Write-Output "$($found.Count) file(s) of at least $minMb MB below $root, showing $($list.Count) ($skipped folders not readable)"
foreach ($f in $list) {
    Write-Output ('{0,9:N0} MB  {1:yyyy-MM-dd}  {2}' -f ($f.Length / 1MB), $f.LastWriteTime, $f.FullName)
}
exit 0

# Optimizes a volume by media type: TRIM for SSDs and thin disks, defragmentation for hard disks.
# Variables: DRIVE drive letter (default: the system drive).
# Exit: 0 done, 1 failed, 3 bad input or unsupported volume.
$drive = $env:SystemDrive
if ($env:DRIVE) { $drive = $env:DRIVE.Trim() }
if ($drive -notmatch '^[A-Za-z]:?\\?$') { Write-Output 'DRIVE must be a drive letter like C'; exit 3 }
$letter = $drive.Substring(0, 1).ToUpper()
if (-not (Get-Command Optimize-Volume -ErrorAction SilentlyContinue)) { Write-Output 'Optimize-Volume is not available on this system'; exit 3 }
$vol = Get-Volume -DriveLetter $letter -ErrorAction SilentlyContinue
if (-not $vol -or $vol.DriveType -ne 'Fixed') { Write-Output "Drive ${letter}: is not a fixed volume"; exit 3 }
if ($vol.FileSystem -notin 'NTFS', 'ReFS') { Write-Output "Drive ${letter}: has file system '$($vol.FileSystem)', only NTFS and ReFS are optimized"; exit 3 }
try {
    $media = 'Unspecified'
    $disk = Get-Partition -DriveLetter $letter -ErrorAction Stop | Get-Disk -ErrorAction Stop | Select-Object -First 1
    $pd = Get-PhysicalDisk -ErrorAction SilentlyContinue | Where-Object { [string]$_.DeviceId -eq [string]$disk.Number } | Select-Object -First 1
    if ($pd) { $media = [string]$pd.MediaType }
    if ($media -eq 'HDD') {
        Optimize-Volume -DriveLetter $letter -Defrag -ErrorAction Stop
        Write-Output "Drive ${letter}: defragmented (hard disk)"
    } elseif ($media -eq 'SSD') {
        Optimize-Volume -DriveLetter $letter -ReTrim -ErrorAction Stop
        Write-Output "Drive ${letter}: retrim done (SSD)"
    } else {
        Optimize-Volume -DriveLetter $letter -ErrorAction Stop
        Write-Output "Drive ${letter}: default optimization for the drive type done (media type $media)"
    }
    exit 0
} catch {
    Write-Output "Drive ${letter}: $($_.Exception.Message)"
    exit 1
}

# Reports the shadow copies (restore points) per volume with count, oldest and newest copy, and the shadow storage use.
# Variables: none.
# Exit: 0 report printed, 1 failed.
try {
    $vols = @{}
    foreach ($v in Get-CimInstance Win32_Volume) { $vols[$v.DeviceID] = if ($v.DriveLetter) { $v.DriveLetter } else { $v.DeviceID } }
    $copies = @(Get-CimInstance Win32_ShadowCopy -ErrorAction SilentlyContinue)
    if ($copies.Count -eq 0) { Write-Output 'No shadow copies exist'; exit 0 }
    Write-Output "$($copies.Count) shadow copies"
    foreach ($g in ($copies | Group-Object -Property VolumeName)) {
        $label = $g.Name
        if ($vols.ContainsKey($g.Name)) { $label = $vols[$g.Name] }
        $dates = @($g.Group | ForEach-Object { $_.InstallDate } | Sort-Object)
        Write-Output ("{0}: {1} copies, oldest {2:yyyy-MM-dd HH:mm}, newest {3:yyyy-MM-dd HH:mm}" -f $label, $g.Count, $dates[0], $dates[-1])
    }
    foreach ($s in @(Get-CimInstance Win32_ShadowStorage -ErrorAction SilentlyContinue)) {
        $label = $s.Volume.DeviceID
        if ($vols.ContainsKey($label)) { $label = $vols[$label] }
        $max = 'unbounded'
        if ($s.MaxSpace -gt 0 -and $s.MaxSpace -lt 9e18) { $max = '{0:N1} GB' -f ($s.MaxSpace / 1GB) }
        Write-Output ("Storage on {0}: used {1:N1} GB, allocated {2:N1} GB, limit {3}" -f $label, ($s.UsedSpace / 1GB), ($s.AllocatedSpace / 1GB), $max)
    }
    exit 0
} catch {
    Write-Output "Failed: $($_.Exception.Message)"
    exit 1
}

# Checks the health of Storage Spaces: storage pools, virtual disks and the physical disks in the pools.
# Variables: none.
# Exit: 0 healthy or no pools, 1 something is unhealthy, 2 something is degraded or has a warning, 3 Storage module missing.
if (-not (Get-Command Get-StoragePool -ErrorAction SilentlyContinue)) { Write-Output 'The Storage module is not available on this system'; exit 3 }
try {
    $pools = @(Get-StoragePool -IsPrimordial $false -ErrorAction Stop)
    if ($pools.Count -eq 0) { Write-Output 'No storage pools configured'; exit 0 }
    $level = 0
    $lines = @()
    function Add-Line([string]$Kind, [string]$Name, $Health, $Op) {
        $h = [string]$Health
        if ($h -ne 'Healthy') { $script:level = [math]::Max($script:level, $(if ($h -eq 'Warning') { 1 } else { 2 })) }
        $script:lines += "$Kind ${Name}: health $h, status $(@($Op) -join '/')"
    }
    foreach ($p in $pools) {
        Add-Line 'Pool' $p.FriendlyName $p.HealthStatus $p.OperationalStatus
        foreach ($v in @(Get-VirtualDisk -StoragePool $p -ErrorAction SilentlyContinue)) { Add-Line 'Virtual disk' $v.FriendlyName $v.HealthStatus $v.OperationalStatus }
        foreach ($d in @(Get-PhysicalDisk -StoragePool $p -ErrorAction SilentlyContinue)) { Add-Line 'Physical disk' $d.FriendlyName $d.HealthStatus $d.OperationalStatus }
    }
    switch ($level) {
        0 { Write-Output "OK: $($pools.Count) pool(s) healthy"; $rc = 0 }
        1 { Write-Output 'WARNING: a storage object has a warning'; $rc = 2 }
        default { Write-Output 'CRITICAL: a storage object is unhealthy'; $rc = 1 }
    }
    $lines | ForEach-Object { Write-Output $_ }
    exit $rc
} catch {
    Write-Output "Check failed: $($_.Exception.Message)"
    exit 1
}

# Scans a volume for file system errors with Repair-Volume (online scan) or runs a spot fix.
# Variables: DRIVE drive letter; SPOT_FIX (false) run -SpotFix, which repairs offline and may schedule the work for the next restart on the system drive.
# Exit: 0 no errors or errors fixed, 1 errors remain or the scan failed, 3 bad input or not a fixed NTFS volume.
$drive = ''
if ($env:DRIVE) { $drive = $env:DRIVE.Trim() }
if ($drive -notmatch '^[A-Za-z]:?\\?$') { Write-Output 'DRIVE must be a drive letter like C'; exit 3 }
$letter = $drive.Substring(0, 1).ToUpper()
if ($env:SPOT_FIX -and 'true', 'false' -notcontains $env:SPOT_FIX.Trim()) { Write-Output 'SPOT_FIX must be true or false'; exit 3 }
if (-not (Get-Command Repair-Volume -ErrorAction SilentlyContinue)) { Write-Output 'Repair-Volume is not available on this system'; exit 3 }
$vol = Get-Volume -DriveLetter $letter -ErrorAction SilentlyContinue
if (-not $vol) { Write-Output "Drive ${letter}: not found"; exit 3 }
if ($vol.DriveType -ne 'Fixed') { Write-Output "Drive ${letter}: is not a fixed disk"; exit 3 }
if ($vol.FileSystem -ne 'NTFS') { Write-Output "Drive ${letter}: has file system '$($vol.FileSystem)', scan and spot fix work on NTFS only"; exit 3 }
try {
    if ("$env:SPOT_FIX".Trim() -eq 'true') { $res = Repair-Volume -DriveLetter $letter -SpotFix -ErrorAction Stop; $mode = 'spot fix' }
    else { $res = Repair-Volume -DriveLetter $letter -Scan -ErrorAction Stop; $mode = 'scan' }
    $text = (@($res) | ForEach-Object { $_.ToString() }) -join ' '
    Write-Output "Drive ${letter}: $mode result: $text"
    if ($text -match 'NoErrorsFound|ErrorsFixed') { exit 0 }
    exit 1
} catch {
    Write-Output "Drive ${letter}: $($_.Exception.Message)"
    exit 1
}

# Lists services set to start automatically that are not running; trigger-start services and delayed services that are not due yet are ignored.
# Variables: EXCLUDE (edgeupdate,gupdate,MapsBroker) services to ignore, comma or line separated, name or display name, wildcards allowed.
# Exit: 0 all running, 1 at least one service is stopped.
$list = 'edgeupdate,gupdate,MapsBroker'
if ($env:EXCLUDE) { $list = $env:EXCLUDE }
$exclude = @($list -split '[,\r\n]+' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
$os = Get-CimInstance Win32_OperatingSystem
$upMin = ((Get-Date) - $os.LastBootUpTime).TotalMinutes
$bad = @()
$services = Get-CimInstance Win32_Service -Filter "StartMode='Auto' AND State<>'Running'"
foreach ($s in $services) {
    $reg = 'HKLM:\SYSTEM\CurrentControlSet\Services\' + $s.Name
    if (Test-Path -LiteralPath (Join-Path $reg 'TriggerInfo')) { continue }
    $delayed = (Get-ItemProperty -LiteralPath $reg -Name DelayedAutostart -ErrorAction SilentlyContinue).DelayedAutostart
    if ($delayed -eq 1 -and $upMin -lt 15) { continue }
    $skip = $false
    foreach ($e in $exclude) { if ($s.Name -like $e -or $s.DisplayName -like $e) { $skip = $true } }
    if (-not $skip) { $bad += $s }
}
if ($bad.Count -eq 0) { Write-Output 'OK: all automatic services are running'; exit 0 }
Write-Output "$($bad.Count) automatic service(s) not running"
foreach ($s in ($bad | Sort-Object -Property Name)) {
    Write-Output ("{0} ({1}): {2}, exit code {3}" -f $s.Name, $s.DisplayName, $s.State, $s.ExitCode)
}
exit 1

# Lists critical and error events of an event log, grouped by provider and event id.
# Variables: LOG (System) log name; HOURS (24) look back; MAX (20) number of groups shown.
# Exit: 0 report printed, 3 bad input or unknown log.
$log = 'System'
if ($env:LOG) { $log = $env:LOG.Trim() }
if ($log -notmatch '^[A-Za-z0-9 /_.\-]{1,100}$') { Write-Output 'LOG contains characters that are not allowed'; exit 3 }
$hours = 24
if ($env:HOURS) { if (-not [int]::TryParse($env:HOURS.Trim(), [ref]$hours) -or $hours -lt 1 -or $hours -gt 8760) { Write-Output 'HOURS must be a number from 1 to 8760'; exit 3 } }
$maxRows = 20
if ($env:MAX) { if (-not [int]::TryParse($env:MAX.Trim(), [ref]$maxRows) -or $maxRows -lt 1 -or $maxRows -gt 200) { Write-Output 'MAX must be a number from 1 to 200'; exit 3 } }

$info = Get-WinEvent -ListLog $log -ErrorAction SilentlyContinue
if (-not $info) { Write-Output "Event log '$log' does not exist"; exit 3 }
try {
    $events = @(Get-WinEvent -FilterHashtable @{ LogName = $log; Level = 1, 2; StartTime = (Get-Date).AddHours(-$hours) } -ErrorAction SilentlyContinue)
} catch { $events = @() }
if ($events.Count -eq 0) { Write-Output "No critical or error events in '$log' during the last $hours hours"; exit 0 }
$groups = $events | Group-Object -Property ProviderName, Id | Sort-Object -Property Count -Descending
Write-Output ("{0} critical/error events in '{1}' during the last {2} hours, {3} distinct provider/id pairs" -f $events.Count, $log, $hours, @($groups).Count)
foreach ($g in ($groups | Select-Object -First $maxRows)) {
    $first = $g.Group | Select-Object -First 1
    $line = ([string]$first.Message -split "`r?`n")[0]
    if ($line.Length -gt 60) { $line = $line.Substring(0, 60) }
    Write-Output ("{0,5}x {1} id {2} last {3:MM-dd HH:mm}: {4}" -f $g.Count, $first.ProviderName, $first.Id, $first.TimeCreated, $line)
}
exit 0

# Points Windows and volume-licensed Office at a KMS host and activates them.
# Variables:
#   ACTION        activate (default), status, clear
#   KMS_HOST      host name or IP of the KMS host; host:port is accepted
#   KMS_PORT      1688
#   PRODUCTS      all (default), windows, office
#   INSTALL_GVLK  false. true first replaces the Windows key with the generic volume
#                 license key of this edition when Windows is not a KMS client yet.
# Exit codes: 0 ok, 1 activation failed or a product is not licensed, 3 bad input or nothing to do

$ErrorActionPreference = 'Stop'

$windowsApp = '55c92734-d682-4d71-983e-d6ec3f16059f'
$officeApp = '0ff1ce15-a989-479d-af46-f275c6370663'
$states = @('unlicensed', 'licensed', 'initial grace period', 'additional grace period',
    'non-genuine grace period', 'notification', 'extended grace period')
$hints = @{
    'C004F074' = 'the KMS host did not answer'
    'C004F038' = 'the KMS host has not reached its minimum client count yet'
    'C004F042' = 'the KMS host has no key for this product'
    'C004F06C' = 'the clocks of this computer and the KMS host differ too much'
}

# Generic volume license keys as published by Microsoft, by EditionID.
$gvlk = @{
    'Professional'             = 'W269N-WFGWX-YVC9B-4J6C9-T83GX'
    'ProfessionalN'            = 'MH37W-N47XK-V7XM9-C7227-GCQG9'
    'ProfessionalWorkstation'  = 'NRG8B-VKK3Q-CXVCJ-9G2XF-6Q84J'
    'ProfessionalWorkstationN' = '9FNHH-K3HBT-3W4TD-6383H-6XYWF'
    'ProfessionalEducation'    = '6TP4R-GNPTD-KYYHQ-7B7DP-J447Y'
    'ProfessionalEducationN'   = 'YVWGF-BXNMC-HTQYQ-CPQ99-66QFC'
    'Education'                = 'NW6C2-QMPVW-D7KKK-3GKT6-VCFB2'
    'EducationN'               = '2WH4N-8QGBV-H22JP-CT43Q-MDWWJ'
    'Enterprise'               = 'NPPR9-FWDCX-D2C8J-H872K-2YT43'
    'EnterpriseN'              = 'DPH2V-TTNVB-4X9Q3-TJR4H-KHJW4'
    'EnterpriseG'              = 'YYVX9-NTFWV-6MDM3-9PT4T-4M68B'
    'EnterpriseGN'             = '44RPN-FTY23-9VTTB-MP9BX-T84FV'
}
# Server and LTSC keys change with the release: EditionID, then build number.
$gvlkByBuild = @{
    'EnterpriseS'      = @{ 14393 = 'DCPHK-NFMTC-H88MJ-PFHPY-QJ4BJ'; 17763 = 'M7XTQ-FN8P6-TTKYV-9D4CC-J462D'; 19044 = 'M7XTQ-FN8P6-TTKYV-9D4CC-J462D'; 26100 = 'M7XTQ-FN8P6-TTKYV-9D4CC-J462D' }
    'EnterpriseSN'     = @{ 14393 = 'QFFDN-GRT3P-VKWWX-X7T3R-8B639'; 17763 = '92NFX-8DJQP-P6BBQ-THF9C-7CG2H'; 19044 = '92NFX-8DJQP-P6BBQ-THF9C-7CG2H'; 26100 = '92NFX-8DJQP-P6BBQ-THF9C-7CG2H' }
    'IoTEnterpriseS'   = @{ 19044 = 'KBN8V-HFGQ4-MGXVD-347P6-PDQGT'; 26100 = 'KBN8V-HFGQ4-MGXVD-347P6-PDQGT' }
    'ServerStandard'   = @{ 14393 = 'WC2BQ-8NRM3-FDDYY-2BFGV-KHKQY'; 17763 = 'N69G4-B89J2-4G8F4-WWYCC-J464C'; 20348 = 'VDYBN-27WPP-V4HQT-9VMD4-VMK7H'; 26100 = 'TVRH6-WHNXV-R9WG3-9XRFY-MY832' }
    'ServerDatacenter' = @{ 14393 = 'CB7KF-BWN84-R7R2Y-793K2-8XDDG'; 17763 = 'WMDGN-G9PQG-XVVXX-R3X43-63DFG'; 20348 = 'WX4NM-KYWYW-QJJR4-XV3QB-6VM33'; 26100 = 'D764K-2NDRG-47T6Q-P8T8W-YP6DF' }
    'ServerTurbine'    = @{ 20348 = 'NTBV8-9K7Q8-V27C6-M2BTV-KHMXV'; 26100 = 'XGN3F-F394H-FD2MY-PP6FD-8MCRC' }
    'ServerSolution'   = @{ 14393 = 'JCKRF-N37P4-C2D82-9YXRT-4M63B'; 17763 = 'WVDHN-86M7X-466P6-VHXV7-YY726' }
}

function Stop-Script([string]$Message, [int]$Code) {
    [Console]::Out.WriteLine($Message)
    exit $Code
}

function Get-Choice([string]$Name, [string]$Value, [string[]]$Allowed) {
    $v = "$Value".Trim().ToLower()
    if (-not $v) { return $Allowed[0] }
    if ($Allowed -notcontains $v) { Stop-Script "$Name must be one of: $($Allowed -join ', ')." 3 }
    return $v
}

function Get-License([string]$AppId) {
    @(Get-CimInstance -ClassName SoftwareLicensingProduct -Filter "ApplicationID='$AppId' AND PartialProductKey IS NOT NULL" |
            Where-Object { -not $_.LicenseIsAddon })
}

function Get-Channel($Product) {
    if ("$($Product.Description)" -match ',\s*(\S+) channel') { return $Matches[1] }
    return 'unknown'
}

function Format-License($Product) {
    $index = [int]$Product.LicenseStatus
    $state = if ($index -ge 0 -and $index -lt $states.Count) { $states[$index] } else { "status $index" }
    $line = '{0}: {1}, {2} key' -f $Product.Name, $state, (Get-Channel $Product)
    if ($Product.GracePeriodRemaining -gt 0) {
        $line += ', {0} days left' -f [math]::Floor($Product.GracePeriodRemaining / 1440)
    }
    return $line
}

# The licensing error sits in the WMI error record when there is one.
function Get-ErrorCode($ErrorRecord) {
    $ex = $ErrorRecord.Exception
    $value = $ex.HResult
    if ($ex.PSObject.Properties['ErrorData'] -and $ex.ErrorData) {
        $prop = $ex.ErrorData.CimInstanceProperties['error_Code']
        if ($prop -and $null -ne $prop.Value) { $value = $prop.Value }
    }
    return '{0:X8}' -f $value
}

function Test-KmsPort([string]$Name, [int]$Port) {
    try { $addresses = [System.Net.Dns]::GetHostAddresses($Name) } catch { return $false }
    foreach ($address in $addresses) {
        $client = New-Object System.Net.Sockets.TcpClient($address.AddressFamily)
        try {
            $pending = $client.BeginConnect($address, $Port, $null, $null)
            if ($pending.AsyncWaitHandle.WaitOne(5000)) {
                $client.EndConnect($pending)
                return $true
            }
        }
        catch { continue }
        finally { $client.Close() }
    }
    return $false
}

# Returns an empty string when the product is licensed afterwards, else the reason.
function Invoke-Activation($Service, $Product) {
    try {
        Invoke-CimMethod -InputObject $Product -MethodName Activate | Out-Null
    }
    catch {
        $code = Get-ErrorCode $_
        $hint = if ($hints.ContainsKey($code)) { $hints[$code] } else { "$($_.Exception.Message)".Trim() }
        return "0x$code $hint".Trim()
    }
    Invoke-CimMethod -InputObject $Service -MethodName RefreshLicenseStatus | Out-Null
    $after = Get-CimInstance -ClassName SoftwareLicensingProduct -Filter "ID='$($Product.ID)'"
    if ($after.LicenseStatus -ne 1) { return 'the product is still not licensed' }
    return ''
}

$action = Get-Choice 'ACTION' $env:ACTION @('activate', 'status', 'clear')
$products = Get-Choice 'PRODUCTS' $env:PRODUCTS @('all', 'windows', 'office')
$installGvlk = (Get-Choice 'INSTALL_GVLK' $env:INSTALL_GVLK @('false', 'true')) -eq 'true'
$doWindows = $products -ne 'office'
$doOffice = $products -ne 'windows'

try {
    $service = Get-CimInstance -ClassName SoftwareLicensingService
}
catch {
    Stop-Script "The software licensing service cannot be read: $($_.Exception.Message)" 1
}

if ($action -eq 'status') {
    $all = @()
    if ($doWindows) { $all += Get-License $windowsApp }
    if ($doOffice) { $all += Get-License $officeApp }
    if (-not $all) { Stop-Script 'No licensed product found.' 3 }
    $open = @($all | Where-Object { $_.LicenseStatus -ne 1 }).Count
    Write-Output ('{0} of {1} products licensed' -f ($all.Count - $open), $all.Count)
    foreach ($p in $all) { Write-Output (Format-License $p) }
    $set = "$($service.KeyManagementServiceMachine)".Trim()
    $found = "$($service.DiscoveredKeyManagementServiceMachineName)".Trim()
    if ($set) {
        Write-Output "KMS host set for Windows: ${set}:$($service.KeyManagementServicePort)"
    }
    elseif ($found) {
        Write-Output "KMS host found by DNS for Windows: ${found}:$($service.DiscoveredKeyManagementServiceMachinePort)"
    }
    else {
        Write-Output 'KMS host for Windows: none set, DNS discovery'
    }
    if ($open) { exit 1 }
    exit 0
}

if ($action -eq 'clear') {
    if ($doWindows) {
        Invoke-CimMethod -InputObject $service -MethodName ClearKeyManagementServiceMachine | Out-Null
        Invoke-CimMethod -InputObject $service -MethodName ClearKeyManagementServicePort | Out-Null
        Write-Output 'Windows: KMS host removed, DNS discovery applies again.'
    }
    if ($doOffice) {
        foreach ($p in (Get-License $officeApp | Where-Object { (Get-Channel $_) -eq 'VOLUME_KMSCLIENT' })) {
            Invoke-CimMethod -InputObject $p -MethodName ClearKeyManagementServiceMachine | Out-Null
            Invoke-CimMethod -InputObject $p -MethodName ClearKeyManagementServicePort | Out-Null
            Write-Output "$($p.Name): KMS host removed."
        }
    }
    exit 0
}

$kmsHost = "$env:KMS_HOST".Trim()
$kmsPort = "$env:KMS_PORT".Trim()
if ($kmsHost -match '^\[([0-9A-Fa-f:]+)\]:(\d{1,5})$' -or $kmsHost -match '^([^:\[\]]+):(\d{1,5})$') {
    $kmsHost = $Matches[1]
    $kmsPort = $Matches[2]
}
if (-not $kmsHost) { Stop-Script 'KMS_HOST is required: host name or IP of your KMS host.' 3 }
$address = $null
$isName = $kmsHost -match '^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$'
if (-not $isName -and -not [System.Net.IPAddress]::TryParse($kmsHost, [ref]$address)) {
    Stop-Script 'KMS_HOST is not a host name or an IP address.' 3
}
if (-not $kmsPort) { $kmsPort = '1688' }
if ($kmsPort -notmatch '^\d{1,5}$' -or [int]$kmsPort -lt 1 -or [int]$kmsPort -gt 65535) {
    Stop-Script 'KMS_PORT must be a number from 1 to 65535.' 3
}
$kmsPort = [int]$kmsPort

if (-not (Test-KmsPort $kmsHost $kmsPort)) {
    Stop-Script "The KMS host ${kmsHost}:$kmsPort cannot be reached over TCP." 1
}

$done = 0
$failed = 0

if ($doWindows) {
    $os = Get-CimInstance -ClassName Win32_OperatingSystem
    $edition = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion').EditionID -replace '^(Server\w+)Cor$', '$1'
    $windows = @(Get-License $windowsApp | Sort-Object { (Get-Channel $_) -ne 'VOLUME_KMSCLIENT' })[0]
    $channel = if ($windows) { Get-Channel $windows } else { 'no' }

    if ($channel -ne 'VOLUME_KMSCLIENT') {
        $key = $gvlk[$edition]
        if (-not $key -and $gvlkByBuild.ContainsKey($edition)) { $key = $gvlkByBuild[$edition][[int]$os.BuildNumber] }
        if ($edition -like 'Core*') {
            Write-Output 'Windows: Home editions cannot be activated by KMS.'
        }
        elseif (-not $installGvlk) {
            Write-Output "Windows: uses a $channel key. Set INSTALL_GVLK to replace it with the volume license key of this edition."
        }
        elseif (-not $key) {
            Write-Output "Windows: no volume license key known for edition $edition, build $($os.BuildNumber)."
        }
        else {
            try {
                Invoke-CimMethod -InputObject $service -MethodName InstallProductKey -Arguments @{ ProductKey = $key } | Out-Null
                Invoke-CimMethod -InputObject $service -MethodName RefreshLicenseStatus | Out-Null
                Write-Output "Windows: volume license key for $edition installed, replacing the $channel key."
                $windows = @(Get-License $windowsApp | Where-Object { (Get-Channel $_) -eq 'VOLUME_KMSCLIENT' })[0]
            }
            catch {
                Write-Output "Windows: the volume license key was refused (0x$(Get-ErrorCode $_))."
                $failed++
                $windows = $null
            }
        }
        if ($windows -and (Get-Channel $windows) -ne 'VOLUME_KMSCLIENT') { $windows = $null }
    }

    if ($windows) {
        Invoke-CimMethod -InputObject $service -MethodName SetKeyManagementServiceMachine -Arguments @{ MachineName = $kmsHost } | Out-Null
        Invoke-CimMethod -InputObject $service -MethodName SetKeyManagementServicePort -Arguments @{ PortNumber = [uint32]$kmsPort } | Out-Null
        $reason = Invoke-Activation $service $windows
        if ($reason) {
            Write-Output "Windows: activation failed, $reason"
            $failed++
        }
        else {
            Write-Output "Windows: activated through ${kmsHost}:$kmsPort"
            $done++
        }
    }
}

if ($doOffice) {
    $office = @(Get-License $officeApp | Where-Object { (Get-Channel $_) -eq 'VOLUME_KMSCLIENT' })
    if (-not $office) {
        Write-Output 'Office: no volume-licensed Office found. Microsoft 365 Apps and retail Office do not use KMS.'
    }
    foreach ($p in $office) {
        Invoke-CimMethod -InputObject $p -MethodName SetKeyManagementServiceMachine -Arguments @{ MachineName = $kmsHost } | Out-Null
        Invoke-CimMethod -InputObject $p -MethodName SetKeyManagementServicePort -Arguments @{ PortNumber = [uint32]$kmsPort } | Out-Null
        $reason = Invoke-Activation $service $p
        if ($reason) {
            Write-Output "$($p.Name): activation failed, $reason"
            $failed++
        }
        else {
            Write-Output "$($p.Name): activated through ${kmsHost}:$kmsPort"
            $done++
        }
    }
}

if ($failed) { exit 1 }
if (-not $done) { exit 3 }
exit 0

# Enables Win32 long path support (paths over 260 characters) for applications that declare it.
# Variables: none.
# Exit: 0 enabled or already enabled, 1 failed, 3 Windows too old.
$build = [int](Get-CimInstance Win32_OperatingSystem).BuildNumber
if ($build -lt 14393) { Write-Output "Long paths need Windows 10 1607 or Server 2016 (build 14393), this is build $build"; exit 3 }
$key = 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem'
try {
    $cur = (Get-ItemProperty -LiteralPath $key -Name LongPathsEnabled -ErrorAction SilentlyContinue).LongPathsEnabled
    if ($cur -eq 1) { Write-Output 'LongPathsEnabled is already 1'; exit 0 }
    New-ItemProperty -LiteralPath $key -Name LongPathsEnabled -Value 1 -PropertyType DWord -Force -ErrorAction Stop | Out-Null
    Write-Output 'LongPathsEnabled set to 1; running applications pick it up after a restart'
    exit 0
} catch {
    Write-Output "Failed: $($_.Exception.Message)"
    exit 1
}

# Shows, enables or disables a Windows optional feature or server role/feature. Client Windows uses the DISM cmdlets (example: NetFx3 for .NET 3.5), Windows Server uses ServerManager (example: NET-Framework-Core).
# Variables: FEATURE feature name; STATE (status) status, enable or disable.
# Exit: 0 done, 1 failed, 3 bad input, unknown feature or tooling missing.
$feature = ''
if ($env:FEATURE) { $feature = $env:FEATURE.Trim() }
if ($feature -notmatch '^[A-Za-z0-9._-]{2,100}$') { Write-Output 'FEATURE is required: letters, digits, dot, dash and underscore only'; exit 3 }
$state = 'status'
if ($env:STATE) { $state = $env:STATE.Trim().ToLower() }
if ('status', 'enable', 'disable' -notcontains $state) { Write-Output 'STATE must be status, enable or disable'; exit 3 }
$server = (Get-CimInstance Win32_OperatingSystem).ProductType -ne 1

try {
    if ($server) {
        $getF = Get-Command -Name Get-WindowsFeature -ErrorAction SilentlyContinue
        if (-not $getF) { Write-Output 'The ServerManager module is not available on this system'; exit 3 }
        try { $f = & $getF -Name $feature -ErrorAction Stop } catch { $f = $null }
        if (-not $f) { Write-Output "Unknown feature '$feature'; list names with Get-WindowsFeature"; exit 3 }
        $on = [bool]$f.Installed
        Write-Output "$($f.Name) ($($f.DisplayName)): installed=$on"
        if ($state -eq 'enable' -and -not $on) {
            $r = & (Get-Command -Name Install-WindowsFeature) -Name $feature -ErrorAction Stop
        } elseif ($state -eq 'disable' -and $on) {
            $r = & (Get-Command -Name Uninstall-WindowsFeature) -Name $feature -ErrorAction Stop
        } else { exit 0 }
        Write-Output "Success=$($r.Success), restart needed=$($r.RestartNeeded), exit code=$($r.ExitCode)"
        if ($r.Success) { exit 0 }
        exit 1
    }
    if (-not (Get-Command Get-WindowsOptionalFeature -ErrorAction SilentlyContinue)) { Write-Output 'The DISM PowerShell module is not available on this system'; exit 3 }
    try { $f = Get-WindowsOptionalFeature -Online -FeatureName $feature -ErrorAction Stop }
    catch { Write-Output "Unknown feature '$feature'; list names with Get-WindowsOptionalFeature -Online"; exit 3 }
    $cur = $f.State.ToString()
    Write-Output "$($f.FeatureName): $cur"
    $r = $null
    if ($state -eq 'enable' -and $cur -notlike 'Enable*') {
        $r = Enable-WindowsOptionalFeature -Online -FeatureName $feature -All -NoRestart -ErrorAction Stop
    } elseif ($state -eq 'disable' -and $cur -notlike 'Disable*') {
        $r = Disable-WindowsOptionalFeature -Online -FeatureName $feature -NoRestart -ErrorAction Stop
    }
    if ($r) {
        $now = (Get-WindowsOptionalFeature -Online -FeatureName $feature).State
        Write-Output "Now: $now, restart needed: $($r.RestartNeeded)"
    }
    exit 0
} catch {
    Write-Output "Failed: $($_.Exception.Message)"
    exit 1
}

# Renames the computer; on a domain member the account rename needs domain credentials. The new name is active after a restart.
# Variables: NEW_NAME new computer name; RESTART (false) restart in 30 seconds; DOMAIN_USERNAME and DOMAIN_PASSWORD domain account allowed to rename the computer object (domain members only).
# Exit: 0 renamed or already named so, 1 failed, 3 bad input.
$new = ''
if ($env:NEW_NAME) { $new = $env:NEW_NAME.Trim() }
if ($new -notmatch '^[A-Za-z0-9]([A-Za-z0-9-]{0,13}[A-Za-z0-9])?$' -or $new -match '^[0-9]+$') {
    Write-Output 'NEW_NAME must be 1-15 letters, digits or dashes, not start or end with a dash and not be only digits'
    exit 3
}
$cs = Get-CimInstance Win32_ComputerSystem
if ($cs.Name -ieq $new) { Write-Output "The computer is already named $new"; exit 0 }
$pending = (Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ComputerName' -ErrorAction SilentlyContinue).ComputerName
$user = $env:DOMAIN_USERNAME
$cred = $null
if ($cs.PartOfDomain -and $pending -ine $new) {
    if (-not $user -or -not $env:DOMAIN_PASSWORD) { Write-Output "The computer is a member of $($cs.Domain); DOMAIN_USERNAME and DOMAIN_PASSWORD are required"; exit 3 }
    $sec = ConvertTo-SecureString -String $env:DOMAIN_PASSWORD -AsPlainText -Force
    $cred = New-Object System.Management.Automation.PSCredential ($user.Trim(), $sec)
}
try {
    if ($pending -ieq $new) { Write-Output "The rename to $new is already done and waits for a restart" }
    else {
        if ($cred) { Rename-Computer -NewName $new -DomainCredential $cred -Force -ErrorAction Stop }
        else { Rename-Computer -NewName $new -Force -ErrorAction Stop }
        Write-Output "Renamed $($cs.Name) to $new, active after a restart"
    }
    if ($env:RESTART -eq 'true') {
        & (Join-Path $env:windir 'System32\shutdown.exe') /r /t 30 /c 'Restart after computer rename' 2>&1 | Out-Null
        if ($LASTEXITCODE -eq 0) { Write-Output 'Restart scheduled in 30 seconds' }
        else { Write-Output "Restart could not be scheduled (shutdown.exe exit code $LASTEXITCODE), restart manually" }
    }
    exit 0
} catch {
    Write-Output "Rename failed: $($_.Exception.Message)"
    exit 1
}

# Measures the clock offset against the configured time source over SNTP and optionally resyncs the clock.
# Variables: MAX_OFFSET_SECONDS (60) allowed offset; RESYNC (false) run w32tm /resync when the offset is too large.
# Exit: 0 clock within the limit, 1 offset too large, 2 offset could not be measured, 3 bad input.
$max = 60
if ($env:MAX_OFFSET_SECONDS) {
    if (-not [int]::TryParse($env:MAX_OFFSET_SECONDS.Trim(), [ref]$max) -or $max -lt 1 -or $max -gt 86400) { Write-Output 'MAX_OFFSET_SECONDS must be a number from 1 to 86400'; exit 3 }
}
$resync = $env:RESYNC -eq 'true'
$w32 = Join-Path $env:windir 'System32\w32tm.exe'

function Get-Source {
    $list = @()
    $src = (& $w32 /query /source 2>&1 | Out-String).Trim()
    if ($src -match '^[A-Za-z0-9][A-Za-z0-9.\-]*(,0x[0-9a-fA-F]+)?$' -and $src -notmatch '^Local|^Free') { $list += ($src -split ',')[0] }
    $ntp = (Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\W32Time\Parameters' -ErrorAction SilentlyContinue).NtpServer
    foreach ($s in ([string]$ntp -split '\s+')) {
        $h = ($s -split ',')[0]
        if ($h) { $list += $h }
    }
    $list += 'time.windows.com'
    return @($list | Select-Object -Unique)
}

function Get-Offset([string]$Server) {
    $udp = New-Object System.Net.Sockets.UdpClient
    try {
        $udp.Client.ReceiveTimeout = 3000
        $udp.Connect($Server, 123)
        $req = New-Object byte[] 48
        $req[0] = 0x1B
        $t1 = [DateTime]::UtcNow
        [void]$udp.Send($req, 48)
        $ep = New-Object System.Net.IPEndPoint ([System.Net.IPAddress]::Any, 0)
        $resp = $udp.Receive([ref]$ep)
        $t4 = [DateTime]::UtcNow
        if ($resp.Length -lt 48 -or $resp[1] -eq 0) { return $null }
        $secs = [double]0
        $frac = [double]0
        for ($i = 0; $i -lt 4; $i++) { $secs = $secs * 256 + $resp[40 + $i]; $frac = $frac * 256 + $resp[44 + $i] }
        $remote = (New-Object DateTime 1900, 1, 1, 0, 0, 0, ([DateTimeKind]::Utc)).AddSeconds($secs + $frac / 4294967296)
        $mid = $t1.AddTicks([int64](($t4 - $t1).Ticks / 2))
        return ($remote - $mid).TotalSeconds
    } catch { return $null }
    finally { $udp.Close() }
}

function Measure-Clock {
    foreach ($s in (Get-Source)) {
        $o = Get-Offset $s
        if ($null -ne $o) { return @{ Server = $s; Offset = $o } }
    }
    return $null
}

$svc = Get-Service -Name W32Time -ErrorAction SilentlyContinue
$notes = @()
if ($svc) { $notes += "Windows Time service: $($svc.Status)" }
$m = Measure-Clock
if (-not $m) { Write-Output 'WARNING: no time server answered on UDP 123, offset unknown'; Write-Output $notes; exit 2 }
$off = [math]::Abs($m.Offset)
if ($off -gt $max -and $resync) {
    if ($svc -and $svc.Status -ne 'Running') { Start-Service -Name W32Time -ErrorAction SilentlyContinue }
    & $w32 /resync 2>&1 | Out-Null
    $notes += "Resync requested, w32tm exit code $LASTEXITCODE"
    Start-Sleep -Seconds 3
    $m2 = Measure-Clock
    if ($m2) { $m = $m2; $off = [math]::Abs($m.Offset) }
}
$text = "clock offset against {0}: {1:N2} s (limit {2} s)" -f $m.Server, $m.Offset, $max
if ($off -gt $max) { Write-Output "CRITICAL: $text"; Write-Output $notes; exit 1 }
Write-Output "OK: $text"
Write-Output $notes
exit 0

# Shows the time zone or sets it by Windows time zone id (for example W. Europe Standard Time).
# Variables: TIMEZONE time zone id; empty reports the current zone and the clock.
# Exit: 0 done, 1 failed, 3 unknown time zone id.
$id = ''
if ($env:TIMEZONE) { $id = $env:TIMEZONE.Trim() }
try {
    $cur = Get-TimeZone
    if (-not $id) {
        Write-Output "Time zone: $($cur.Id) ($($cur.DisplayName))"
        Write-Output "Local time: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"
        exit 0
    }
    $zone = Get-TimeZone -ListAvailable | Where-Object { $_.Id -ieq $id }
    if (-not $zone) { Write-Output "Unknown time zone id '$id'; list them with Get-TimeZone -ListAvailable"; exit 3 }
    if ($cur.Id -eq $zone.Id) { Write-Output "Time zone is already $($zone.Id)"; exit 0 }
    Set-TimeZone -Id $zone.Id -ErrorAction Stop
    Write-Output "Time zone changed from $($cur.Id) to $($zone.Id)"
    exit 0
} catch {
    Write-Output "Failed: $($_.Exception.Message)"
    exit 1
}

# Pins a Windows 10 or 11 PC to a feature update version with the TargetReleaseVersion policy.
# Variables: ACTION (status) status, set or clear; PRODUCT (Windows 11) Windows 10 or Windows 11; VERSION release such as 24H2.
# Exit: 0 done, 1 failed, 3 bad input or not a client Windows.
$action = 'status'
if ($env:ACTION) { $action = $env:ACTION.Trim().ToLower() }
if ('status', 'set', 'clear' -notcontains $action) { Write-Output 'ACTION must be status, set or clear'; exit 3 }
$product = 'Windows 11'
if ($env:PRODUCT) { $product = $env:PRODUCT.Trim() }
if ('Windows 10', 'Windows 11' -notcontains $product) { Write-Output 'PRODUCT must be Windows 10 or Windows 11'; exit 3 }
$version = ''
if ($env:VERSION) { $version = $env:VERSION.Trim().ToUpper() }
if ($action -eq 'set' -and $version -notmatch '^[0-9]{2}H[12]$') { Write-Output 'VERSION must look like 24H2'; exit 3 }
if ((Get-CimInstance Win32_OperatingSystem).ProductType -ne 1) { Write-Output 'The policy only applies to client Windows, not to Windows Server'; exit 3 }

$key = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'
$values = 'TargetReleaseVersion', 'ProductVersion', 'TargetReleaseVersionInfo'
try {
    if ($action -eq 'set') {
        if (-not (Test-Path -LiteralPath $key)) { New-Item -Path $key -Force | Out-Null }
        New-ItemProperty -LiteralPath $key -Name TargetReleaseVersion -Value 1 -PropertyType DWord -Force -ErrorAction Stop | Out-Null
        New-ItemProperty -LiteralPath $key -Name ProductVersion -Value $product -PropertyType String -Force -ErrorAction Stop | Out-Null
        New-ItemProperty -LiteralPath $key -Name TargetReleaseVersionInfo -Value $version -PropertyType String -Force -ErrorAction Stop | Out-Null
        Write-Output "Feature update target set to $product $version"
    } elseif ($action -eq 'clear') {
        $removed = 0
        foreach ($v in $values) {
            if (Get-ItemProperty -LiteralPath $key -Name $v -ErrorAction SilentlyContinue) {
                Remove-ItemProperty -LiteralPath $key -Name $v -ErrorAction Stop
                $removed++
            }
        }
        Write-Output "Feature update target cleared ($removed policy values removed)"
    }
    $p = Get-ItemProperty -LiteralPath $key -ErrorAction SilentlyContinue
    if ($p -and $p.TargetReleaseVersion -eq 1) {
        Write-Output "Current target: $($p.ProductVersion) $($p.TargetReleaseVersionInfo)"
    } else {
        Write-Output 'Current target: none, feature updates follow the normal offer'
    }
    exit 0
} catch {
    Write-Output "Failed: $($_.Exception.Message)"
    exit 1
}

# Starts an update of Microsoft 365 Apps (Click-to-Run) through OfficeC2RClient.exe; the update then continues in the background.
# Variables: FORCE_CLOSE (false) close open Office apps so the update does not wait.
# Exit: 0 update started, 1 failed, 3 Click-to-Run Office is not installed.
$client = Join-Path $env:CommonProgramFiles 'microsoft shared\ClickToRun\OfficeC2RClient.exe'
if (-not (Test-Path -LiteralPath $client)) {
    $x86 = ${env:CommonProgramFiles(x86)}
    if ($x86) { $client = Join-Path $x86 'microsoft shared\ClickToRun\OfficeC2RClient.exe' }
}
if (-not (Test-Path -LiteralPath $client)) { Write-Output 'Click-to-Run Office is not installed (OfficeC2RClient.exe not found)'; exit 3 }
$cfg = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Office\ClickToRun\Configuration' -ErrorAction SilentlyContinue
if ($cfg) { Write-Output "Version before: $($cfg.VersionToReport), channel: $($cfg.CDNBaseUrl)" }
$force = 'false'
if ($env:FORCE_CLOSE -eq 'true') { $force = 'true' }
try {
    $p = Start-Process -FilePath $client -ArgumentList @('/update', 'user', 'displaylevel=false', "forceappshutdown=$force") -Wait -PassThru
    Write-Output "OfficeC2RClient exit code $($p.ExitCode); the update continues in the background (force close: $force)"
    if ($p.ExitCode -eq 0) { exit 0 }
    exit 1
} catch {
    Write-Output "Failed to start the update: $($_.Exception.Message)"
    exit 1
}

# Undoes the automatic update policy of the RMM agent: removes the AUOptions value it writes under the Windows Update policy key, so Windows manages updates again.
# Variables: none.
# Exit: 0 done or already in place, 1 failed.
$key = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU'
try {
    if (-not (Test-Path -LiteralPath $key)) { Write-Output 'No automatic update policy key, nothing to restore'; exit 0 }
    $p = Get-ItemProperty -LiteralPath $key
    if ($null -ne $p.AUOptions) {
        Remove-ItemProperty -LiteralPath $key -Name AUOptions -ErrorAction Stop
        Write-Output "Removed AUOptions ($($p.AUOptions)) from the Windows Update policy"
    } else {
        Write-Output 'AUOptions is not set, already in place'
    }
    $left = @((Get-Item -LiteralPath $key).Property)
    $sub = @(Get-ChildItem -LiteralPath $key -ErrorAction SilentlyContinue)
    if ($left.Count -eq 0 -and $sub.Count -eq 0) {
        Remove-Item -LiteralPath $key -ErrorAction Stop
        Write-Output 'Removed the empty policy key'
    } elseif ($left.Count -gt 0) {
        Write-Output "Other policy values remain and were not touched: $($left -join ', ')"
    }
    exit 0
} catch {
    Write-Output "Failed: $($_.Exception.Message)"
    exit 1
}

# Checks the Windows 11 hardware requirements: 64-bit, 2+ cores, 1 GHz, 4 GB RAM, 64 GB system disk, UEFI, Secure Boot capable, TPM 2.0. The CPU model list is NOT checked.
# Variables: none.
# Exit: 0 all checks pass, 1 at least one check fails, 3 not a client Windows.
$ErrorActionPreference = 'Stop'
if ((Get-CimInstance Win32_OperatingSystem).ProductType -ne 1) { Write-Output 'Windows 11 readiness only applies to client Windows, not to Windows Server'; exit 3 }
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class FwType {
    [DllImport("kernel32.dll")]
    public static extern bool GetFirmwareType(ref uint type);
}
'@
$fail = 0
$lines = @()
function Write-Check([string]$Label, [bool]$Ok, [string]$Detail) {
    $tag = 'FAIL'
    if ($Ok) { $tag = 'ok  ' } else { $script:fail++ }
    $script:lines += ("{0} {1}: {2}" -f $tag, $Label, $Detail)
}
try {
    $cpu = @(Get-CimInstance Win32_Processor)
    $cs = Get-CimInstance Win32_ComputerSystem
    $arch = ($cpu | Select-Object -First 1).AddressWidth
    Write-Check '64-bit CPU' ($arch -eq 64) "address width $arch"
    $cores = ($cpu | Measure-Object -Property NumberOfCores -Sum).Sum
    Write-Check 'Cores' ($cores -ge 2) "$cores"
    $mhz = ($cpu | Measure-Object -Property MaxClockSpeed -Minimum).Minimum
    Write-Check 'Clock' ($mhz -ge 1000) "$mhz MHz"
    $ram = [double](@(Get-CimInstance Win32_PhysicalMemory) | Measure-Object -Property Capacity -Sum).Sum
    if ($ram -le 0) { $ram = $cs.TotalPhysicalMemory }
    $ramGb = [math]::Round($ram / 1GB, 1)
    Write-Check 'RAM' ($ramGb -ge 3.8) "$ramGb GB (4 GB needed)"
    $disk = Get-CimInstance Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $env:SystemDrive)
    $diskGb = [math]::Round($disk.Size / 1GB, 0)
    Write-Check 'System disk' ($diskGb -ge 60) "$diskGb GB (64 GB needed)"

    $fw = [uint32]0
    $uefi = $false
    if ([FwType]::GetFirmwareType([ref]$fw)) { $uefi = ($fw -eq 2) }
    Write-Check 'UEFI firmware' $uefi $(if ($uefi) { 'UEFI' } else { 'legacy BIOS' })
    $sb = $false
    $sbDetail = 'not supported'
    if ($uefi) {
        try {
            $on = Confirm-SecureBootUEFI
            $sb = $true
            $sbDetail = if ($on) { 'capable, enabled' } else { 'capable, currently off' }
        } catch { $sbDetail = 'not supported by the firmware' }
    }
    Write-Check 'Secure Boot' $sb $sbDetail

    $tpm = $null
    try { $tpm = Get-CimInstance -Namespace 'root\cimv2\Security\MicrosoftTpm' -ClassName Win32_Tpm } catch { $tpm = $null }
    if (-not $tpm) {
        Write-Check 'TPM 2.0' $false 'no TPM found or it is disabled in the firmware'
    } else {
        $spec = [string]$tpm.SpecVersion
        Write-Check 'TPM 2.0' ($spec -like '2.0*') "spec $spec, enabled $($tpm.IsEnabled_InitialValue), activated $($tpm.IsActivated_InitialValue)"
    }
    $lines += "Not checked: CPU model on the supported list ($(($cpu | Select-Object -First 1).Name.Trim()))"
    if ($fail -eq 0) { Write-Output 'RESULT: ready for Windows 11 (CPU list not checked)'; Write-Output $lines; exit 0 }
    Write-Output "RESULT: not ready, $fail check(s) failed"
    Write-Output $lines
    exit 1
} catch {
    Write-Output "Check failed: $($_.Exception.Message)"
    exit 1
}

# Resets the Windows Update components: stops the services, renames the SoftwareDistribution and catroot2 folders, clears the BITS queue and starts the services again.
# Variables: none.
# Exit: 0 done, 1 failed.
$ErrorActionPreference = 'Stop'
$names = 'wuauserv', 'bits', 'cryptsvc', 'msiserver'
$running = @()
try {
    foreach ($n in $names) {
        $s = Get-Service -Name $n -ErrorAction SilentlyContinue
        if ($s -and $s.Status -ne 'Stopped') {
            $running += $n
            $running += @($s.DependentServices | Where-Object { $_.Status -eq 'Running' } | ForEach-Object { $_.Name })
            Stop-Service -Name $n -Force -ErrorAction SilentlyContinue
            $s.WaitForStatus('Stopped', [TimeSpan]::FromSeconds(60))
        }
    }
    $targets = @(
        (Join-Path $env:windir 'SoftwareDistribution'),
        (Join-Path $env:windir 'System32\catroot2')
    )
    foreach ($t in $targets) {
        if (-not (Test-Path -LiteralPath $t)) { Write-Output "$t does not exist, skipped"; continue }
        $old = $t + '.bak'
        if (Test-Path -LiteralPath $old) { Remove-Item -LiteralPath $old -Recurse -Force }
        Rename-Item -LiteralPath $t -NewName ((Split-Path -Leaf $t) + '.bak')
        Write-Output "Renamed $t to $old"
    }
    $q = Join-Path $env:ALLUSERSPROFILE 'Microsoft\Network\Downloader'
    $files = @(Get-ChildItem -LiteralPath $q -Filter 'qmgr*.dat' -Force -ErrorAction SilentlyContinue)
    $files | Remove-Item -Force -ErrorAction SilentlyContinue
    Write-Output "BITS queue files removed: $($files.Count)"
    $failed = @()
    foreach ($n in $running) {
        try { Start-Service -Name $n -ErrorAction Stop } catch { $failed += $n }
    }
    if ($failed.Count -gt 0) { Write-Output "Could not start: $($failed -join ', ')"; exit 1 }
    Write-Output 'Windows Update components reset, services restarted'
    exit 0
} catch {
    Write-Output "Reset failed: $($_.Exception.Message)"
    foreach ($n in $running) { Start-Service -Name $n -ErrorAction SilentlyContinue }
    exit 1
}

# Creates a local user account, optionally as administrator. The password is never printed.
# Variables: TARGET_USER, PASSWORD, FULL_NAME (optional), ADMINISTRATOR (checkbox, default false), PASSWORD_NEVER_EXPIRES (checkbox, default false)
# Exit: 0 created, 1 creation failed or account exists, 3 bad input or local accounts not available
$ErrorActionPreference = 'Stop'
$name = ([string]$env:TARGET_USER).Trim()
$password = [string]$env:PASSWORD
$fullName = ([string]$env:FULL_NAME).Trim()
$admin = ([string]$env:ADMINISTRATOR).Trim().ToLower() -eq 'true'
$neverExpires = ([string]$env:PASSWORD_NEVER_EXPIRES).Trim().ToLower() -eq 'true'
if (-not $name -or $name.Length -gt 20 -or $name -match '["/\\\[\]:;|=,+*?<>@]|\$$' -or $name -match '^[. ]+$' -or $name -match '[. ]$') {
    Write-Output 'Bad TARGET_USER: 1-20 characters, none of " / \ [ ] : ; | = , + * ? < > @ and no trailing $, not ending in a dot or space'
    exit 3
}
if (-not $password) {
    Write-Output 'PASSWORD is required'
    exit 3
}
if ($fullName.Length -gt 100) {
    Write-Output 'FULL_NAME is longer than 100 characters'
    exit 3
}
if (-not (Get-Command New-LocalUser -ErrorAction SilentlyContinue)) {
    Write-Output 'The LocalAccounts cmdlets are not available on this system'
    exit 3
}
try {
    if (Get-LocalUser -Name $name -ErrorAction SilentlyContinue) {
        Write-Output ('Account ' + $name + ' already exists, nothing changed')
        exit 1
    }
    $secure = ConvertTo-SecureString -String $password -AsPlainText -Force
    $params = @{ Name = $name; Password = $secure; AccountNeverExpires = $true; PasswordNeverExpires = $neverExpires }
    if ($fullName) { $params['FullName'] = $fullName }
    [void](New-LocalUser @params)
    $users = Get-LocalGroup -SID 'S-1-5-32-545'
    Add-LocalGroupMember -Group $users -Member $name
    if ($admin) {
        $admins = Get-LocalGroup -SID 'S-1-5-32-544'
        Add-LocalGroupMember -Group $admins -Member $name
    }
} catch {
    Write-Output ('FAIL: ' + $_.Exception.Message)
    exit 1
}
Write-Output ('Created local account ' + $name + ', administrator=' + $admin + ', password never expires=' + $neverExpires)
exit 0

# Enables or disables a local user account.
# Variables: TARGET_USER, STATE (enable or disable)
# Exit: 0 done or already in that state, 1 change failed, 3 bad input or account not found
$ErrorActionPreference = 'Stop'
$name = ([string]$env:TARGET_USER).Trim()
$state = ([string]$env:STATE).Trim().ToLower()
if (-not $name -or $name -match '["/\\\[\]:;|=,+*?<>@]|\$$') {
    Write-Output 'Bad or missing TARGET_USER'
    exit 3
}
if ($state -notin 'enable', 'disable') {
    Write-Output ('Bad STATE value: ' + $state + ' (enable or disable)')
    exit 3
}
if (-not (Get-Command Get-LocalUser -ErrorAction SilentlyContinue)) {
    Write-Output 'The LocalAccounts cmdlets are not available on this system'
    exit 3
}
try {
    $u = Get-LocalUser -Name $name -ErrorAction Stop
} catch {
    Write-Output ('Local account not found: ' + $name)
    exit 3
}
$want = $state -eq 'enable'
if ($u.Enabled -eq $want) {
    Write-Output ('Account ' + $name + ' is already ' + $state + 'd, nothing changed')
    exit 0
}
try {
    if ($want) { Enable-LocalUser -Name $name } else { Disable-LocalUser -Name $name }
} catch {
    Write-Output ('FAIL: ' + $_.Exception.Message)
    exit 1
}
Write-Output ('Account ' + $name + ' ' + $state + 'd')
exit 0

# Lists local user accounts with state, last logon, password expiry and administrator membership.
# Variables: none
# Exit: 0 listed, 3 local accounts not available (domain controller or missing cmdlets)
$ErrorActionPreference = 'Stop'
if (-not (Get-Command Get-LocalUser -ErrorAction SilentlyContinue)) {
    Write-Output 'The LocalAccounts cmdlets are not available on this system'
    exit 3
}
try {
    $users = @(Get-LocalUser)
} catch {
    Write-Output ('Cannot list local users (domain controller?): ' + $_.Exception.Message)
    exit 3
}
# administrators group found by SID, read with net.exe because Get-LocalGroupMember fails on orphaned members
$admins = @()
try {
    $sid = New-Object System.Security.Principal.SecurityIdentifier('S-1-5-32-544')
    $group = $sid.Translate([System.Security.Principal.NTAccount]).Value.Split('\')[-1]
    $out = @(& net.exe localgroup $group 2>&1 | ForEach-Object { ([string]$_).Trim() } | Where-Object { $_ })
    $dash = -1
    for ($i = 0; $i -lt $out.Count; $i++) {
        if ($out[$i] -match '^-{5,}$') { $dash = $i; break }
    }
    if ($dash -ge 0 -and $out.Count - 2 -gt $dash) {
        $admins = @($out[($dash + 1)..($out.Count - 2)] | ForEach-Object { $_.ToLower() })
    }
} catch {
    Write-Output 'Warning: could not read the Administrators group'
}
$prefix = $env:COMPUTERNAME.ToLower() + '\'
Write-Output ('{0} local account(s)' -f $users.Count)
foreach ($u in ($users | Sort-Object Name)) {
    $isAdmin = ($admins -contains $u.Name.ToLower()) -or ($admins -contains ($prefix + $u.Name.ToLower()))
    $last = if ($u.LastLogon) { '{0:yyyy-MM-dd HH:mm}' -f $u.LastLogon } else { 'never' }
    $exp = if ($u.PasswordExpires) { '{0:yyyy-MM-dd}' -f $u.PasswordExpires } else { 'never' }
    Write-Output ('{0,-24} enabled={1,-5} admin={2,-5} lastlogon={3,-16} pwexpires={4}' -f $u.Name, $u.Enabled, $isAdmin, $last, $exp)
