try {
    $sessions = @([UlWts]::List() | Where-Object { $_.User })
} catch {
    Write-Output ('Cannot enumerate sessions: ' + $_.Exception.Message)
    exit 3
}
$all = $target -eq 'ALL'
$short = $target.Split('\')[-1]
$domain = if ($target.Contains('\')) { $target.Split('\')[0] } else { '' }
$hits = @($sessions | Where-Object { $all -or ($_.User -eq $short -and (-not $domain -or $_.Domain -eq $domain)) })
if ($hits.Count -eq 0) {
    Write-Output ('No matching session for ' + $target)
    exit 0
}
$failed = 0
foreach ($s in $hits) {
    if ([UlWts]::WTSLogoffSession([IntPtr]::Zero, $s.Id, $true)) {
        Write-Output ('Logged off session ' + $s.Id + ' (' + $s.Domain + '\' + $s.User + ')')
    } else {
        Write-Output ('FAIL: could not log off session ' + $s.Id + ' (' + $s.Domain + '\' + $s.User + ')')
        $failed++
    }
}
if ($failed -gt 0) { exit 1 }
exit 0

# Shows a message box to all logged-on users with msg.exe.
# Variables: MESSAGE, DISPLAY_SECONDS (optional, default 60, how long the box stays, 5-3600)
# Exit: 0 sent, 1 msg.exe reported an error (for example no session), 3 bad input or msg.exe missing
$ErrorActionPreference = 'Stop'
$message = ([string]$env:MESSAGE).Trim() -replace '"', "'"
$raw = ([string]$env:DISPLAY_SECONDS).Trim()
$seconds = 60
if ($raw) {
    if (-not [int]::TryParse($raw, [ref]$seconds) -or $seconds -lt 5 -or $seconds -gt 3600) {
        Write-Output ('Bad DISPLAY_SECONDS value: ' + $raw + ' (allowed 5-3600)')
        exit 3
    }
}
if (-not $message -or $message.Length -gt 500) {
    Write-Output 'MESSAGE is required and limited to 500 characters'
    exit 3
}
# a leading space keeps msg.exe from reading the text as a switch
if ($message -match '^[/-]') { $message = ' ' + $message }
$msg = Join-Path $env:SystemRoot 'System32\msg.exe'
if (-not (Test-Path $msg)) {
    Write-Output 'msg.exe is not available (Windows Home editions do not include it)'
    exit 3
}
$ErrorActionPreference = 'Continue'
$out = & $msg '*' "/TIME:$seconds" $message 2>&1
$rc = $LASTEXITCODE
$ErrorActionPreference = 'Stop'
if ($rc -ne 0) {
    Write-Output ('msg.exe failed with exit code ' + $rc + ': ' + (($out | ForEach-Object { [string]$_ }) -join ' '))
    exit 1
}
Write-Output ('Message sent to all sessions, shown for ' + $seconds + ' s')
exit 0

# Sets a new password on a local user account, optionally forcing a change at next logon. The password is never printed.
# Variables: TARGET_USER, PASSWORD, MUST_CHANGE (checkbox, default false)
# Exit: 0 password set, 1 change failed, 3 bad input or account not found
$ErrorActionPreference = 'Stop'
$name = ([string]$env:TARGET_USER).Trim()
$password = [string]$env:PASSWORD
$mustChange = ([string]$env:MUST_CHANGE).Trim().ToLower() -eq 'true'
if (-not $name -or $name -match '["/\\\[\]:;|=,+*?<>@]|\$$') {
    Write-Output 'Bad or missing TARGET_USER'
    exit 3
}
if (-not $password) {
    Write-Output 'PASSWORD is required'
    exit 3
}
if (-not (Get-Command Set-LocalUser -ErrorAction SilentlyContinue)) {
    Write-Output 'The LocalAccounts cmdlets are not available on this system'
    exit 3
}
try {
    $u = Get-LocalUser -Name $name -ErrorAction Stop
} catch {
    Write-Output ('Local account not found: ' + $name)
    exit 3
}
try {
    $secure = ConvertTo-SecureString -String $password -AsPlainText -Force
    Set-LocalUser -Name $name -Password $secure
    if ($mustChange) {
        $adsi = [ADSI]('WinNT://' + $env:COMPUTERNAME + '/' + $u.Name + ',user')
        $adsi.Put('PasswordExpired', 1)
        $adsi.SetInfo()
    }
} catch {
    Write-Output ('FAIL: ' + $_.Exception.Message)
    exit 1
}
Write-Output ('Password of ' + $name + ' was reset, change at next logon=' + $mustChange)
exit 0

