# Lists user profiles with path, last use, loaded state and optionally the size on disk. Deletes nothing.
# Variables: SIZES (checkbox, default false, adds the folder size and can take minutes on large profiles)
# Exit: 0 listed, 3 profile information unavailable
$ErrorActionPreference = 'Stop'
$sizes = ([string]$env:SIZES).Trim().ToLower() -eq 'true'

function Get-DirBytes([string]$Path) {
    $total = [long]0
    $stack = New-Object System.Collections.Generic.Stack[string]
    $stack.Push($Path)
    while ($stack.Count -gt 0) {
        $dir = New-Object System.IO.DirectoryInfo($stack.Pop())
        try {
            foreach ($f in $dir.GetFiles()) { $total += $f.Length }
            foreach ($d in $dir.GetDirectories()) {
                if (-not ($d.Attributes -band [System.IO.FileAttributes]::ReparsePoint)) { $stack.Push($d.FullName) }
            }
        } catch {
            Write-Verbose ('skipped ' + $dir.FullName)
        }
    }
    return $total
}

try {
    $profiles = @(Get-CimInstance -ClassName Win32_UserProfile | Where-Object { -not $_.Special })
} catch {
    Write-Output ('Cannot read the profile list: ' + $_.Exception.Message)
    exit 3
}
Write-Output ('{0} user profile(s)' -f $profiles.Count)
foreach ($p in ($profiles | Sort-Object LocalPath)) {
    $name = $p.SID
    try {
        $name = (New-Object System.Security.Principal.SecurityIdentifier($p.SID)).Translate([System.Security.Principal.NTAccount]).Value
    } catch {
        $name = $p.SID + ' (unresolved)'
    }
    $last = if ($p.LastUseTime) { '{0:yyyy-MM-dd}' -f $p.LastUseTime } else { 'n/a' }
    $line = '{0} | {1} | lastuse={2} | loaded={3}' -f $name, $p.LocalPath, $last, $p.Loaded
    if ($sizes -and $p.LocalPath -and (Test-Path -LiteralPath $p.LocalPath)) {
        $line += ' | size={0:N0} MB' -f ((Get-DirBytes $p.LocalPath) / 1MB)
    }
    Write-Output $line
}
exit 0

#!/bin/bash
# Tail the agent log (/var/log/ulrmm-agent.log). LINES (100): 1-2000.
# Exit: 0 printed, 1 log missing, 3 bad input, not macOS or not root.
PATH=/usr/bin:/bin:/usr/sbin:/sbin
export PATH
set -u

lines=${LINES:-100}
log=/var/log/ulrmm-agent.log

{ [ "$(uname -s)" = Darwin ] && [ "$(id -u)" -eq 0 ]; } || { echo "Needs macOS and root."; exit 3; }
case "$lines" in '' | *[!0-9]*) echo "LINES must be a whole number."; exit 3 ;; esac
[ "$lines" -ge 1 ] && [ "$lines" -le 2000 ] || { echo "LINES must be 1-2000."; exit 3; }

[ -f "$log" ] || { echo "$log does not exist."; exit 1; }
echo "$log, last $lines lines ($(stat -f%z "$log") bytes)"
tail -n "$lines" "$log" | cut -c1-2000
exit 0

#!/bin/bash
# Disk space of the data volume. WARN_PERCENT (85), ERROR_PERCENT (95): used space of the APFS container.
# Exit: 0 ok, 1 at or above ERROR_PERCENT, 2 at or above WARN_PERCENT, 3 bad input or not macOS.
PATH=/usr/bin:/bin:/usr/sbin:/sbin
export PATH
set -u

warn=${WARN_PERCENT:-85}
err=${ERROR_PERCENT:-95}

[ "$(uname -s)" = Darwin ] || { echo "Not macOS."; exit 3; }
case "$warn$err" in *[!0-9]*) echo "WARN_PERCENT and ERROR_PERCENT must be whole numbers."; exit 3 ;; esac
[ -n "$warn" ] && [ -n "$err" ] && [ "$warn" -ge 1 ] && [ "$err" -le 100 ] && [ "$warn" -le "$err" ] ||
  { echo "Need 1 <= WARN_PERCENT <= ERROR_PERCENT <= 100."; exit 3; }

mnt=/System/Volumes/Data
[ -d "$mnt" ] || mnt=/
# On APFS the size and available columns are those of the whole container, the used column
# is only this volume. Used percent is taken from container size and free space.
line=$(df -k -P "$mnt" 2>/dev/null | awk 'NR==2 {print $(NF-4), $(NF-2)}')
size=${line% *}
avail=${line#* }
case "${size}x${avail}" in *[!0-9x]* | x* | *x) echo "Could not read df for $mnt."; exit 3 ;; esac
[ "$size" -gt 0 ] || { echo "Could not read df for $mnt."; exit 3; }

pct=$(awk -v s="$size" -v a="$avail" 'BEGIN { printf "%d", ((s - a) * 100 + s - 1) / s }')
gb() { awk -v k="$1" 'BEGIN { printf "%.1f", k / 1048576 }'; }

verdict="OK"
rc=0
if [ "$pct" -ge "$err" ]; then verdict="CRITICAL"; rc=1; elif [ "$pct" -ge "$warn" ]; then verdict="WARNING"; rc=2; fi
echo "$verdict: $mnt is $pct% used ($(gb "$avail") GB free of $(gb "$size") GB)"
echo "Thresholds: warn $warn%, error $err%. Purgeable space counts as used."
exit $rc

#!/bin/bash
# System integrity report: SIP, authenticated root volume, Gatekeeper. No variables.
# Exit: 0 all protections on, 1 SIP or Gatekeeper off, 2 custom SIP configuration, 3 not macOS.
PATH=/usr/bin:/bin:/usr/sbin:/sbin
export PATH
set -u

[ "$(uname -s)" = Darwin ] || { echo "Not macOS."; exit 3; }

sip=$(csrutil status 2>&1 | head -n 3 | tr '\n' ' ')
gk=$(spctl --status 2>&1 | head -n 1)
authroot=$(csrutil authenticated-root status 2>&1 | head -n 1)

rc=0
case "$sip" in
*"(Custom Configuration)"*) rc=2 ;;
*"status: enabled"*) ;;
*) rc=1 ;;
esac
case "$gk" in
*"assessments enabled"*) ;;
*) rc=1 ;;
esac

case $rc in
0) echo "System integrity protections are on." ;;
2) echo "SIP is on with a custom configuration." ;;
*) echo "SIP or Gatekeeper is off or unreadable." ;;
esac
echo "SIP: $sip"
echo "Gatekeeper: $gk"
echo "Authenticated root volume: $authroot"
echo "Secure boot level: not read (Apple silicon needs recoveryOS, Intel the Startup Security Utility)."
exit $rc

# Rotates the password of a local administrator account, creating it when missing. The password is never printed.
# Variables: TARGET_USER, NEW_PASSWORD, CREATE_IF_MISSING (checkbox, default true)
# Exit: 0 password set, 1 change failed, 3 bad input or account not found
$ErrorActionPreference = 'Stop'
function Finish([string]$msg, [int]$code) {
    [Console]::Out.WriteLine($msg)
    exit $code
}
$name = ([string]$env:TARGET_USER).Trim()
$password = [string]$env:NEW_PASSWORD
$createRaw = ([string]$env:CREATE_IF_MISSING).Trim().ToLower()
if (-not $createRaw) { $createRaw = 'true' }
if ($createRaw -ne 'true' -and $createRaw -ne 'false') { Finish 'CREATE_IF_MISSING must be true or false' 3 }
$create = $createRaw -eq 'true'
if ($name -cnotmatch '^[a-z][a-z0-9_-]{0,19}$') {
    Finish 'Bad or missing TARGET_USER' 3
}
if ($password.Length -lt 8 -or $password.Length -gt 128) { Finish 'NEW_PASSWORD must be 8-128 characters' 3 }
if (-not (Get-Command New-LocalUser -ErrorAction SilentlyContinue)) {
    Finish 'The LocalAccounts cmdlets are not available on this system' 3
}
$created = $false
try {
    $secure = ConvertTo-SecureString -String $password -AsPlainText -Force
    $u = Get-LocalUser -Name $name -ErrorAction SilentlyContinue
    if (-not $u) {
        if (-not $create) { Finish ('Local account not found: ' + $name) 3 }
        $u = New-LocalUser -Name $name -Password $secure -PasswordNeverExpires -AccountNeverExpires
        $created = $true
        try {
            Add-LocalGroupMember -SID 'S-1-5-32-544' -Member $name
        } catch {
            Remove-LocalUser -Name $name -ErrorAction SilentlyContinue
            throw
        }
    } else {
        if ($u.SID.Value -match '-500$' -eq $false -and -not $u.Enabled) {
            Finish ('Refusing to rotate ' + $name + ': the account is disabled') 3
        }
        Set-LocalUser -Name $name -Password $secure -PasswordNeverExpires $true
    }
} catch {
    Finish ('FAIL: ' + $_.Exception.Message) 1
}
Finish ('Password of ' + $name + ' rotated, created=' + $created) 0

$networkstatus = Get-NetConnectionProfile | Select NetworkCategory | Out-String

if ($networkstatus.Contains("DomainAuthenticated")) {
    exit 0
} else {
    exit 1
}

$pools = Get-VirtualDisk | select -ExpandProperty HealthStatus

$err = $False

ForEach ($pool in $pools) {
    if ($pool -ne "Healthy") {
        $err = $True
    }
}

if ($err) {
    exit 1
} else {
    exit 0
}

